(window.GIM_TP=window.GIM_TP||{})["Z.HaAzinu.0"]={"from":0,"a":[[[],[],[]],[["(דברים לב) הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי, רִבִּי יְהוּדָה פָּתַח, (שיר השירים ה) פָּתַחְתִּי אֲנִי לְדוֹדִי וְדוֹדִי חָמַק עָבָר וְגוֹ', בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ קְרָאתִיו וְלָא עָנָנִי. מַה כְּתִיב לְעֵילָּא. אֲנִי יְשֵׁנָה וְלִבִּי עֵר וְגוֹ'. אֲנִי יְשֵׁנָה, אָמְרָה כְּנֶסֶת יִשְׂרָאֵל. אֲנִי יְשֵׁנָה, מִפִּקּוּדֵי אוֹרַיְיתָא, בְּזִמְנָא דַּאֲזִילְנָא בְּמַדְבְּרָא. וְלִבִּי עֵר, לְאַעֲלָא לְאַרְעָא, לְמֶעְבַּד לְהוּ (נימוסין) דְּהָא כָּל פִּקּוּדֵי אוֹרַיְיתָא בְּאַרְעָא מִשְׁתַּכְּחִין. קוֹל דּוֹדִי דוֹפֵק, דָּא מֹשֶׁה. דְּאוֹכַח לְהוּ לְיִשְׂרָאֵל בְּכַמָּה וִיכּוּחִין, בְּכַמָּה קְטָטִין. דִּכְתִּיב, (דברים א) אֵלֶּה הַדְּבָרִים וְגוֹ', (דברים ט) מַמְרִים הֱיִיתֶם וְגוֹ'. (דברים ט) וּבְחוֹרֵב הִקְצַפְתֶּם וְגוֹ'. הֲדָא הוּא דִכְתִיב, (שיר השירים ה) דוֹפֵק.","וְעִם כָּל דָּא דְּמֹשֶׁה אוֹכַח לְהוּ לְיִשְׂרָאֵל, בִּרְחִימוּתָא הֲווֹ כָּל מִלּוֹי, דִּכְתִּיב, (דברים ז׳:ו׳) כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ' אֱלֹהֶיךָ. וּבְךָ בָּחַר יְיָ' אֱלֹהֶיךָ לִהְיוֹת לוֹ לְעָם וְגוֹ' (דברים י״ד:ב׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ'. וְעַל דָּא (דברים כ״ז:י׳) וְשָׁמַעְתָּ בְּקוֹל יְיָ' אֱלֹהֶיךָ. (דברים ז׳:ח׳) כִּי מֵאַהֲבַת יְיָ' אֶתְכֶם. הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:ב׳) פִּתְחִי לִי אֲחוֹתִי רַעְיָתִי.","מַה כְּתִיב. (שם) קַמְתִּי אֲנִי לִפְתּוֹחַ לְדוֹדִי, אָמְרוּ יִשְׂרָאֵל בְּעוֹד דַּהֲוֵינָן זְמִינִין לְמֵיעַל לְאַרְעָא, וּלְקַבְּלָא אִינּוּן פִּקּוּדֵי אוֹרַיְיתָא עַל יְדוֹי דְּמֹשֶׁה. מַה כְּתִיב, (שם) וְדוֹדִי חָמַק עָבָר. דִּכְתִּיב, (דברים ל״ד:ה׳) וַיָּמָת שָׁם מֹשֶׁה עֶבֶד יְיָ'. בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ, דִּכְתִּיב וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. קְרָאתִיו וְלֹא עָנָנִי, דְּלָא הֲוָה דָּרָא כְּדָרָא דְּמֹשֶׁה, דְקוּדְשָׁא בְּרִיךְ הוּא שָׁמַע לְקַלֵיהוֹן, וְעָבַד לְהוּ נִסִּין וְנִימוּסִין, כְּמָה דְּעָבַד עַל יְדוֹי.","רִבִּי יִצְחָק אָמַר, קַמְתִּי אֲנִי לִפְתּוֹחַ לְדוֹדִי, דָּא קוּדְשָׁא בְּרִיךְ הוּא בְּיוֹמוֹי דְּמֹשֶׁה, דְּכָל יוֹמוֹי לָא בָּעָא דְּמַלְאָכָא וּשְׁלִיחָא לְדַבְּרָא עִמֵּיהּ, דִּכְתִּיב, (שמות ל״ג:ט״ו) אִם אֵין פָּנֶיךָ הוֹלְכִים וְגוֹ'. זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְקוּדְשָׁא בְּרִיךְ הוּא אִסְתְּכַם לִרְעוּתֵיהּ. וְדוֹדִי חָמַק עָבָר, בְּיוֹמוֹי דִּיהוֹשֻׁעַ, דִּכְתִּיב, (יהושע ה׳:י״ד) לֹא כִּי אֲנִי שַׂר צְבָא יְיָ'.","תָּא חֲזֵי, מֹשֶׁה הֲוָה שָׁמַע קָלָא קַדִּישָׁא דְּמַלְכָּא עִלָּאָה, וְלָא אִזְדַּעְזָע, וְכָּל שֶׁכֵּן מַלְאָכָא, דְּלָא בָּעָא (ולא קבליה). בָּתַר דְּשָׁכִיב מַה כְּתִיב. וַיֹּאמֶר לֹא כִּי אֲנִי שַׂר צְבָא יְיָ'. וּכְתִיב (שם) וַיִּפּוֹל יְהוֹשֻׁעַ אֶל פָּנָיו אַרְצָה. עַתָּה בָאתִי, בְּיוֹמוֹי דְּמֹשֶׁה רַבָּךְ אֲתֵינָא, וְלָא קִבְּלָּנִי. בֵּיהּ שַׁעֲתָא, יָדְעוּ יִשְׂרָאֵל שְׁבָחָא דְּמֹשֶׁה. בְּהַהוּא זִמְנָא בָּעוּ יִשְׂרָאֵל לְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִזְדְּמַן לְהוּ הָכִי כְּיוֹמוֹי דְּמֹשֶׁה, הֲדָא הוּא דִכְתִיב בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ וְגוֹ'.","(דברים ל״ב:א׳) הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, רִבִּי חִיָּיא אָמַר, זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, יַתִּיר מִכָּל נְבִיאֵי עָלְמָא. תָּא חֲזֵי, כְּתִיב (ישעיהו א׳:ב׳) שִׁמְעוּ שָׁמַיִם וְהַאֲזִינִי אֶרֶץ כִּי יְיָ' דִּבֵּר. שִׁמְעוּ שָׁמַיִם, יְשַׁעְיָה דְּהֲוָה יַתִּיר רְחִיקָא מִמַּלְכָּא, כְּתִיב שִׁמְעוּ שָׁמַיִם. מֹשֶׁה דְּהֲוָה יַתִּיר קָרִיב לְמַלְכָּא, כְּתִיב הַאֲזִינוּ הַשָּׁמַיִם.","תָּאנָא, בְּהַהוּא זִמְנָא דְּאָמַר יְשַׁעְיָהוּ שִׁמְעוּ שָׁמַיִם וְהַאֲזִינִי אֶרֶץ. כַּמָה גַּרְדִּינֵי טְהִירִין אִזְדְּמָנוּ לְתַּבְרָא רֵישֵׁיהּ, נָפְקָא קָלָא וְאָמַר, מַאן הוּא דֵּין דְּבָעֵי לְאַרְעֲשָׁא עָלְמִין. עַד דְּפָתַח וְאָמַר, לָאו אֲנָא, וְלָאו דִּידִי, אֶלָּא כִּי יְיָ' דִּבֵּר, וְלָא אֲנָא. בְּמֹשֶׁה מַה כְּתִיב. הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, אֲנָא וְלָא אַחֲרָא. וַאֲדַבֵּרָה בְּלָא דְּחִילוּ. וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי, וְלָא מֵאַחֲרָא. זַכָּאָה חוּלָקֵיהּ. אָמַר רִבִּי אַבָּא, בְּאַתְוָון גְּלִיפָן דְּרִבִּי אֶלְעָזָר, הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ, הָכָא אִתְרְמִיז שְׁמָא קַדִּישָׁא עִלָּאָה.","רִבִּי יוֹסֵי אָמַר, תּוּ מַה בֵּין מֹשֶׁה לִישַׁעְיָהוּ. מֹשֶׁה אָמַר הַאֲזִינוּ הַשָּׁמַיִם, הַשָּׁמַיִם, שָׁמַיִם עִלָּאִין, אִינּוּן דְּאִשְׁתְּמוֹדְעָן, דְּאִקְרוּן שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא. וְתִשְׁמַע הָאָרֶץ, אֶרֶץ עִלָּאָה, הַהִיא דְּאִשְׁתְּמוֹדְעָא, וְאִיהִי אֶרֶץ הַחַיִּים. בִּישַׁעְיָה כְּתִיב, שִׁמְעוּ שָׁמַיִם וְלָא הַשָּׁמַיִם. הַאֲזִינִי אֶרֶץ, וְלָא הָאָרֶץ. וְאִינּוּן שָׁמַיִם וָאָרֶץ תַּתָּאִין. וְעִם כָּל דָּא, בָּעוּ לְאַעְנְשָׁא לֵיהּ, עַד דְּאָמַר כִּי יְיָ' דִּבֵּר, וְלֹא אֲנָא. וּמֹשֶׁה אָמַר כּוּלֵי הַאי, דִּכְתִּיב הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי.","רִבִּי יִצְחָק פָּתַח, (שיר השירים ב׳:ג׳) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל מִכָּל עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּהָא כָּל שְׁאַר עַמִּין אִתְיְהִיבוּ לְרַבְרְבָן מְמָנָן, בְּשֻׁלְטָנוּתָא עָלַיְיהוּ. וְיִשְׂרָאֵל קַדִּישִׁין, זַכָּאָה חוּלָקֵיהוֹן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, דְּלָא יָהַב לוֹן קוּדְשָׁא בְּרִיךְ הוּא לָא לְמַלְאָכָא, וְלָא לְשָׁלִיטָא אַחֲרָא, אֶלָּא הוּא אָחִיד לוֹן לְחוּלָקֵיהּ, הֲדָא הוּא דִכְתִיב כִּי חֵלֶק יְיָ' עַמּוֹ. וּכְתִיב, (תהילים קל״ה:ד׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר, מַה תַּפּוּחַ מִתְפָּרְשָׁא בִּגְוָונוֹי, עַל כָּל שְׁאַר אִילָנֵי חַקְלָא, כַּךְ קוּדְשָׁא בְּרִיךְ הוּא מִתְפְּרַשׁ וְאִתְרְשִׁים עַל כָּל חֵילִין עִלָּאִין וְתַתָּאִין, בְּגִין כָּךְ (ישעיהו מ״ח:ב׳) יְיָ' צְבָאוֹת שְׁמוֹ, אוֹת הוּא בְּכָל חֵילָא דִּלְעֵילָּא.","תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא כְּתַפּוּחַ, דְּאִית בֵּיהּ תְּלַת גַּוְונִין. כְּנֶסֶת יִשְׂרָאֵל כְּשׁוֹשַׁנָּה. מַאן שׁוֹשַׁנָה. אָמַר רִבִּי אַבָּא, שׁוֹשַׁנָה סְתָם, שׁוֹשַׁנָה דְּאִתְכְּלִילַת בְּשִׁית טַרְפֵּי, שׁוֹשַׁנָה דָּא גְּוָונֵיהּ חִוָּור וְסוּמָק. וְכֹלָּא הוּא תְּרֵין גְּוָונֵי, סוּמָק וְחִוָּור, הָכִי כְּנֶסֶת יִשְׂרָאֵל.","קוּדְשָׁא בְּרִיךְ הוּא כְּתַפּוּחַ, כְּנֶסֶת יִשְׂרָאֵל כְּשׁוֹשַׁנָּה. דְּהָכִי אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, (שיר השירים ח׳:ה׳) תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךָ. תַּחַת הַתַּפּוּחַ בְּאָן אֲתָר הִיא. אֶלָּא אִלֵּין אֲבָהָתִין דְּאַמָרָן. רִבִּי יוֹסֵי אָמַר, דָּא יוֹבְלָא. רִבִּי אַבָּא אָמַר, כֹּלָּא שַׁפִּיר, אֶלָּא אִלֵּין אֲבָהָן דְּקָאַמְרָן, אִלֵּין אִינּוּן ג' גְּוָונֵי, דְּמִתְחַבְּרָן בַּתַפּוּחַ."],[[0,"האזינו השמים ואדברה וגו':","ר' יהודה פתח, פתחתי אני לדודי, ודודי חמק עבר וגו'. בקשתיהו ולא מצאתיהו קראתיו ולא ענני. מה כתוב למעלה אני ישנה ולבי ער וגו'. \u0003אני ישנה\u0004, אמרה כנסת ישראל \u0003אני ישנה\u0004, ממצות התורה בזמן שהלכתי במדבר. \u0003ולבי ער\u0004, וגו', להביאם לארץ לעשות להם חוקים, כי כל מצות התורה נמצאות בארץ. \u0003קול דודי דופק\u0004, זה משה, שהוכיח את ישראל בכמה ויכוחים בכמה מריבות. שכתוב אלה הדברים וגו', ממרים הייתם וגו'. ובחרב הקצפתם וגו'. ז\"ש. דופק."],[1,"ועכ\"ד דמשה אוכח וכו':","ועם כל זה, שמשה הוכיח לישראל, כל דבריו באהבה היו, שכתוב, כי עם קדוש אתה לה' אלקיך ובך בחר ה' אלקיך להיות לו לעם וגו'. בנים אתם לה' אלקיכם. ואתם הדבקים בה'. ועל כן, ושמעת בקול ה' אלקיך. כי מאהבת ה' אתכם. ז\"ש, פתחי לי אחותי רעיתי, בלשון חיבה."],[2,"מה כתיב קמתי וגו':","מה כתוב, קמתי אני לפתוח לדודי. אמרו ישראל, בעוד שהיינו מוכנים ליכנס לארץ ולקבל מצות התורה על ידי משה, מה כתוב, ודודי חמק עבר, שכתוב, וימת שם משה עבד ה'. בקשתיהו ולא מצאתיהו, שכתוב, ולא קם נביא עוד בישראל כמשה. קראתיו ולא ענני, שלא היה דור כדורו של משה, שהקב\"ה שמע לקולם, ועשה להם נסים וחוקים, כמו שעשה על ידיו."],[3,"ר' יצחק אמר וכו':","רי\"א, קמתי אני לפתוח לדודי זה הקב\"ה בימיו של משה, שכל ימיו לא רצה שמלאך ושליח ינהג עמו. שכתוב, אם אין פניך הולכים וגו'. אשרי חלקו של משה, שהקב\"ה הסכים לרצונו. ודודי חמק עבר. היינו בימיו של יהושע, שכתוב, לא כי אני שר צבא ה'."],[4,"ת\"ח משה הוה וכו':","בוא וראה, משה היה שומע את קול הקדוש של מלך העליון ולא נזדעזע, וכל שכן מלאך, שלא רצה לקבלו. אחר שמת מה כתוב, ויאמר לא כי אני שר צבא ה'. וכתוב ויפול יהושע אל פניו ארצה. \u0003עתה באתי\u0004, בימיו של משה רבך באתי, ולא קבלו אותי. בה בשעה, ידעו ישראל שבחו של משה. בעת ההיא בקשו ישראל את הקב\"ה ולא נזדמן להם כך, כבימיו של משה. ז\"ש, בקשתיהו ולא מצאתיהו וגו'."],[5,"האזינו השמים ואדברה:","ר' חייא אמר, אשרי חלקו של משה יותר מכל נביאי העולם. בוא וראה, כתוב, שמעו שמים והאזיני ארץ כי ה' דבר. \u0003שמעו שמים\u0004, הנה ישעיה שהיה יותר רחוק מן המלך, כתוב, שמעו שמים. משה שהיה יותר קרוב למלך, כתוב \u0003האזינו השמים\u0004."],[6,"תאנא בהאי זמנא וכו':","למדנו באותה שעה שאמר ישעיהו, \u0003שמעו שמים והאזיני ארץ\u0004, כמה בעלי דין נזדמנו לשבור ראשו, יצא קול ואמר, מי הוא זה שרוצה להרעיש עולמות. עד שפתח ואמר לא אני ולא שלי אלא \u0003כי ה' דבר\u0004, ולא אני. במשה מה כתוב, האזינו השמים ואדברה, אני ולא אחר. \u0003ואדברה\u0004, בלא פחד. ותשמע הארץ אמרי פי, ולא מאחר. אשרי חלקו. א\"ר אבא באותיות חקוקות דר' אלעזר, אמר, האז \u0003י\u0004 נו \u0003ה\u0004 שמים \u0003ו\u0004 אדברה ותשמע \u0003ה\u0004 ארץ כאן נרמז שם הקדוש העליון. דהיינו ה \u0003י'\u0004 שבהאזינו, \u0003ה'\u0004 שבהשמים, \u0003ו'\u0004 של ואדברה. \u0003ה'\u0004 שבהארץ."],[7,"ר' יוסי אמר וכו':","רי\"א. עוד מה בין משה לישעיהו, משה אמר \u0003האזינו השמים\u0004 עם ה' הידיעה, השמים, היינו השמים העליונים אלו הנודעים, הנקראים שמו של הקב\"ה. \u0003ותשמע הארץ\u0004, היינו ארץ העליונה, אותה שנודעת, שהיא ארץ החיים, דהיינו מלכות. בישעיהו כתוב, שמעו שמים ולא השמים. האזיני ארץ, ולא הארץ. כי הם שמים וארץ תחתונים. ועם כל זה, רצו להענישו, עד שאמר, כי ה' דבר, ולא אני. ומשה אמר כל כך, שכתוב האזינו השמים ואדברה ותשמע הארץ אמרי פי, שהם ז\"א ומלכות כנ\"ל, ולא פחד, ולא רצו להענישו."],[8,"ר' יצחק פתח כתפוח וגו':","רי\"פ, כתפוח בעצי היער וגו'. אשרי חלקם של ישראל מכל העמים עכו\"ם, כי כל שאר העמים ניתנו לשרים ממונים שישלטו עליהם. וישראל הקדושים, אשרי חלקם בעולם הזה ובעולם הבא, שלא נתן אותם הקב\"ה לא למלאך ולא לשליט אחר, אלא הוא אחז אותם לחלקו. ז\"ש, כי חלק ה' עמו. וכתוב, כי יעקב בחר לו יה. \u0003כתפוח בעצי היער\u0004, מה תפוח נבדל בצבעיו מכל שאר אילנות השדה, כך הקב\"ה נבדל ונרשם על כל הצבאות העליונים והתחתונים. משום זה ה' צבאות שמו. שפירושו, אות הוא בכל הצבא שלמעלה."],[9,"ת\"ח קב\"ה כתפוח וכו':","בוא וראה, הקב\"ה הוא כמו תפוח, שיש בו ג' צבעים לבן אדום ירוק. הרומזים על חסד גבורה ת\"ת. כנסת ישראל, שהיא המלכות, היא כשושנה. מהי שושנה. א\"ר אבא שושנה סתם, שושנה שנכללת מששה עלים, שושנה זו צבעיה לבן ואדום. וכולו הוא ב' צבעים אדום ולבן המורים על דין וחסד. כך היא כנסת ישראל. שהיא המלכות."],[10,"קב\"ה כתפוח כ\"י וכו':","הקב\"ה הוא כתפוח. כנסת ישראל היא כשושנה. כי כך אמרה כנסת ישראל, תחת התפוח עוררתיך. שואל תחת התפוח, באיזה מקום הוא. ומשיב, אלא אלו הם האבות שאמרנו, שהם חג\"ת הנקראים אבות. ר' יוסי אומר זה יובל. דהיינו בינה, שנקראת תפוח. ר' אבא אמר הכל יפה, כי אלו האבות שאמרנו, הם ג' צבעים שמתחברים בתפוח. פירוש, שהם בחינת ג' קוין שבבינה, והם בחינת חג\"ת שבז\"א. וע\"כ אפשר לומר שתפוח הוא ז\"א. ואפשר לומר שהוא בינה."]],[[0,"","הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי [דברים לב]. רַבִּי יְהוּדָה פָּתַח, [שיר השירים ה] פָּתַחְתִּי אֲנִי לְדוֹדִי וְדוֹדִי חָמַק עָבָר וְגוֹ', בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ קְרָאתִיו וְלֹא עָנָנִי. מַה כָּתוּב לְמַעְלָה? אֲנִי יְשֵׁנָה וְלִבִּי עֵר וְגוֹ'. אֲנִי יְשֵׁנָה. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, אֲנִי יְשֵׁנָה – מִמִּצְווֹת הַתּוֹרָה, בִּזְמַן שֶׁהָלַכְתִּי בַמִּדְבָּר. וְלִבִּי עֵר – לַעֲלוֹת לָאָרֶץ, לַעֲשׂוֹת אוֹתָם [חובות], שֶׁהֲרֵי כָּל מִצְווֹת הַתּוֹרָה נִמְצָאוֹת בָּאָרֶץ. קוֹל דּוֹדִי דוֹפֵק – זֶה מֹשֶׁה, שֶׁהוֹכִיחַ לָהֶם לְיִשְׂרָאֵל בְּכַמָּה וִכּוּחִים, בְּכַמָּה מְרִיבוֹת, שֶׁכָּתוּב [דברים א] אֵלֶּה הַדְּבָרִים וְגוֹ', [שם ט] מַמְרִים הֱיִיתֶם וְגוֹ', [שם] וּבְחֹרֵב הִקְצַפְתֶּם וְגוֹ'. זֶהוּ שֶׁכָּתוּב דּוֹפֵק."],[1,"","וְעִם כָּל זֶה שֶׁמֹּשֶׁה הוֹכִיחַ לָהֶם לְיִשְׂרָאֵל, בְּאַהֲבָה הָיוּ כָּל דְּבָרָיו, שֶׁכָּתוּב [דברים ז] כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ, [שם יד] וּבְךְ בָּחַר ה' אֱלֹהֶיךְ לִהְיוֹת לוֹ לְעַם וְגוֹ', בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם, [שם ד] וְאַתֶּם הַדְּבֵקִים בַּה'. וְעַל זֶה [שם כז] וְשָׁמַעְתָּ בְּקוֹל ה' אֱלֹהֶיךְ. [שם ז] כִּי מֵאַהֲבַת ה' אֶתְכֶם. זֶהוּ שֶׁכָּתוּב [שיר השירים ה] פִּתְחִי לִי אֲחֹתִי רַעְיָתִי."],[2,"","מַה כָּתוּב? [שם] קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי. אָמְרוּ יִשְׂרָאֵל, בְּעוֹד שֶׁהָיִינוּ מְזֻמָּנִים לַעֲלוֹת לָאָרֶץ וּלְקַבֵּל מִצְווֹת הַתּוֹרָה הָאֵלּוּ עַל יְדֵי מֹשֶׁה, מַה כָּתוּב? [שם] וְדוֹדִי חָמַק עָבָר, שֶׁכָּתוּב [דברים לד] וַיָּמָת שָׁם מֹשֶׁה עֶבֶד ה'. בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ, שֶׁכָּתוּב וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. קְרָאתִיו וְלֹא עָנָנִי, שֶׁלֹּא הָיָה דוֹר כְּדוֹרוֹ שֶׁל מֹשֶׁה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁמַע לְקוֹלָם וְעָשָׂה לָהֶם נִסִּים וְחֻקִּים, כְּמוֹ שֶׁעָשָׂה עַל יָדָיו."],[3,"","רַבִּי יִצְחָק אָמַר, קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי – זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָמָיו שֶׁל מֹשֶׁה, שֶׁכָּל יָמָיו לֹא רָצָה שֶׁמַּלְאָךְ אוֹ שָׁלִיחַ לְהַנְהִיג עִמּוֹ, שֶׁכָּתוּב [שמות לג] אִם אֵין פָּנֶיךְ הֹלְכִים וְגוֹ'. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַסְכִּים לִרְצוֹנוֹ. וְדוֹדִי חָמַק עָבָר, בְּיָמָיו שֶׁל יְהוֹשֻׁעַ, שֶׁכָּתוּב [יהושע ה] לֹא כִּי אֲנִי שַׂר צְבָא ה'."],[4,"","בֹּא רְאֵה, מֹשֶׁה הָיָה שׁוֹמֵעַ קוֹל קָדוֹשׁ שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן וְלֹא נִזְדַּעֲזַע, וְכָל שֶׁכֵּן מַלְאָךְ שֶׁלֹּא רָצָה [ולא קבלו]. אַחַר שֶׁמֵּת מֹשֶׁה, מַה כָּתוּב? וַיֹּאמֶר לֹא כִּי אֲנִי שַׂר צְבָא ה'. וְכָתוּב [שם] וַיִּפֹּל יְהוֹשֻׁעַ אֶל פָּנָיו אַרְצָה. עַתָּה בָאתִי, בְּיָמָיו שֶׁל מֹשֶׁה רַבְּךְ בָּאתִי וְלֹא קִבְּלַנִי. בְּאוֹתָהּ שָׁעָה יָדְעוּ יִשְׂרָאֵל שִׁבְחוֹ שֶׁל מֹשֶׁה. בְּאוֹתוֹ זְמַן בִּקְּשׁוּ יִשְׂרָאֵל לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא נִזְדַּמֵּן לָהֶם כָּךְ כְּבִימֵי מֹשֶׁה. זֶהוּ שֶׁכָּתוּב בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ וְגוֹ'."],[5,"","הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה [דברים לב]. רַבִּי חִיָּיא אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה יוֹתֵר מִכָּל נְבִיאֵי הָעוֹלָם. בֹּא רְאֵה, כָּתוּב [ישעיה א] שִׁמְעוּ שָׁמַיִם וְהַאֲזִינִי אֶרֶץ כִּי ה' דִּבֵּר. שִׁמְעוּ שָׁמַיִם. יְשַׁעְיָה שֶׁהָיָה רָחוֹק יוֹתֵר מֵהַמֶּלֶךְ, כָּתוּב שִׁמְעוּ שָׁמַיִם. מֹשֶׁה שֶׁהָיָה קָרוֹב יוֹתֵר לַמֶּלֶךְ, כָּתוּב הַאֲזִינוּ הַשָּׁמַיִם."],[6,"","לָמַדְנוּ, בְּאוֹתוֹ זְמַן שֶׁאָמַר יְשַׁעְיָהוּ שִׁמְעוּ שָׁמַיִם וְהַאֲזִינִי אֶרֶץ, כַּמָּה בַּעֲלֵי דִינִים מְאִירִים הִזְדַּמְּנוּ לִשְׁבֹּר אֶת רֹאשׁוֹ. יָצָא קוֹל וְאָמַר: מִי הוּא זֶה שֶׁרוֹצֶה לְהַרְעִישׁ עוֹלָמוֹת? עַד שֶׁפָּתַח וְאָמַר: לֹא אֲנִי וְלֹא שֶׁלִּי, אֶלָּא כִּי ה' דִּבֵּר, וְלֹא אֲנִי. בְּמֹשֶׁה מַה כָּתוּב? הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, אֲנִי וְלֹא אַחֵר. וַאֲדַבֵּרָה – בְּלֹא פַחַד. וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי – וְלֹא מֵאַחֵר. אַשְׁרֵי חֶלְקוֹ. אָמַר רַבִּי אַבָּא, בְּאוֹתִיּוֹת חֲקוּקוֹת שֶׁל רַבִּי אֶלְעָזָר, הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ – כָּאן נִרְמָז שֵׁם הַקָּדוֹשׁ הָעֶלְיוֹן."],[7,"","רַבִּי יוֹסֵי אָמַר, עוֹד מַה בֵּין מֹשֶׁה לִישַׁעְיָהוּ? מֹשֶׁה אָמַר הַאֲזִינוּ הַשָּׁמַיִם. הַשָּׁמַיִם – הַשָּׁמַיִם הָעֶלְיוֹנִים, אֵלּוּ הַנּוֹדָעִים, שֶׁנִּקְרָאִים שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְתִשְׁמַע הָאָרֶץ – הָאָרֶץ הָעֶלְיוֹנָה, אוֹתָהּ הַנּוֹדַעַת, וְהִיא אֶרֶץ הַחַיִּים. בִּישַׁעְיָה כָתוּב שִׁמְעוּ שָׁמַיִם, וְלֹא הַשָּׁמַיִם. הַאֲזִינִי אֶרֶץ, וְלֹא הָאָרֶץ. וְאֵלּוּ שָׁמַיִם וְאֶרֶץ תַּחְתּוֹנִים. וְעִם כָּל זֶה רָצוּ לְהַעֲנִישׁ אוֹתוֹ, עַד שֶׁאָמַר כִּי ה' דִּבֵּר, וְלֹא אֲנִי. וּמֹשֶׁה אָמַר כָּל זֶה, שֶׁכָּתוּב הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי."],[8,"","רַבִּי יִצְחָק פָּתַח, [שיר השירים ב] כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מִכָּל אֻמּוֹת עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, שֶׁהֲרֵי כָּל שְׁאָר הָאֻמּוֹת נִתְּנוּ לְשָׂרִים מְמֻנִּים שַׁלִּיטִים עֲלֵיהֶם. וְיִשְׂרָאֵל קְדוֹשִׁים, אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁלֹּא נָתַן אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא לְמַלְאָךְ וְלֹא לְשַׁלִּיט אַחֵר, אֶלָּא הוּא יִחֵד אוֹתָם לְחֶלְקוֹ. זֶהוּ שֶׁכָּתוּב כִּי חֵלֶק ה' עַמּוֹ, וְכָתוּב [תהלים קלה] כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר, מַה תַּפּוּחַ מִתְחַלֵּק בִּגְוָנָיו עַל כָּל שְׁאָר עֲצֵי הַשָּׂדֶה, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְחַלֵּק וְנִרְשָׁם עַל כָּל חֲיָלוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים, מִשּׁוּם זֶה [ישעיה מח] ה' צְבָאוֹת שְׁמוֹ, אוֹת הוּא בְּכָל צָבָא שֶׁל מַעְלָה."],[9,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא כְּתַפּוּחַ, שֶׁיֵּשׁ בּוֹ שְׁלֹשָׁה גְוָנִים. כְּנֶסֶת יִשְׂרָאֵל כְּמוֹ שׁוֹשַׁנָּה. אֵיזוֹ שׁוֹשַׁנָּה? אָמַר רַבִּי אַבָּא, שׁוֹשַׁנָּה מֻקֶּפֶת, סְתָם שׁוֹשַׁנָּה שֶׁנִּכְלֶלֶת בְּשִׁשָּׁה עָלִים. שׁוֹשַׁנָּה זוֹ גְּוָנֶיהָ לָבָן וְאָדם, וְהַכֹּל הוּא בִּשְׁנֵי גְוָנִים – אָדם וְלָבָן. כָּךְ כְּנֶסֶת יִשְׂרָאֵל."],[10,"","הַקָּדוֹשׁ בָּרוּךָ הוּא כְּמוֹ תַפּוּחַ, כְּנֶסֶת יִשְׂרָאֵל כְּמוֹ שׁוֹשַׁנָּה. שֶׁכָּךְ אָמְרָה כְנֶסֶת יִשְׂרָאֵל, [שיר השירים ח] תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךְ. תַּחַת הַתַּפּוּחַ – בְּאֵיזֶה מָקוֹם זֶה? אֶלָּא אֵלּוּ הָאָבוֹת שֶׁאָמַרְנוּ. רַבִּי יוֹסֵי אָמַר, זֶה יוֹבֵל. רַבִּי אַבָּא אָמַר, הַכֹּל יָפֶה, אֶלָּא אֵלּוּ הָאָבוֹת שֶׁאָנוּ אוֹמְרִים, אֵלּוּ הֵם שְׁלֹשָׁה גְוָנִים שֶׁמִּתְחַבְּרִים בַּתַּפּוּחַ."]]],[["רִבִּי יִצְחָק אָמַר, בְּאָן אֲתָר אִתְכְּלִילַת כְּנֶסֶת יִשְׂרָאֵל בְּשׁוֹשַׁנָּה. בְּאִינּוּן נְשִׁיקִין דִּרְחִימוּתָא, דְּאִתְדְּבָקַת בְּמַלְכָּא עִלָּאָה, נַטְלָה תְּרֵי שׁוֹשַׁנִּים, כְּמָה דְאַתְּ אָמֵר (שיר השירים ה׳:י״ג) שִׂפְתוֹתָיו שׁוֹשַׁנִּים. וּבְגִין כָּךְ אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, (שם א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. (כמה דאת אמר (בראשית מ״א:מ׳) ועל פיך ישק כל עמי) בְּגִין דְּאִתְכְּלִילַת בַּשּׁוֹשַׁנִּים, בִּתְרֵי שִׂפְוָון דִּילֵיהּ.","רִבִּי יְהוּדָה אָמַר, קוּדְשָׁא בְּרִיךְ הוּא שָׁמַיִם אִקְרֵי. וּבְגִין דְּאִקְרֵי שָׁמַיִם, כָּל אִינּוּן רְקִיעִין דְּאִתְכְּלִילָן בִּשְׁמָא דָּא, (ס\"א שבעה אינון דכד מתחברן וכו') כַּד מִתְחַבְּרָן כַּחֲדָא, אִקְרוּ שָׁמַיִם, וְאִקְרוּ שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא. מַאן אִינּוּן רְקִיעִין. שִׁבְעָה אִינּוּן.","כְּמָה דְּתָנֵינָן, וִילוֹן, רָקִיעַ, שְׁחָקִים, זְבוּל, מָעוֹן, מָכוֹן, עֲרָבוֹת. וּבְאַגַּדְתָּא דְּבֵי רַב הַמְנוּנָא סָבָא, הָכִי תָּנֵינָן. רִבִּי יִצְחָק אָמַר, הָנֵי בָּרַיְיתֵי דְּבֵי רַב הַמְנוּנָא סָבָא הָכִי, וְסַגִּיאִין אִינּוּן בְּכָל הָנֵי גְּוָונֵי. כְּמָה דְּתָנֵינָן, אָמַר רִבִּי שִׁמְעוֹן, תָּנֵינָן בְּאִינּוּן בָּרַיְיתֵי, (ס\"א דלבר) דִּלְגַבֵּי דְּכָל הָנֵי שִׁבְעִין כִּתְרִין דְּמַלְכָּא. לָקֳבְלֵיהוֹן שַׁוְויָין ז' רְקִיעִין, וְז' כֹּכָבַיָא דְּרַהֲטִין וְאַזְלִין, וְקָרֵי לוֹן שְׁמָהָן בִּשְׁמָהָן. וְאַף עַל גַּב דְּשַׁוְויָין כֻּלְּהוּ כִּסְאֵי דִּרְקִיעִין, דְּשִׁבְעָה כֹּכָבַיָא, שַׁבְּתַאי, צֶדֶק, מַאֲדִים, חַמָּה, נוֹגַהּ, כּוֹכָב, לְבָנָה. וְשָׁוִין אִלֵּין לָקֳבֵיל אִלֵּין, בְּכִסּוּיָא דְּמִלִּין. לְגַבֵּי אִינּוּן דִּכְתִּיב, (ישעיהו מ״ז:י״ג) יַעַמְדוּ נָא וְיוֹשִׁיעוּךְ הוֹבְרֵי שָׁמַיִם הַחוֹזִים בַּכֹּכָבִים. כֻּלְּהוּ מִלִּין מִתְכַּסְּיָין, וְאַף עַל גַּב דְּלָאו אוֹרְחֵי דְּאוֹרַיְיתָא. וַאֲנָן בָּתַר אוֹרְחִין דְּאוֹרַיְיתָא קָא אַזְלֵינָן, כְּמָה דִּכְתִּיב, (בראשית כ״ו:י״ח) וַיִּקְרָא לָהֶן שֵׁמוֹת כַּשֵּׁמוֹת אֲשֶׁר קָרָא לָהֶן אָבִיו, כְּמָה דְּמַלִּיל קוּדְשָׁא בְּרִיךְ הוּא, אָזְלֵינָן, וּבַהֲדֵיהּ אָזְלֵינָן, כְּמָה דִּכְתִּיב, (דברים כ״ח:ט׳) וְהָלַכְתָּ בִּדְרָכָיו.","אָמַר רִבִּי יוֹסֵי, פְּשִׁיטִין מִלִּין אִלֵּין לְגַבֵּי חַבְרַיָּיא, וְאִשְׁתְּמוֹדְעָן מִלֵּי בְּהוּ, וְאַף עַל גַּב דְּאִתְכַּסְּיָין. אָמַר לֵיהּ וְהָכִי תְּנָן, כְּמָה דְּאָמַר רִבִּי יְהוּדָה אָמַר רִבִּי חִיָּיא לְקַמָּן. וְהָכִי אוֹלִיפְנָא מֵאִינּוּן בָּרַיְיתֵי, דְּתָנָא בְּיוֹמוֹי דִּשְׁלֹמֹה מַלְכָּא, קַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא, וּבְאַתְרִין סַגִּיאִין אִשְׁתְּמוֹדְעָן מִלֵי דְּאִינּוּן בָּרַיְיתֵי.","אָמַר רִבִּי שִׁמְעוֹן, אֲרִימִית יְדַי בְּצַלּוּ לְקַדִישָׁא עִלָּאָה, דְּמִלִּין אִלֵּין אִתְגְּלִּיאוּ עַל יְדִי, בְּהַהוּא עָלְמָא, כְּמָה דְּאִתְכְּסִּיאוּ בְּלִבָּאִי. וְלֵית אֲנָן בְּאִינּוּן אָרְחִין דְּאִינּוּן בָּרַיְיתֵי, אוֹרְחֵי דְּאוֹרַיְיתָא נַקְטִינָן.","תָּאנָא אָמַר רִבִּי יְהוּדָה, מַאן לָךְ רַב בְּחָכְמְתָא כְּדָוִד מַלְכָּא, וּשְׁלֹמֹה מַלְכָּא בְּרֵיהּ, בְּהַאי כִּתְרָא דְּאִשְׁתְּמוֹדַע בְּבָרַיְיתֵי אִלֵּין. וְסִיהֲרָא קַרְיֵיהּ דָּוִד מַלְכָּא צֶדֶק, דְּהָא דִּילֵיהּ הוּא, דִּכְתִּיב, (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. שְׁלֹמֹה מַלְכָּא הָכִי נָמֵי, וְאִיהוּ אִתְקְרֵי צֶדֶק, וְשִׁמְּשָׁא דְּאִתְקְרֵי בְּבָרַיְיתֵי בְּרִית, אִיהוּ אִקְרֵי מִשְׁפָּט. וְאִינּוּן כֻּרְסֵי יְקָרָא דְּמַלְכָּא, דִּכְתִּיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ. צַדִּיק וְצֶדֶק הָכִי נָמֵי בְּחַד דַּרְגָּא הֲווֹ. תָּאנָא, ז' כִּתְרִין אוֹקְמוּהָ, תִּשְׁעָה אִקְרוּן. וַאֲפִילּוּ בְּאִינּוּן בָּרַיְיתֵי, שִׁבְעָה רְקִיעִין אִינּוּן תִּשְׁעָה הֲווֹ.","אָמַר רִבִּי שִׁמְעוֹן, עַד אֵימָתַי יִקְרוּן חַבְרַיָּיא בְּהָנֵי מִלִּין. הָא אֲנָן בָּתַר קוּדְשָׁא בְּרִיךְ הוּא אַזְלֵינָן, וַאֲנָן יַדְעֵי מִלִּין, וְהָא אִתְגְּלֵי עַל יְדָן מִלָּה דָּא, מַה דְּלָא אִתְגְּלֵי לְקַדְמָאֵי. מִכָּאן וּלְהָלְאָה, כָּל אִינּוּן מִלִּין, וְכָל אִינּוּן בָּרַיְיתֵי, סְלִיקוּ לְהוּ לְאִינּוּן דְּלָא עָאלוּ וְנַפְקוּ, וּבְנֵיהוֹן אַתְיָין לְשָׁאֲלָא. וְכַד יִשְׁאֲלוּן, יֵימְרוּן חַבְרַיָּיא, וַוי לְדָרָא דְּרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי אִסְתְּלִיק מִנֵּיהּ. אֲבָל תָּא חֲזֵי מִכָּאן וּלְהָלְאָה, לָא יְהֵא דָּרָא כְּדָרָא דָּא, וְלָא אוֹרַיְיתָא אִתְגְּלֵי עַל חַבְרַיָּיא.","תָּא חֲזֵי, דָּרָא בַּתְרָאָה דְּנַפְקוּ מִמִּצְרַיִם, יָדְעוּ כֹּלָּא, דְּהָא מֹשֶׁה גַּלֵּי לוֹן כָּל אִינּוּן מ' שְׁנִין דַּהֲווֹ בְּמַדְבְּרָא, כְּמָה דַּאֲמֵינָא. תָּאנָא אָמַר רִבִּי יִצְחָק, וְאַף מֹשֶׁה לָא גַּלֵּי דָּא, אֶלָּא בְּהַהוּא יוֹמָא דְּהֲוָה סָלִיק מִן עָלְמָא, דִּכְתִּיב, (דברים ל״א:ב׳) בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם, בְּהַהוּא יוֹמָא מַמָּשׁ, וְעִם כָּל דָּא לָא אָמַר, עַד דְּיָהֲבוּ לֵיהּ רְשׁוּתָא. דִּכְתִּיב, (שם) וְעַתָּה כִּתְבוּ לָכֶם אֶת הַשִּׁירָה הַזֹּאת. וְכַד גַּלֵּי, לָא אָמַר הַאֲזִינוּ יִשְׂרָאֵל, אֶלָּא הַאֲזִינוּ הַשָּׁמַיִם.","אָמַר רִבִּי יוֹסֵי, כְּתִיב אֶת הַשִּׁירָה, וְכִי שִׁירָה אִקְרֵי. אָמַר רִבִּי יִצְחָק שִׁירָה וַדַּאי, מַה שִׁירָה אִתְמַשְּׁכָא בְּרוּחַ הַקֹּדֶשׁ מֵעֵילָּא לְתַתָּא, אוּף הָכִי מִלִּין אִלֵּין אִתְמַשְּׁכָן בְּרוּחַ הַקֹּדֶשׁ מֵעֵילָּא לְתַתָּא, וּבְגִין כָּךְ אָמַר מֹשֶׁה שִׁירָה."],[[0,"ר' יצחק אמר וכו':","רי\"א באיזה מקום נכללה כנסת ישראל בשושנה. היינו באלו נשיקין של אהבה שהמלכות נתדבקה במלך העליון, ז\"א, אז לקחה מב' שפתותיו, ב' שושנים, כש\"א שפתותיו שושנים. ומשום זה אמרה כנסת ישראל, ישקני מנשיקות פיהו. כי אז נכללת בשושנים בב' שפות שלו. הנק' שושנים."],[1,"ר' יהודה אמר וכו':","רי\"א, הקב\"ה שהוא ז\"א, נקרא שמים, ומשום שנקרא שמים, כל אלו הרקיעים, הנכללים בשם הזה, כשמתחברים יחד נקראים שמים. ונקראים שם הקב\"ה. מה הם אלו הרקיעים הנכללים בשמים, ומשיב, שבעה הם כמו שלמדנו, וילון, רקיע, שחקים, זבול, מעון, מכון, ערבות. ובאגדתא דרב המנונא סבא למדנו כך. בלשון הזה. ר' יצחק אמר אלו הברייתות של ר' המנונא סבא כך הם, דהיינו שמדברים מדברים תחתונים ורומזים עליונים. דהיינו כמו כאן שמדברים מז' רקיעים ורומזים על ז\"א. שיש לו ז' ספירות. ורבות המה הברייתות המדברות בכל אלו הדרכים."],[2,"כמה דתנינן אר\"ש וכו':","כמו שלמדנו, א\"ר שמעין, למדנו באלו הברייתות, אשר כלפי כל אלו שבעים ספירות של המלך, משימים כנגדם ז' רקיעים, וז' ככבי לכת הרצים והולכים, וקוראים אותם שמות בשמות הגשמיים, ואע\"פ שהם משימים הרקיעים כולם בכיסוי, דהיינו שקוראים בשמות המרמזים על הפנימיות בהעלם. ושבעת הככבים, שבתאי, צדק, מאדים, חמה, נוגה, כוכב, לבנה, עושים אלו ז' ספירות העליונים, כנגד אלו שמות הכוכבים, ברצונם לכסות הדברים דהיינו כנגד אלו שכתוב בהם יעמדו נא ויושיעך הוברי שמים החוזים בככבים. ומכסים כל הדברים בשמות ההם, אע\"פ שאינם בדרכי התורה, אלא לשון החוזים בככבים, ואנו, אחר דרכי התורה אנו הולכים, דהיינו לרמז על כל דבר ולכסות, בלשון התורה, כמ\"ש ויקרא להם שמות כשמות אשר קרא להן אביו. דהיינו כמו שהקב\"ה מדבר אנו הולכים, דהיינו בלשון התורה, ועמו אנו הולכים, כמ\"ש, והלכת בדרכיו. פירוש. ר\"ש היו מתרעם על אותם הברייתות, המבארים סדרי חכמת הקבלה ע\"פ שמות מחכמות חיצוניות. ולא ע\"פ שמות שבתורה, ושבשיר השירים, כדרכו של ר' שמעון."],[3,"א\"ר יוסי פשיטין וכו':","אר\"י דברים אלו דהיינו השמות החיצונים הנ\"ל, פשוטים אצל החברים, והדברים מובנים להם, אע\"פ שנתכסו בשמות זרים. א\"ל, וכך למדנו, כמו שא\"ר יהודה א\"ר חייא לפנינו. וכך למדנו מאלו הברייתות, שלמדנו, בימיו של שלמה המלך עמדה הלבנה במילואה, דהיינו שהמלכות היתה במלואה פנים בפנים עם ז\"א, וע\"כ התרבתה אז החכמה, ובמקומות רבים הבינו הדברים של אלו הברייתות."],[4,"אר\"ש ארימית ידי וכו':","א\"ר שמעון, הרימותי ידי בתפלה, להקדוש העליון, שדברים אלו, דהיינו חכמת הקבלה, נתגלו על ידי בעולם ההוא, כמו שהיו מכוסים בלבי. ואין אנו משתמשים באלו הדרכים של אותם הברייתות, אלא דרכי התורה אנו מחזיקים לבאר החכמה, כנ\"ל."],[5,"תאנא א\"ר יהודה וכו':","למדנו א\"ר יהודה, מי לך גדול בחכמה כדוד המלך ושלמה המלך בנו, בהשגת אותה הספירה הנודעת בברייתות אלו, דהיינו ספירת המלכות. והלבנה, שהיא מלכות, קראה דוד המלך \u0003צדק\u0004, כי שלו היא, שהיה מרכבה למלכות, שכתוב פתחו לי שערי \u0003צדק\u0004 אבא בם אודה יה. שלמה המלך ג\"כ קראה צדק. והיא נקראת צדק, והשמש, שנקרא בברייתות, ברית, דהיינו יסוד, הוא נקרא משפט. והם כסא הכבוד של המלך, ז\"א, שכתוב צדק ומשפט מכון כסאך, כי צדיק וצדק, שהם יסוד ומלכות, הם ג\"כ במדרגה אחת. וע\"כ כוללם ואמר, צדק ומשפט מכון כסאך. למדנו ז' ספירות, חג\"ת נהי\"מ הן תשע דהיינו עם חכמה ובינה. ואפילו באלו הברייתות, שבעה רקיעים הם תשעה."],[6,"אר\"ש עד אימתי וכו':","א\"ר שמעון עד מתי יקראו החברים בדברים אלו, דהיינו בברייתות, הרי אנו הולכים אחר הקב\"ה. ואנו יודעים הדברים, שבחכמת הקבלה, ודבר זה נתגלה על ידנו מה שלא נתגלו לראשונים. מכאן ולהלאה, כל אלו הדברים וכל אלו הברייתות הניחו אותם לאלו שלא נכנסו ויצאו, דהיינו שנכנסו בחכמה, ולא יצאו ממנה, כי לא הבינו אותה. ובניהם יבואו לשאול בחכמה, וכשישאלו יאמרו להם החברים. אוי לאותו הדור שר'\"ש בן יוחאי נסתלק ממנו. אבל בוא וראה, מכאן ולהלאה לא יהיה דור כדור הזה, והתורה לא תתגלה ע\"י החברים."],[7,"ת\"ח דרא בתראה וכו':","בוא וראה, דור האחרון שיצא ממצרים ידע הכל, כי משה גילה להם כל אלו מ' שנה שהיו במדבר, כמו שאמרתי. למדנו, א\"ר יצחק, ואף משה לא גילה זה, אלא ביום ההוא שנסתלק מן העולם. שכתוב בן מאה ועשרים שנה אנכי היום. ביום ההוא, שנסתלק מן העולם, ממש. ועכ\"ז לא אמר עד שנתנו לו רשות. שכתוב, ועתה כתבו לכם את השירה הזאת. וכשגילה, לא אמר האזינו ישראל, אלא האזינו השמים."],[8,"א\"ר יוסי כתיב וכו':","אר\"י כתוב, את השירה, דהיינו כתבו לכם את השירה הזאת. וכי שירה נקראת, היה צריך לומר את התורה. א\"ר יצחק, שירה ודאי היא. מה שירה נמשכה ברוח הקודש ממעלה למטה, אף דברים אלו כך שנמשכו ברוח הקודש ממעלה למטה. ומשום זה אמר משה שירה."]],[[0,"","רַבִּי יִצְחָק אָמַר, בְּאֵיזֶה מָקוֹם נִכְלֶלֶת כְּנֶסֶת יִשְׂרָאֵל? בַּשּׁוֹשַׁנָּה. בְּאֵלּוּ הַנְּשִׁיקוֹת שֶׁל אַהֲבָה שֶׁנִּדְבֶּקֶת בַּמֶּלֶךְ הָעֶלְיוֹן, לוֹקַחַת שְׁתֵּי שׁוֹשַׁנִּים, כְּמוֹ שֶׁנֶּאֱמַר [שם ה] שִׂפְתוֹתָיו שׁוֹשַׁנִּים. וּמִשּׁוּם זֶה אָמְרָה כְנֶסֶת יִשְׂרָאֵל, [שם א] יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ [כמו שנאמר [בראשית מא] ועל פיך ישק כל עמי], מִשּׁוּם שֶׁנִּכְלֶלֶת בַּשּׁוֹשַׁנִּים בִּשְׁתֵּי שְׂפָתַיִם שֶׁלּוֹ."],[1,"","רַבִּי יְהוּדָה אָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא שָׁמַיִם, וּמִשּׁוּם שֶׁנִּקְרָא שָׁמַיִם, כָּל אֵלּוּ הָרְקִיעִים שֶׁנִּכְלָלִים בְּשֵׁם זֶה, [שבעה הם שכאשר מתחברים וכו'] כַּאֲשֶׁר מִתְחַבְּרִים כְּאֶחָד, נִקְרָאִים שָׁמַיִם, וְנִקְרָאִים שֵׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מָה אֵלּוּ הָרְקִיעִים? שִׁבְעָה הֵם."],[2,"","כְּמוֹ שֶׁלָּמַדְנוּ, וִילוֹן, רָקִיעַ, שְׁחָקִים, זְבוּל, מָעוֹן, מָכוֹן, עֲרָבוֹת. וּבָאַגָּדוֹת שֶׁל יְשִׁיבַת רַב הַמְנוּנָא סָבָא כָּךְ לָמַדְנוּ. רַבִּי יִצְחָק אָמַר, אֵלּוּ הַבָּרַיְתוֹת שֶׁל יְשִׁיבַת רַב הַמְנוּנָא סָבָא כָּךְ, וְרַבִּים הֵם בְּכָל אֵלּוּ הָאֳפָנִים. כְּמוֹ שֶׁלָּמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, שָׁנִינוּ בְּאֵלּוּ הַבָּרַיְתוֹת [החיצוניות], שֶׁאֵצֶל כָּל אֵלּוּ הַשִּׁבְעִים כְּתָרִים שֶׁל הַמֶּלֶךְ, כְּנֶגְדָּם יֵשׁ שִׁבְעָה רְקִיעִים וְשִׁבְעָה כּוֹכָבִים שֶׁרָצִים וְהוֹלְכִים, וְקוֹרְאִים לָהֶם שֵׁמוֹת כִּשְׁמוֹתָם, וְאַף עַל גַּב שֶׁשָּׁוִים כֻּלָּם. כִּסְאוֹת הָרְקִיעִים שֶׁל שִׁבְעָה כּוֹכָבִים – שַׁבְּתַאי, צֶדֶק, מַאְדִּים, חַמָּה נֹגַהּ, כּוֹכָב, לְבָנָה. וְשָׁוִים אֵלּוּ כְּנֶגֶד אֵלּוּ בְּכִסּוּי הַדְּבָרִים. אֵצֶל אֵלּוּ כָּתוּב, [ישעיה מז] יַעַמְדוּ נָא וְיוֹשִׁיעֻךְ הֹבְרֵי שָׁמַיִם הַחֹזִים בַּכּוֹכָבִים. כָּל הַדְּבָרִים נֶעְלָמִים, וְאַף עַל גַּב שֶׁאֵינָם דַּרְכֵי הַתּוֹרָה. וְאָנוּ אַחַר דַּרְכֵי הַתּוֹרָה אָנוּ הוֹלְכִים, כְּמוֹ שֶׁכָּתוּב [בראשית כו] וַיִּקְרָא לָהֶן שֵׁמוֹת כַּשֵּׁמֹת אֲשֶׁר קָרָא לָהֶן אָבִיו. כְּמוֹ שֶׁדִּבֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא אָנוּ הוֹלְכִים, וְעִמּוֹ הוֹלְכִים, כְּמוֹ שֶׁכָּתוּב [דברים כח] וְהָלַכְתָּ בִּדְרָכָיו."],[3,"","אָמַר רַבִּי יוֹסֵי, פְּשׁוּטִים דְּבָרִים אֵלּוּ אֵצֶל הַחֲבֵרִים, וְנוֹדָעִים דְּבָרִים בָּהֶם, וְאַף עַל גַּב שֶׁמְּכֻסִּים. אָמַר לוֹ, וְכָךְ שָׁנִינוּ, כְּמוֹ שֶׁאָמַר רַבִּי יְהוּדָה, אָמַר רַבִּי חִיָּיא לְפָנֵינוּ. וְכָךְ לָמַדְנוּ מֵאֵלּוּ הַבָּרַיְתוֹת, שֶׁשָּׁנִינוּ, בְּיָמָיו שֶׁל שְׁלֹמֹה הַמֶּלֶךְ עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, וּבִמְקוֹמוֹת רַבִּים נוֹדָעִים דְּבָרִים שֶׁהֵם בָּרַיְתוֹת."],[4,"","אָמַר רַבִּי שִׁמְעוֹן, הֵרַמְתִּי יָדִי בִתְפִלָּה לַקָּדוֹשׁ הָעֶלְיוֹן, שֶׁדְּבָרִים אֵלּוּ הִתְגַּלּוּ עַל יָדִי בָּעוֹלָם הַהוּא כְּמוֹ שֶׁהָיוּ מְכֻסִּים בְּלִבִּי. וְאֵין אָנוּ בְּאוֹתָם דְּרָכִים שֶׁל אֵלּוּ הַבָּרַיְתוֹת, דַּרְכֵי הַתּוֹרָה אָנוּ אוֹחֲזִים."],[5,"","שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, מִי לְךְ גָּדוֹל בְּחָכְמָה כְּדָוִד הַמֶּלֶךְ וּשְׁלֹמֹה הַמֶּלֶךְ בְּנוֹ בַּכֶּתֶר הַזֶּה שֶׁנּוֹדַע בְּבָרַיְתוֹת אֵלּוּ. וְהַלְּבָנָה, קָרָא אוֹתָהּ דָּוִד הַמֶּלֶךְ צֶדֶק, שֶׁהֲרֵי שֶׁלּוֹ הוּא, שֶׁכָּתוּב [תהלים קיח] פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. שְׁלֹמֹה הַמֶּלֶךְ כָּךְ גַּם, וְהוּא נִקְרָא צֶדֶק, וְהַשֶּׁמֶשׁ שֶׁנִּקְרָא בַבָּרַיְתוֹת בְּרִית, הוּא נִקְרָא מִשְׁפָּט, וְאֵלּוּ כִּסְאוֹת הַכָּבוֹד שֶׁל הַמֶּלֶךְ, שֶׁכָּתוּב [תהלים פט] צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ. צַדִּיק וְצֶדֶק כָּךְ גַּם בְּמַדְרֵגָה אַחַת הָיוּ. לָמַדְנוּ, שִׁבְעָה כְתָרִים בֵּאֲרוּהָ, תִּשְׁעָה נִקְרָאִים. וַאֲפִלּוּ בְּאֵלּוּ הַבָּרַיְתוֹת, שִׁבְעָה רְקִיעִים אֵלּוּ – תִּשְׁעָה הָיוּ."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, עַד מָתַי יִקְרְאוּ הַחֲבֵרִים בְּאֵלּוּ הַדְּבָרִים. הֲרֵי אָנוּ אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלְכִים, וְאָנוּ יוֹדְעִים דְּבָרִים, וְהִנֵּה מִתְגַּלֶּה עַל יָדֵינוּ דָּבָר זֶה מַה שֶּׁלֹּא נִגְלָה לַקַּדְמוֹנִים. מִכָּאן וּלְהָלְאָה, כָּל אֵלּוּ הַדְּבָרִים וְכָל אֵלּוּ הַבָּרַיְתוֹת סִלְּקוּ אוֹתָם לְאוֹתָם שֶׁלֹּא נִכְנְסוּ וְיָצְאוּ, וּבְנֵיהֶם בָּאִים לִשְׁאֹל. וְכַאֲשֶׁר יִשְׁאֲלוּ, יֹאמְרוּ הַחֲבֵרִים: אוֹי לַדּוֹר שֶׁרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי יִסְתַּלֵּק מִמֶּנּוּ. אֲבָל בּא רְאֵה, מִכָּאן וּלְהַבָּא לֹא יִהְיֶה דוֹר כְּדוֹר זֶה, וְלֹא תִתְגַּלֶּה תוֹרָה עַל הַחֲבֵרִים."],[7,"","בֹּא רְאֵה, דּוֹר אַחֲרוֹן שֶׁיָּצְאוּ מִמִּצְרַיִם יָדְעוּ הַכֹּל, שֶׁהֲרֵי מֹשֶׁה גִּלָּה לָהֶם כָּל אוֹתָן אַרְבָּעִים שָׁנָה שֶׁהָיוּ בַמִּדְבָּר, כְּמוֹ שֶׁאָמַרְנוּ. לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, וְאַף מֹשֶׁה לֹא גִלָּה זֶה אֶלָּא בְאוֹתוֹ יוֹם שֶׁהָיָה מִסְתַּלֵּק מִן הָעוֹלָם, שֶׁכָּתוּב [דברים לא] בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם, בְּאוֹתוֹ יוֹם מַמָּשׁ. וְעִם כָּל זֶה לֹא אָמַר, עַד שֶׁנָּתְנוּ לוֹ רְשׁוּת, שֶׁכָּתוּב [שם] וְעַתָּה כִתְבוּ לָכֶם אֶת הַשִּׁירָה הַזֹּאת. וְכַאֲשֶׁר גִּלָּה, לֹא אָמַר הַאֲזִינוּ יִשְׂרָאֵל, אֶלָּא הַאֲזִינוּ הַשָּׁמַיִם."],[8,"","אָמַר רַבִּי יוֹסֵי, כָּתוּב אֶת הַשִּׁירָה, וְכִי שִׁירָה נִקְרֵאת? אָמַר רַבִּי יִצְחָק, שִׁירָה וַדַּאי. מַה שִּׁירָה נִמְשְׁכָה בְּרוּחַ הַקֹּדֶשׁ מִמַּעְלָה לְמַטָּה, אַף כָּךְ דְּבָרִים אֵלּוּ נִמְשָׁכִים בְּרוּחַ הַקֹּדֶשׁ מִמַּעְלָה לְמַטָּה, וּמִשּׁוּם זֶה אָמַר מֹשֶׁה שִׁירָה."]]],[["תָּא חֲזֵי, כּוּלֵי הַאי אָמַר מֹשֶׁה, וְקָרָא לְעִלָּאִין, עַד לָא יֵימָּא מִלָּה, דִּכְתִּיב הַאֲזִינוּ הַשָּׁמַיִם. יַעֲרוֹף כַּמָּטָר וְגוֹ'. וְכָל כַּךְ לָמָּה. מִשּׁוּם כִּי שֵׁם יְיָ' אֶקְרָא. עַד דְּיֵימָּא מִלָּה, אַרְעִישׁ כֻּלְּהוּ עָלְמִין.","תָּאנָא בְּהַהִיא שַׁעֲתָא דְּאָמַר מֹשֶׁה הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, אִתְרְגִּישׁוּ עָלְמִין. נָפַק קָלָא וְאָמַר, מֹשֶׁה מֹשֶׁה, אֲמַאי אַתְּ מַרְעִישׁ עָלְמָא כֹּלָּא. אַתְּ בְּרֵיהּ דְּבַר נָשׁ, וּבְגִינָךְ אִתְרְגִּישׁ עָלְמָא. פָּתַח וְאָמַר, כִּי שֵׁם יְיָ' אֶקְרָא. בְּהַהִיא שַׁעֲתָא אִשְׁתָּתָקוּ, וַאֲצִיתוּ מִלּוֹי.","אָמַר רִבִּי יוֹסֵי, כַּמָה חֲבִיבִין יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, בְּקַדְמִיתָא קָרָא לוֹן גּוֹי קָדוֹשׁ, דִּכְתִּיב, (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה וְגוֹ'. לְבָתַר קָרָא לוֹן קֹדֶשׁ, דִּכְתִּיב, (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה. מַה בֵּין הַאי לְהַאי. אָמַר רִבִּי אַבָּא, קֹדֶשׁ עִלָּאָה מִכֹּלָּא, דְּהָכִי תָּנֵינָן, כַּד אִתְחַבְּרָן כֻּלְּהוּ קְדוֹשֵׁי כַּחֲדָא, אִקְרוּן קָדוֹשׁ. וְכֻלְּהוּ סַלְּקִין וּמִתְכַּנְּשִׁין לְהַהוּא אֲתָר עִלָּאָה, דְּאִקְרֵי קֹדֶשׁ."],[[0,"ת\"ח כולי האי וכו':","בוא וראה, כל כמה אמר משה וקרא לעליונים, מטרם שהתחיל לומר מלה. שכתוב, האזינו השמים. יערוף כמטר לקחי וגו'. וכל כך למה. משום כי שם ה' אקרא. ומטרם שאמר דבר זה, הרעיש כל העולמות."],[1,"תאנא בההוא שעתא וכו':","למדנו, בשעה ההיא שאמר משה האזינו השמים ואדברה, נזדעזעו העולמות. יצא קול ואמר, משה משה, למה אתה מרעיש כל העולם. אתה, בן אדם, ובשילך ירעש העולם. פתח ואמר, כי שם ה' אקרא. באותה שעה נשתתקו והקשיבו לדבריו."]],[[0,"","בֹּא רְאֵה, כָּל זֶה אָמַר מֹשֶׁה וְקָרָא לָעֶלְיוֹנִים טֶרֶם יֹאמַר דָּבָר, שֶׁכָּתוּב הַאֲזִינוּ הַשָּׁמַיִם. יַעֲרֹף כַּמָּטָר וְגוֹ'. וְכָל כָּךְ לָמָּה? מִשּׁוּם כִּי שֵׁם ה' אֶקְרָא. עַד שֶׁיֹּאמַר דָּבָר, הִרְעִישׁ כָּל הָעוֹלָמוֹת."],[1,"","לָמַדְנוּ, בְּאוֹתָהּ שָׁעָה שֶׁאָמַר מֹשֶׁה הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, הִתְרַגְּשׁוּ הָעוֹלָמוֹת. יָצָא קוֹל וְאָמַר: מֹשֶׁה מֹשֶׁה, מַדּוּעַ אַתָּה מַרְעִישׁ אֶת כָּל הָעוֹלָם? אַתָּה בְּנוֹ שֶׁל אָדָם, וּבִגְלָלְךְ נִרְגָּשׁ הָעוֹלָם?! פָּתַח וְאָמַר, כִּי שֵׁם ה' אֶקְרָא. בְּאוֹתָהּ שָׁעָה נִשְׁתַּתְּקוּ וְהִקְשִׁיבוּ לִדְבָרָיו."],[2,"","אָמַר רַבִּי יוֹסֵי, כַּמָּה חֲבִיבִין יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. בָּרִאשׁוֹנָה קָרָא לָהֶם גּוֹי קָדוֹשׁ, שֶׁכָּתוּב [דברים יד] כִּי עַם קָדוֹשׁ אַתָּה וְגוֹ', וּלְבַסּוֹף קָרָא לָהֶם קֹדֶשׁ, שֶׁכָּתוּב [ירמיה ב] קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. מַה בֵּין זֶה לָזֶה? אָמַר רַבִּי אַבָּא, קֹדֶשׁ – עֶלְיוֹן מִכֻּלָּם. שֶׁכָּךְ לָמַדְנוּ, כַּאֲשֶׁר מִתְחַבְּרִים כָּל הַקְּדוֹשִׁים כְּאֶחָד, נִקְרָאִים קָדוֹשׁ. וְכֻלָּם עוֹלִים וּמִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא קֹדֶשׁ."]]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[["וּבְגִין כָּךְ ק' ק' ק' (קדוש קדוש קדוש), קֹדֶשׁ יִשְׂרָאֵל אִתְעָבִיד מִנַּיְיהוּ. וּבְגִין דְּיִשְׂרָאֵל בִּתְלַת דַּרְגִּין מִתְעַטְּרִן, כַּד אִתְחַבְּרָן כַּחֲדָא, אִקְרוּן קֹדֶשׁ יִשְׂרָאֵל לַיְיָ', דְּאִיהִי רֵאשִׁית. וְהָא אוֹקִימְנָא תְּבוּאָתֹה, בְּהֵ\"א. כָּל אוֹכְלָיו יֶאְשָׁמוּ, מַאי כָּל אוֹכְלָיו יֶאְשָׁמוּ. אָמַר רִבִּי אַבָּא, הָא אִתְּמַר, דִּכְתִּיב, (ויקרא כ״ב:י״ד) וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה. וּכְתִיב (שם) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ, וְיִשְׂרָאֵל אִקְרוּן קֹדֶשׁ, בְּגִין כָּךְ כָּל אוֹכְלָיו יֶאְשָׁמוּ.","אָמַר רִבִּי אֶלְעָזָר, שֵׁירוּתָא וְסִיּוּמָא דְּכֹלָּא, אִתְכְּלִיל בַּקֹּדֶשׁ. (ס\"א א') וְחָכְמָה עִלָּאָה קֹדֶשׁ אִקְרֵי, וְכַד נָהִיר דָּא חָכְמָה עִלָּאָה, חָכְמָה דִּשְׁלֹמֹה נָהִיר. כְּמָה דִּכְתִּיב, (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמַת שְׁלֹמֹה, דְּקַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא. וְהָא אוֹקִימְנָא. וְכַד אִתְבָּרְכָא מִיסוֹד, הָכִי קָרֵינָן לָהּ קֹדֶשׁ, דְּאִיהוּ אַנְהִיר בִּשְׁלִימוּ. וְכַד לָא אִתְנַהֲרָא מִתְעַטְּרָא בְּאַשְׁלְמוּתָא, קָרֵינָן לָהּ רוּחַ הַקֹּדֶשׁ, וְלָא אִתְקְרֵי קֹדֶשׁ כְּהַהוּא דִּלְעֵילָּא.","וְכַד מִתְבָּרְכָא מֵהַאי יְסוֹד, וְיַנְקָא לְכָל אִינּוּן דִּלְתַתָּא, אִתְקְרֵי אֵם, כְּהַהִיא דִּלְעֵילָּא. וְקָרֵינָן לֵיהּ קֳדָשִׁים. וּכְדֵין קָרֵינָן לֵיהּ קֹדֶשׁ הַקֳּדָשִׁים, דְּבֵיהּ כַּלָּה דִּכְתִּיב, (שיר השירים ד׳:ח׳) אִתִּי מִלְּבָנוֹן כַּלָּה וְגוֹ'. מַאי לְבָנוֹן. דָּא עֵדֶן, דְּאִתְלַבֵּן מִכָּל סִטְרִין. וְעֵדֶן הָא יָדוּעַ לְגַבֵּי חַבְרַיָּיא.","תָּאנָא, כְּתִיב כִּי שֵׁם יְיָ' אֶקְרָא, מַאי כִּי שֵׁם יְיָ' אֶקְרָא. אָמַר רִבִּי שִׁמְעוֹן, הָא כְּתִיב הָבוּ גּוֹדֶל לֵאלֹהֵינוּ. אָמַר רִבִּי אַבָּא, הָבוּ גּוֹדֶל, דָּא גְּדוּלָה, הַצוּר תָּמִים פָּעֳלוֹ, דָּא גְּבוּרָה. כִּי כָל דְּרָכָיו מִשְׁפָּט, דָּא תִּפְאֶרֶת. אֵל אֱמוּנָה, דָּא נֶצַח. וְאֵין עָוֶל, דָּא הוֹד. צַדִּיק, דָּא יְסוֹד. וְיָשָׁר, דָּא צֶדֶק. הוּא כֹּלָּא שְׁמָא קַדִּישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כָּךְ כִּי שֵׁם יְיָ' אֶקְרָא.","אָמַר רִבִּי יוֹסֵי, שֵׁם יְיָ' מַמָּשׁ. וּמֹשֶׁה בְּהַהִיא שַׁעֲתָא גַּלֵּי לְהוּ לְיִשְׂרָאֵל. דִּכְתִּיב, (דברים ל״א:ב׳) בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם וְגוֹ'. מִכָּאן אוֹלִיפְנָא, הַהוּא זַכָּאָה דְּחָכְמְתָא עִלָּאָה בֵּיהּ, כַּד מָטֵי יוֹמָא לְאִסְתַּלְּקָא מֵעָלְמָא, בָּעֵי לְגַלָּאָה הַהִיא חָכְמְתָא, לְאִינּוּן דִּי רוּחַ קַדִּישָׁא בֵּינַיְיהוּ. מְנָלָן. מִמֹּשֶׁה. דִּכְתִּיב בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם. וּכְתִיב, (שם) וְעַתָּה כִּתְבוּ לָכֶם אֵת הַשִּׁירָה הַזֹּאת וְגוֹ'.","וְאִם לָאו, עָלֵיהּ כְּתִיב, (משלי ג׳:כ״ז) אַל תִּמְנָע טוֹב מִבְּעָלָיו. כְּמָה דְאַתְּ אָמֵר, (משלי ד׳:ב׳) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם וְגוֹ'. (משלי ג׳:כ״ז) בִּהְיוֹת לְאֵל יָדְךָ לַעֲשׂוֹת. עַד לָא תִּסְתָּלַּק מִן עָלְמָא, וְלָא אִתְיְיהִיב לָךְ רְשׁוּתָא לְגַלָּאָה.","אָמַר רִבִּי חִיָּיא, הַאי קְרָא אוֹלִיפְנָא מִנֵיהּ חָכְמְתָא עִלָּאָה, וְהָכִי הוּא. אֲבָל סֵיפֵיהּ דִּקְרָא, מְקַשֵּׁר קִשְׁרָא דִּמְהֵימְנוּתָא, בְּמַאי דִּכְתִּיב הוּא. כְּמָה דְאַתְּ אָמֵר, צַדִּיק וְיָשָׁר הוּא. כְּלוֹמַר הוּא כֹּלָּא. הוּא חַד בְּלָא פִּרוּדָא. דְּאִי תֵּימָא כָּל הָנֵי סַגִּיאִין אִינּוּן, חָזַר וְאָמַר הוּא, כֻּלְּהוּ סַלְּקִין וּמִתְקַשְּׁרָן וּמִתְאַחֲדָן בְּחַד. וְכֹלָּא, הוּא הָיָה, וְהוּא הֲוָה, וְהוּא יְהֵא. וְהוּא חַד. בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין. (על) עַד כֵּן מִתְקַטְּרִין מִלִּין, וּמִתְאַחֲדִין מִלִּין קַדִּישִׁין, דִּשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא.","זַכָּאָה חוּלָקֵיהּ מַאן דְּקָרֵי לְמַלְכָּא, וְיִנְדַּע לְמִקְרֵי כַּדְּקָא יָאוּת. וְאִי אִיהוּ קָרֵי וְלֹא יְדַע לְמַאן קָרֵי, אִתְרְחִיק קוּדְשָׁא בְּרִיךְ הוּא מִנֵּיהּ, דִּכְתִּיב, (תהילים קמ״ה:י״ח) קָרוֹב יְיָ' לְכָל קוֹרְאָיו וְגוֹ'. קָרוֹב יְיָ' לְכָל קוֹרְאָיו, לְמַאן קָרוֹב. חָזַר וְאָמַר, לְכֹל אֲשֶׁר יִקְרָאוּהוּ בֶאֱמֶת, וְכִי אִית מַאן דְּיִקְרֵי לֵיהּ בְּשִׁקְרָא. אָמַר רִבִּי אַבָּא אִין, הַהוּא מַאן דְּקָרֵי וְלֹא יְדַע לְמַאן דְּקָרֵי. מְנָלָן. דִּכְתִּיב לְכֹל אֲשֶׁר יִקְרָאוּהוּ בֶאֱמֶת. מַאי בֶאֱמֶת. בְּחוֹתָמָא דְּגוּשְׁפַּנְקָא דְּמַלְכָּא, דְּהוּא שְׁלִימוּ דְּכֹלָּא. הֲדָא הוּא דִכְתִיב, (מיכה ז׳:כ׳) תִתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם. וּבְגִין כָּךְ לְכֹל אֲשֶׁר יִקְרָאוּהוּ בֶאֱמֶת כְּתִיב. זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּעָאל, וְנָפַק לְמִנְדַּע אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא כְּתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נוֹגַהּ וְגוֹ'. וּכְתִיב (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'.","תַּנְיָא אָמַר רִבִּי יִצְחָק, כָּל הָנֵי תִּקּוּנִין, וְכָל הָנֵי מִלֵּי, לִמְחַצְדֵי חַקְלָא אִתְמַסְרָן. וְתָנֵינָן, חַיָּיבִין כִּבְיָכוֹל עַבְדִּין פְּגִימוּתָא לְעֵילָּא. מַאי פְּגִימוּתָא. כְּמָה דִּכְתִּיב, שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם דְּהָא כָּל הָנֵי תִּקּוּנִין לָא מִשְׁתַּכְּחֵי כַּדְּקָא יָאוּת. כָּתוּב אֶחָד אוֹמֵר, (ישעיהו נ״ט:י״ז) וַיִּלְבַּשׁ צְדָקָה כַּשִׂרְיָין, וְכָתוּב אֶחָד אוֹמֵר (שם) וַיִּלְבַּשׁ בִּגְדֵי נָקָם תִּלְבּוֹשֶׁת. אֶלָּא אָמַר רִבִּי יִצְחָק, וַיִּלְבַּשׁ צְדָקָה, בְּזִמְנָא דְּיִשְׂרָאֵל זַכָאן. לֹא זָכוּ, וַיִלְבַּשׁ בִּגְדֵי נָקָם וְגוֹ'."],[[0,"ובג\"כ ק' ק' ק' וכו':","ומשום זה קדוש קדוש קדוש, שהם חג\"ת, שה\"ס כהנים לוים ישראלים, קדש ישראל נעשה מהם. ומשום שישראל מתעטרים באלו ג' מדרגות, כשמתחברות יחד, נקראים \u0003קדש ישראל לה'\u0004 (כמ\"ש לעיל פקודי אות קס\"ה) שהוא \u0003ראשית\u0004, שאז מקבלים מחכמה עליונה שנקראת ראשית. הנה העמדנו \u0003תבואתה\u0004 היא עם \u0003ה'\u0004 יתרה, שיורה על המלכות שנקראת קדש בעת שמקבלת מחכמה העליונה, \u0003כל אוכליו יאשמו\u0004, מהו כל אוכליו יאשמו. א\"ר אבא, הנה למדנו, שכתוב, ואיש כי יאכל קדש בשגגה, וכתוב, וכל זר לא יאכל קדש, וישראל נקראים קדש, משום זה כל אוכליו יאשמו."],[1,"אר\"א שירותא וסיומא וכו':","אמר ר' אלעזר, ההתחלה, שהיא חכמה עלאה, והסוף של הכל, שהוא המלכות, נכללו בקדש. וחכמה העליונה נקראת קדש, וכשמאירה חכמה עליונה זו, מאירה גם חכמה של שלמה, שהיא המלכות, כמו שכתוב, ותרב חכמת שלמה, שהלבנה, שהיא המלכות, עמדה במילואה. וכבר העמדנו. וכשהמלכות מתברכת מן היסוד קוראים לה כך, קדש. שהיא מאירה במילואה. וכשהמלכות אינה מאירה ומתעטרת כשלימות, קוראים אותה רוח הקדש. ואינה נקראת קדש כמו החכמה של מעלה."],[2,"וכד מתברכא מהאי וכו':","וכשהמלכות מתברכת מיסוד הזה ומניקה לכל אלו שלמטה היא נקראת אם כמו אותה של מעלה, דהיינו כמו הבינה שנקראת אם. וקוראים אז את המלכות, קדשים. ואז קוראים את היסוד קדש הקדשים, כי בו היא הכלה, כלומר שהיסוד הוא קדש ועם הכלה שהיא המלכות הנקראת קדשים הוא קדש הקדשים. שכתוב, אתי מלבנון כלה. מהו לבנון. הוא עדן, דהיינו חכמה עליונה, ונקראת לבנון, משום שנתלבנה מכל הצדדים. כלומר, שמאירה בחסד שהוא גוון לבן, הן בצד ימין והן בצד שמאל. כי היא סוד או\"א עלאין שהם תמיד בסוד כי חפץ חסד הוא. אלא שמשפיעים חכמה למלכות ע\"י הנהר היוצא מעדן, שהיא בינה. ועדן כבר ידוע אצל החברים."],[3,"תאנא כתיב כי וגו':","למדנו כתוב, כי שם ה' אקרא. מהו כי שם ה' אקרא. א\"ר שמעון, הרי כתוב, הבו גודל לאלקינו. א\"ר אבא, לפרש דברי ר\"ש, \u0003הבו גודל\u0004, זהו גדולה, דהיינו חסד. \u0003הצור תמים פעלו\u0004, זהו גבורה. \u0003כי כל דרכיו משפט\u0004, זהו תפארת. \u0003אל אמונה\u0004, זהו נצח. \u0003ואין עול\u0004, זהו הוד. \u0003צדיק\u0004, זהו יסוד. \u0003וישר\u0004, זהו צדק, דהיינו המלכות. הרי הכל הוא שם הקדוש של הקב\"ה, דהיינו ז' הספירות חג\"ת נהי\"מ. ומשום זה אמר, כי שם הויה אקרא."],[4,"אמר ר' יוסי וכו':","אר\"י, הוא שם הויה ממש, שגילה להם משה באותה שעה לישראל. שכתוב, בן מאה ועשרים שנה אנכי היום וגו', ועתה כתבו לכם את השירה וגו'. מכאן למדנו, שאותו צדיק שחכמה עליונה בו, כשהגיע זמנו להסתלק מן העולם, צריך לגלות חכמה ההיא, לאותם שרוח הקדש ביניהם. מאין לנו זה. ממשה, שכתוב בן מאה ועשרים שנה אנכי היום. וכתוב, ועתה כתבו לכם את השירה הזאת וגו'. דהיינו שגילה להם מה שלא גילה להם עד אז."],[5,"ואם לאו עליה וכו':","ואם אינו מגלה להם החכמה, עליו כתוב, אל תמנע טוב מבעליו, שהוא תורה הנקראת טוב, כמ\"ש כי לקח טוב נתתי לכם וגו'. בהיות לאל ידך לעשות, מטרם שתסתלק מן העולם, מטרם שלא יהיה לך רשות לגלות."],[6,"א\"ר חייא האי וכו':","אר\"ח מקרא זה, הנ\"ל, כי שם ה' אקרא, למדתי ממנו חכמה העליונה, וכך הוא. אבל סופו של המקרא מקשר קשר האמונה, במה שכתוב, \u0003הוא\u0004, כמ\"ש, כי צדיק וישר \u0003הוא\u0004. כלומר הוא הכל. הוא אחד בלי פרוד, שאם תאמר, כל אלו השמות שבמקרא, רבים המה, חזר ואמר \u0003הוא\u0004, שכולם עולים ומתקשרים ומחאחדים באחד. והוא הכל. הוא היה והוא הוה והוא יהיה, והוא אחד. ברוך שמו לעולם ולעולמי עולמים. ע\"כ מתקשרים הדברים, ומתאחדים הדברים הקדושים של שם הקב\"ה."],[7,"זכאה חולקיה מאן וכו':","אשרי חלקו מי שקורא אל המלך, ויודע לקראו כראוי, ואם הוא קורא ואינו יודע למי קרא, הקב\"ה מתרחק ממנו, שכתוב, קרוב ה' לכל קוראיו וגו'. למי הוא קרוב. חזר ואמר, לכל אשר יקראוהו באמת. וכי יש מי שיקראוהו בשקר, א\"ר אבא כן. זהו מי שקורא ואינו יודע למי קורא. מאין לנו. כי כתוב, לכל אשר יקראוהו באמת. מהו באמת. היינו בחותם טבעת המלך, שה\"ס קו האמצעי החותם המוחין עם המלכות הנקראת טבעת המלך, שהיא שלמות הכל. ז\"ש תתן אמת ליעקב חסד לאברהם, דהיינו ז\"א, שהוא קו האמצע הנקרא יעקב, שהאמת ניתנה לקו האמצעי. ומשום זה, לכל אשר יקראוהו באמת, כתוב. ומי שאינו יודע לקראו במדת קו האמצעי, אלא שנוטה לקו שמאל או לקו ימין, הרי הקב\"ה מתרחק ממנו. כנ\"ל. אשרי חלקו של מי שנכנס בחכמה, ויצא בשלמות, לדעת דרכיו של הקב\"ה, וע\"כ כתוב, וארח צדיקים כאור נגה וגו'. וכתוב, ועמך כולם צדיקים וגו'."],[8,"תניא א\"ר יצחק וכו':","למדנו, אר\"י, כל אלו התקונים וכל אלו הדברים לקוצרי השדה נמסרו. כלומר לאלו שכבר גמרו עבודת הקדושה והטהרה, וכבר זכו לראות פרי עבודתם. ולמדנו, הרשעים עושים כביכול פגם למעלה. מהו הפגם. הוא כמו שכתוב, שחת לו לא בניו מומם. שהפגם הוא רק כלפי הבנים, שלא יוכלו לקבל שפעם, משום שכל אלו התקונים שנתקנו כדי להשפיע לתחתונים, אינם נמצאים כראוי, מחמת מעשיהם של הרשעים. וז\"ש, בניו מומם. כתוב אחד אומר, וילבש צדקה כשרין. וכתוב אחד אומר, וילבש בגדי נקם תלבושת. אלא א\"ר יצחק, וילבש צדקה, בזמן שישראל כשרים. לא זכו, וילבש בגדי נקם וגו'. וזהו הפגם שהרשעים עושים בתקונים העליונים, שכביכול פושט את לבוש הצדקה, ולובש את בגדי נקם."]],[[0,"","וּמִשּׁוּם זֶה קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ. קֹדֶשׁ יִשְׂרָאֵל נַעֲשֶׂה מֵהֶם. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל מֻכְתָּרִים בְּשָׁלֹשׁ מַדְרֵגוֹת, כַּאֲשֶׁר מִתְחַבְּרִים כְּאֶחָד נִקְרָאִים קֹדֶשׁ יִשְׂרָאֵל לַה', שֶׁהִיא רֵאשִׁית. וַהֲרֵי בֵּאַרְנוּ תְּבוּאָתֹה, בְּהֵ\"א. כָּל אֹכְלָיו יֶאְשָׁמוּ. מַהוּ כָּל אֹכְלָיו יֶאְשָׁמוּ? אָמַר רַבִּי אַבָּא, הֲרֵי נֶאֱמַר, שֶׁכָּתוּב [ויקרא כב] וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה. וְכָתוּב [שם] וְכָל זָר לֹא יֹאכַל קֹדֶשׁ, וְיִשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ, מִשּׁוּם כָּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ."],[1,"","אָמַר רַבִּי אֶלְעָזָר, הַתְחָלָה וְסִיּוּם שֶׁל הַכֹּל נִכְלָל בַּקֹּדֶשׁ. [א'] וְחָכְמָה עֶלְיוֹנָה נִקְרֵאת קֹדֶשׁ, וְכַאֲשֶׁר מְאִירָה הַחָכְמָה הָעֶלְיוֹנָה הַזּוֹ, מְאִירָה חָכְמַת שְׁלֹמֹה, כְּמוֹ שֶׁכָּתוּב [מלכים א ה] וַתֵּרֶב חָכְמַת שְׁלֹמֹה, שֶׁעוֹמֶדֶת הַלְּבָנָה בִשְׁלֵמוּתָהּ, וַהֲרֵי בֵּאַרְנוּ. וְכַאֲשֶׁר מִתְבָּרֶכֶת מֵהַיְסוֹד, כָּךְ קוֹרְאִים לָהּ – קֹדֶשׁ, שֶׁהִיא מְאִירָה בִשְׁלֵמוּת. וְכַאֲשֶׁר לֹא מְאִירָה וְנִכְתֶּרֶת בִּשְׁלֵמוּתָהּ, קוֹרְאִים לָהּ רוּחַ הַקֹּדֶשׁ, וְלֹא נִקְרֵאת קֹדֶשׁ כְּאוֹתוֹ שֶׁל מַעְלָה."],[2,"","וְכַאֲשֶׁר מִתְבָּרְכִים מִזֶּה הַיְסוֹד וּמֵינִיקָה לְכָל אֵלּוּ שֶׁל מַטָּה, נִקְרֵאת אֵם, כְּאוֹתָהּ שֶׁלְּמַעְלָה, וְקוֹרְאִים לָהּ קָדָשִׁים. וְאָז קוֹרְאִים לָהּ קֹדֶשׁ הַקְּדָשִׁים, שֶׁבּוֹ כַלָּה, שֶׁכָּתוּב [שיר השירים ד] אִתִּי מִלְּבָנוֹן כַּלָּה וְגוֹ'. מַהוּ לְבָנוֹן? זֶה עֵדֶן, שֶׁהִלְבִּין מִכָּל הַצְּדָדִים. וְעֵדֶן הֲרֵי יָדוּעַ אֵצֶל הַחֲבֵרִים."],[3,"","לָמַדְנוּ, כָּתוּב כִּי שֵׁם ה' אֶקְרָא. מַהוּ כִּי שֵׁם ה' אֶקְרָא? אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי כָּתוּב הָבוּ גֹדֶל לֵאלֹהֵינוּ. אָמַר רַבִּי אַבָּא, הָבוּ גֹדֶל – זוֹ גְדֻלָּה. הַצּוּר תָּמִים פָּעֳלוֹ – זוֹ גְבוּרָה. כִּי כָל דְּרָכָיו מִשְׁפָּט – זוֹ תִפְאֶרֶת. אֵל אֱמוּנָה – זֶה נֵצַח. וְאֵין עָוֶל – זֶה הוֹד. צַדִּיק – זֶה יְסוֹד. וְיָשָׁר – זֶה צֶדֶק. הֲרֵי הַכֹּל שֵׁם קָדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם זֶה כִּי שֵׁם ה' אֶקְרָא."],[4,"","אָמַר רַבִּי יוֹסֵי, שֵׁם ה' מַמָּשׁ. וּמֹשֶׁה בְּאוֹתָהּ שָׁעָה גִּלָּה לָהֶם לְיִשְׂרָאֵל, שֶׁכָּתוּב [דברים לא] בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם וְגוֹ'. מִכָּאן לָמַדְנוּ, אוֹתוֹ צַדִּיק שֶׁחָכְמָה עֶלְיוֹנָה בוֹ, כַּאֲשֶׁר מַגִּיעַ יוֹמוֹ לְהִסְתַּלֵּק מֵהָעוֹלָם, צָרִיךְ לְגַלּוֹת אוֹתָהּ הַחָכְמָה לְאֵלּוּ שֶׁרוּחַ קְדוֹשָׁה בֵינֵיהֶם. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם, וְכָתוּב [שם] וְעַתָּה כִּתְבוּ לָכֶם אֶת הַשִּׁירָה הַזֹּאת וְגוֹ'."],[5,"","וְאִם לֹא, עָלָיו כָּתוּב, [משלי ג] אַל תִּמְנַע טוֹב מִבְּעָלָיו. כְּמוֹ שֶׁנֶּאֱמַר [משלי ד] כִּי לֶקַח טוֹב נָתַתִּי לָכֶם וְגוֹ'. [משלי ג] בִּהְיוֹת לְאֵל יָדְךְ לַעֲשׂוֹת. טֶרֶם תִּסְתַּלֵּק מִן הָעוֹלָם, וְלֹא נִתְּנָה לְךְ רְשׁוּת לְגַלּוֹת."],[6,"","אָמַר רַבִּי חִיָּיא, פָּסוּק זֶה לָמַדְנוּ מִמֶּנּוּ חָכְמָה עֶלְיוֹנָה, וְכָךְ הוּא. אֲבָל סוֹף הַפָּסוּק מְקַשֵּׁר קֶשֶׁר שֶׁל הָאֱמוּנָה בְּמַה שֶּׁכָּתוּב הוּא, כְּמוֹ שֶׁנֶּאֱמַר צַדִּיק וְיָשָׁר הוּא. כְּלוֹמַר, הוּא הַכֹּל, הוּא אֶחָד בְּלֹא פֵרוּד. שֶׁאִם תֹּאמַר שֶׁכָּל אֵלּוּ רַבִּים הֵם – חָזַר וְאָמַר הוּא, כֻּלָּם עוֹלִים וּמִתְקַשְּׁרִים וּמִתְאַחֲדִים בְּאֶחָד. וְהַכֹּל – הוּא הָיָה, וְהוּא הֹוֶה, וְהוּא יִהְיֶה, וְהוּא אֶחָד. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. [על] עַד כָּאן מִתְקַשְּׁרִים דְּבָרִים וּמִתְאַחֲדִים דְּבָרִים קְדוֹשִׁים שֶׁל שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁקּוֹרֵא לַמֶּלֶךְ וְיוֹדֵעַ לִקְרֹא כְּמוֹ שֶׁצָּרִיךְ. וְאִם הוּא קוֹרֵא וְלֹא יוֹדֵעַ לְמִי קוֹרֵא, מִתְרַחֵק הַקָּדוֹשׁ בָּרוּךְ הוּא מִמֶּנּוּ, שֶׁכָּתוּב [תהלים קמה] קָרוֹב ה' לְכָל קֹרְאָיו וְגוֹ'. קָרוֹב ה' לְכָל קֹרְאָיו, לְמִי קָרוֹב? חָזַר וְאָמַר, לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת. וְכִי יֵשׁ מִי שֶׁיִּקְרָא לוֹ בְשֶׁקֶר? אָמַר רַבִּי אַבָּא, כֵּן, אוֹתוֹ מִי שֶׁקּוֹרֵא וְלֹא יוֹדֵעַ לְמִי קוֹרֵא. מִנַּיִן לָנוּ? שֶׁכָּתוּב לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת. מַהוּ בֶאֱמֶת? בַּחֲתִימָה שֶׁל חוֹתֶמֶת הַמֶּלֶךְ, שֶׁהוּא שְׁלֵמוּת הַכֹּל. זֶהוּ שֶׁכָּתוּב [מיכה ז] תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם. וּמִשּׁוּם כָּךְ, לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת כָּתוּב. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּכְנַס וְיָצָא לָדַעַת דְּרָכָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה כָתוּב, [משלי ד] וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ וְגוֹ'. וְכָתוּב [ישעיה ס] וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'."],[8,"","לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, כָּל אֵלּוּ הַתִּקּוּנִים וְכָל אֵלּוּ הַדְּבָרִים נִמְסְרוּ לְקוֹצְרֵי הַשָּׂדֶה. וְלָמַדְנוּ, רְשָׁעִים כִּבְיָכוֹל עוֹשִׂים פְּגָם לְמַעְלָה. אֵיזֶה פְגָם? כְּמוֹ שֶׁכָּתוּב, שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם, שֶׁהֲרֵי כָּל אֵלּוּ הַתִּקּוּנִים לֹא נִמְצָאִים כְּמוֹ שֶׁצָּרִיךְ. כָּתוּב אֶחָד אוֹמֵר, [ישעיה נט] וַיִּלְבַּשׁ צְדָקָה כַּשִּׁרְיָן, וְכָתוּב אֶחָד אוֹמֵר, [שם] וַיִּלְבַּשׁ בִּגְדֵי נָקָם תִּלְבֹּשֶׁת. אֶלָּא אָמַר רַבִּי יִצְחָק, וַיִּלְבַּשׁ צְדָקָה – בִּזְמַן שֶׁיִּשְׂרָאֵל זַכָּאִים. לֹא זָכוּ – וַיִּלְבַּשׁ בִּגְדֵי נָקָם וְגוֹ'."]]],[["אָמַר רִבִּי יוֹסֵי מַאי פְּגִימוּתָא. כְּמָה דְּתָנֵינָן, דַּאֲבָהָן לָא מִסְתַּפְּקִין (ס\"א מסתפקן) לְאִתְבָּרְכָא מֵהַהוּא שַׁקְיוּ דְּנַחֲלָא. כָּל שֶׁכֵּן בְּנִין. כְּמָה דְאַתְּ אָמֵר, שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מַאי לוֹ לֹא תְּרֵי זִמְנֵי. אֶלָּא חַד לְעֵילָּא, וְחַד לְתַתָּא.","וְהַיְינוּ דְּאָמַר רִבִּי שִׁמְעוֹן, כָּל זִמְנָא דְּחַיָּיבַיָּא סְגִּיאוּ בְּעָלְמָא, כִּבְיָכוֹל שְׁמָא קַדִּישָׁא לָא מִתְבְּרַךְ בְּעָלְמָא. וְכָל זִמְנָא דְּחַיָּיבַיָּא לָא סְגִּיאוּ בְּעָלְמָא, שְׁמָא קַדִּישָׁא מִתְבְּרַךְ בְּעָלְמָא. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:א׳) יִתַּמּוּ חַטָּאִים וְגוֹ', בָּרְכִי נַפְשִׁי אֶת יְיָ' הַלְלוּיָהּ. אָמַר רִבִּי אַבָּא, מִקְרָא זֶה מַמָּשׁ הוּא, דִּכְתִּיב שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מַאן גָּרִים לְחַבְּלוּתָא דָּא. דּוֹר עִקֵּשׁ וּפְתַלְתּוֹל, בְּגִין דְּאִינּוּן חַיָּיבַיָּא וְדָרָא אִשְׁתְּכַח הָכִי.","בְּגִין כָּךְ בָּתַר דְּאָמַר מֹשֶׁה כָּל הָנֵי מִלִּין, וְאַדְכַּר שְׁמָא קַדִּישָׁא כַּדְּקָא יָאוּת, אָמַר וַדַּאי צַדִּיק וְיָשָׁר הוּא, מִלָּה בְּתִקּוּנֵיהּ. אֲבָל שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מַאי טַעְמָא הָכִי. מִשּׁוּם דְּאִינּוּן דּוֹר עִקֵּשׁ וּפְתַלְתּוֹל. אָמַר רִבִּי יְהוּדָה, לוֹ לֹא, כְּלוֹמַר לְגַרְמַיְיהוּ עַבְדִּין דָּא חַיָּיבִין, דְּגַרְמִין לְאִסְתַּלְּקָא בִּרְכָאן מֵעָלְמָא. אָמַר רִבִּי אַבָּא, לוֹ לֹא, הָא אוֹקִימְנָא וְהָכִי הוּא. מַה כְּתִיב בַּתְרֵיהּ. הַלְיְיָ' תִּגְמְלוּ זֹאת, לְשַׁלָּמָא גְּמוּל דָּא לְּקוּדְשָׁא בְּרִיךְ הוּא, עַל כָּל אִינּוּן טָבָאן דְּגָרִים לָךְ, וְעָבִיד לָקֳבְלָךְ.","רִבִּי אֶלְעָזָר פָּתַח, (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ'. זַכָּאִין אִינּוּן יִשְׂרָאֵל, עַל כָּל עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּאַף עַל גַּב דְּאַרְגִּיזוּ קָמֵי מָארֵיהוֹן, קוּדְשָׁא בְּרִיךְ הוּא לָא בָּעֵי לְשַׁבְקָא לוֹן. דִּבְכָל אֲתָר דְּגָלוּ בֵּינֵי עַמְמַיָּא, קוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן בְּגָלוּתָא. הֲדָא הוּא דִכְתִיב וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ'.","רִבִּי אַבָּא אָמַר, וְאַף גַּם זֹאת בִּהְיוֹתָם. תָּא חֲזֵי, כַּמָה חֲבִיבוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּיהוֹן דְּיִשְׂרָאֵל, דְּאַף עַל גַּב דְּגַרְמִין לְמִגְלֵי בֵּינֵי עַמְמַיָּא, שְׁכִינְתָּא לָא אִתְעֲדִיאַת מִנְּהוֹן לְעָלְמִין. דְּלָא תֵּימָא דְּאִינּוּן בִּלְחוֹדַיְיהוּ בְּגָלוּתָא מִשְׁתַּכְּחִין. אֶלָּא וְאַף גַּם זֹאת עִמְּהוֹן מִשְׁתַּכְּחִין. הֲדָא הוּא דִכְתִיב וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ'.","לְמַלְכָּא דְּאַרְגִּיז עַל בְּרֵיהּ, גָּזַר עָלֵיהּ עוֹנְשָׁא לְאִתְרַחֲקָא מִנֵּיהּ, וּלְמֵיזַל לְאַרְעָא רְחִיקָא. שְׁמָעָה מַטְרוֹנִיתָא וְאָמְרָה, הוֹאִיל וּבְרִי אָזִיל לְאַרְעָא רְחִיקָא, וְשַׁדֵי לֵיהּ מַלְכָּא מֵהֵיכָלֵיהּ, אֲנָא לָא אֶשְׁבּוֹק לֵיהּ, אוֹ תַּרְוָונָא כַּחֲדָא נִיתוּב לְהֵיכָלָא דְּמַלְכָּא אוֹ תַּרְוָונָא כַּחֲדָא נֵיתִיב בְּאַרְעָא אַחֲרָא. לְזִמְנִין, פָּקִיד מַלְכָּא עַל מַטְרוֹנִיתָא, לָא אַשְׁכְּחָהּ. דַּהֲוַות אַזְלַת עִם בְּרֵיהּ, אָמַר, הוֹאִיל וּמַטְרוֹנִיתָא תַּמָּן, תַּרְוַויְיהוּ יְתוּבוּן.","וּבְזִמְנָא דְּפָקִיד קוּדְשָׁא בְּרִיךְ הוּא לְמַטְרוֹנִיתָא, פָּקִיד לָהּ בְּקַדְמִיתָא, וּבְגִינָהּ פָּקִיד לִבְנוֹי. הֲדָא הוּא דִכְתִיב, (שמות ו׳:ה׳) וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. מַאן גָּרִים דַּאֲנָא שְׁמַעְנָא עֲקַתְהוֹן. כִּבְיָכוֹל, מַטְרוֹנִיתָא. דִּדְכַרְנָא לָהּ. הֲדָא הוּא דִכְתִיב, (שמות ו׳:ה׳) וָאֶזְכּוֹר אֶת בְּרִיתִי. וּכְתִיב (שמות ב׳:כ״ד) וַיִּזְכּוֹר אֱלֹהִים אֶת בְּרִיתוֹ. וְכַד קוּדְשָׁא בְּרִיךְ הוּא יֵהָדַר לְיִשְׂרָאֵל מִן גָּלוּתָא, מַה כְּתִיב. (דברים ל׳:ג׳) וְשָׁב יְיָ' אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְרִחֲמֶךָ, דָּא מַטְרוֹנִיתָא. וְעוֹד כְּתִיב, (תהילים פ״ה:ב׳) רָצִיתָ יְיָ' אַרְצֶךָ שַׁבְתָּ שְׁבוּת יַעֲקֹב.","אָמַר רִבִּי יְהוּדָה, הַלְיְיָ' תִּגְמְלוּ זֹאת, בְּגִין דְּאַתּוּן דּוֹר עִקֵּשׁ וּפְתַלְתּוֹל, אַתּוּן הֲוֵיתוּן גַּרְמִין דְּתִגְלֵי זֹאת בְּגָלוּתָא. הַלְיְיָ' תִּגְמְלוּ זֹאת. דָּא הוּא גְּמוּל דְּעָבִיד עִמְּכוֹן, בְּכָל אִינּוּן נִימוּסִין דְּמִצְרַיִם, בְּכָל אִינּוּן אַתְוָון דְּעָבַד לְכוּ, דָּא הוּא גְּמוּל דְּאַתּוּן שָׁלְמִין לְהַאי זֹאת. מַאן גָּרַם לְכוֹן דָּא. בְּגִין דְּאַתּוּן עַם נָבָל וְלֹא חָכָם, וְלָא מִסְתַּכְּלִין בְּכָל אִינּוּן טָבָן דְּעָבַד לְכוּ עַד הַשְׁתָּא.","הַלְיְיָ' תִּגְמְלוּ זֹאת, דָּא שְׁכִינְתָּא. וְהָא אוֹקִימְנָא מִלֵּי, דְּתַנִינָן, הֵ\"א דִּבְּהִבָּרְאָם, (בראשית ב) זְעֵירָא. הֵ\"א דִּבְהַלְיְיָ' רַבְרְבָא. וְהָא אִתְּמַר דְּתַנְיָא, אָמַר רִבִּי יְהוּדָה, הֵ\"א דִּבְכָל אֲתָר קוּדְשָׁא בְּרִיךְ הוּא, וְאִקְרֵי אֵם. וּתְרֵי עָלְמִין נִינְהוּ, דִּכְתִּיב, (תהילים ק״ו:מ״ח) מִן הָעוֹלָם וְעַד הָעוֹלָם. וְהָא תָּנֵינָן בְּרָזָא דִּקְרָא, (במדבר כ״ח:ה׳) בְּשֶׁמֶן כָּתִית רְבִיעִית הַהִין."],[[0,"א\"ר יוסי מאי וכו':","אר\"י מהו הפגם, שהרשעים עושים במעשיהם למעלה. הוא כמו שלמדנו, שהאבות שהם חג\"ת אינם מקבלים הספקה להתברך מאותו שיקוי של הנחל, שהוא שפע הבינה. וכל שכן הבנים. כי כיון שהם אינם מקבלים השפע בשביל התחתונים, נעשה מום ופגם למטה. כש\"א שחת לו לא בניו מומם, מהו לו לא ב' פעמים, היה מספיק שיאמר שחת לו בניו מומם. אלא אחד למעלה שנעשה פגם למעלה שאינם מקבלים הברכות. שע\"ז נאמר שחת לו. ואחד למטה, שהם חסרים מכל. וע\"ז נאמר לא בניו מומם. כלומר שאין זה נחשב למום כלפי מעלה אלא כלפי הבנים, שהם ישראל."],[1,"והיינו דאר\"ש כל וכו':","והיינו שא\"ר שמעון, כל זמן שהרשעים מרובים בעולם, כביכול השם הקדוש אינו מתברך בעולם. וכל זמן שהרשעים אינם מרובים בעולם, השם הקדוש מתברך בעולם. ז\"ש, יתמו חטאים וגו' ברכי נפשי את ה' הללויה. א\"ר אבא, מקרא זה ממש הוא, שכתוב, שחת לו לא בניו מומם. מי גרם למום הזה, דור עקש ופתלתול, משום שאלו הרשעים והדור נמצאים כך."],[2,"בג\"כ בתר דאמר וכו':","משום זה, אחר שאמר משה כל אלו הדברים, והזכיר השם הקדוש כראוי, אמר, ודאי צדיק וישר הוא, שהדבר הוא בתקונו, אבל שחת לו לא בניו מומם, מהו הטעם שהוא כך, משום שהם דור עקש ופתלתול. א\"ר יהודה, \u0003לו לא\u0004, כלומר, אלא לעצמם עושים הרשעים את זה, שגורמים שיסתלקו הברכות מן העולם. אר\"א, \u0003לו לא\u0004, הרי העמדנו. וכך הוא. מה כתוב אחריו, הלהויה תגמלו זאת. היינו, אתם משלמים גמול זה להקב\"ה, על כל הטובות שגרם לכם ועשה לפניכם."],[3,"ר\"א פתח ואף וגו':","רא\"פ, ואף גם זאת בהיותם בארץ אויביהם וגו'. אשרי הם ישראל על כל העמים עכו\"ם, שאע\"פ שהכעיסו לפני אדונם, הקב\"ה אינו רוצה לעזוב אותם, שבכל מקום שגלו בין העמים הקב\"ה נמצא עמהם בגלות. ז\"ש, ואף גם זאת בהיותם בארץ אויביהם וגו'."],[4,"ר' אבא אמר וכו':","רא\"א, ואף גם זאת בהיותם. בוא וראה, כמה היא אהבת הקב\"ה לישראל, שאע\"פ שגרמו להיות בגלות בין העמים, השכינה אינה סרה מהם לעולם. ואל תאמר, שהם בלבדם נמצאים בגלות, אלא, ואף גם \u0003זאת\u0004, שהיא השכינה הנקראת זאת, נמצאת עמהם. ז\"ש, אף גם \u0003זאת\u0004 בהיותם בארץ אויביהם וגו'."],[5,"למלכא דארגיז על וכו':","למלך שכעס על בנו, וגזר עליו עונש שיתרחק ממנו וילך לארץ רחוקה, שמעה המלכה ואמרה, כיון שבני הולך לארץ רחוקה, והמלך השליכו מהיכלו, אני לא אעזבנו, או שנינו יחד נחזור להיכל המלך, או שנינו יחד נשב בארץ אחרת. לימים, פקד המלך את המלכה, ולא מצאה, כי הלכה עם בנו. אמר, כיון שהמלכה שם, שניהם ישובו."],[6,"ובזמנא דפקיד וכו':","כך הוא בזמן שיפקוד הקב\"ה את השכינה, יפקוד אותה תחילה, ובשבילה יפקוד לבניו. ז\"ש, וגם אני שמעתי את נאקת בני ישראל וגו'. מי גרם שאני שמעתי נאקתם, כביכול השכינה גרמה, שזכרתי אותה. ז\"ש ואזכור את בריתי. דהיינו השכינה הנקראת ברית. וכתוב, ויזכור אלקים את בריתו. וכשהקב\"ה יחזיר את ישראל מן הגלות, מה כתוב, ושב ה' אלקיך את שבותך ורחמך, זו היא השכינה, שעליה נאמר, \u0003ושב\u0004 וגו' את שבותך. ועוד כתוב, רצית ה' \u0003ארצך\u0004 שבת שבות יעקב. דהיינו השכינה הנקראת ארץ."],[7,"א\"ר יהודה הלה' וכו':","אר\"י, הלהויה תגמלו \u0003זאת\u0004, הרי אתם, דור עקש ופתלתול, אתם גרמתם להגלות את \u0003זאת\u0004 בגלות, הלהויה תגמלו \u0003זאת\u0004, זה הוא הגמול על מה שעשה עמכם, בכל אלו המעשים שבמצרים, בכל אלו האותות שעשה לכם, זה הוא הגמול שאתם משלמים ל \u0003זאת\u0004 הזו. מי גרם לכם את זה, הוא משום שאתם, עם נבל ולא חכם, שאינכם מסתכלים בכל הטוב שעשה לכם עד עתה."],[8,"הלהויה תגמלו זאת:","זאת היא השכינה. והנה העמדנו הדברים, שלמדנו, \u0003ה'\u0004 דהבראם היא קטנה, הרומזת למלכות. \u0003ה'\u0004 דבהלהויה, היא גדולה, שרומזת לבינה. והנה אמרו, שלמדנו, א\"ר יהודה \u0003ה'\u0004 בכל מקום רומזת על הקב\"ה, ונקראת אם. אלא ששני עולמות הם, שהם בינה ומלכות, שכתוב עליהם, מן העולם ועד העולם. דהיינו מבינה למלכות, וזה למדנו, בסוד הכתוב, בשמן כתית רביעית ההין, שפירושו, אשר יסוד דז\"א ממשיך השמן מעולם העליון אל עולם התחתון שהוא מלכות וז\"ש הלהויה תגמלו זאת, שזה כולל ג' מדרגות יחד, שהן, עולם העליון, שהוא \u0003ה'\u0004 גדולה של הלהויה, והויה עצמה, שהוא ז\"א הממשיך ממנה השפע אל \u0003זאת\u0004 שהיא השכינה."]],[[0,"","אָמַר רַבִּי יוֹסֵי, מָה הַפְּגָם? כְּמוֹ שֶׁלָּמַדְנוּ, שֶׁהָאָבוֹת לֹא מִסְתַּפְּקִים [מסתפקים] לְהִתְבָּרֵךְ מֵאוֹתָהּ הַהַשְׁקָיָה שֶׁל הַנַּחַל, כָּל שֶׁכֵּן הַבָּנִים, כְּמוֹ שֶׁנֶּאֱמַר שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מַהוּ לוֹ לֹא – שְׁתֵּי פְעָמִים. אֶלָּא אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה."],[1,"","וְזְהִוּ שֶׁאָמַר רַבִּי שִׁמְעוֹן, כָּל זְמַן שֶׁהָרְשָׁעִים מִתְרַבִּים בָּעוֹלָם, כִּבְיָכוֹל שֵׁם הַקָּדוֹשׁ לֹא מִתְבָּרֵךְ בָּעוֹלָם. וְכָל זְמַן שֶׁהָרְשָׁעִים לֹא מִתְרַבִּים בָּעוֹלָם, שֵׁם הַקָּדוֹשׁ מִתְבָּרֵךְ בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב [תהלים קד] יִתַּמּוּ חַטָּאִים וְגוֹ', בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. אָמַר רַבִּי אַבָּא, מִקְרָא זֶה מַמָּשׁ הוּא, שֶׁכָּתוּב שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מִי גוֹרֵם לְמוּם זֶה? דּוֹר עִקֵּשׁ וּפְתַלְתֹּל. מִשּׁוּם שֶׁאֵלּוּ הָרְשָׁעִים וְהַדּוֹר נִמְצָא כָּךְ."],[2,"","מִשּׁוּם זֶה, אַחַר שֶׁאָמַר מֹשֶׁה כָּל אֵלּוּ הַדְּבָרִים וְהִזְכִּיר הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁצָּרִיךְ, אָמַר, וַדַּאי צַדִּיק וְיָשָׁר הוּא, דָּבָר כְּתִקּוּנוֹ. אֲבָל שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מָה הַטַּעַם כָּךְ? מִשּׁוּם שֶׁהֵם דּוֹר עִקֵּשׁ וּפְתַלְתֹּל. אָמַר רַבִּי יְהוּדָה, לוֹ לֹא, כְּלוֹמַר לְעַצְמָם עוֹשִׂים כָּךְ הָרְשָׁעִים, שֶׁגּוֹרְמִים לַבְּרָכוֹת לְהִסְתַּלֵּק מֵהָעוֹלָם. אָמַר רַבִּי אַבָּא, לוֹ לֹא, הֲרֵי בֵּאַרְנוּ וְכָךְ הוּא. מַה כָּתוּב אַחֲרָיו? הַלְה' תִגְמְלוּ זֹּאת, לְשַׁלֵּם גְּמוּל זֶה לְהַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּל אֵלּוּ הַטּוֹבוֹת שֶׁגָּרַם לְךְ וְעָשָׂה עֲבוּרְךְ."],[3,"","רַבִּי אֶלְעָזָר פָּתַח, [ויקרא כו] וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם וְגוֹ'. זַכָּאִים הֵם יִשְׂרָאֵל עַל כָּל אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁאַף עַל גַּב שֶׁהִרְגִּיזוּ לִפְנֵי אֲדוֹנָם, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה לַעֲזֹּב אוֹתָם. שֶׁבְּכָל מָקוֹם שֶׁגָּלוּ בֵּין הָעַמִּים, הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהֶם בַּגָּלוּת. זֶהוּ שֶׁכָּתוּב וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם וְגוֹ'."],[4,"","רַבִּי אַבָּא אָמַר, וְאַף גַּם זֹּאת בִּהְיוֹתָם. בֹּא רְאֵה כַּמָּה הַחֲבִיבוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלַפֵּי יִשְׂרָאֵל, שֶׁאַף עַל גַּב שֶׁגּוֹרְמִים לִגְלוֹת בֵּין הָעַמִּים, הַשְּׁכִינָה לֹא סָרָה מֵהֶם לְעוֹלָמִים. שֶׁלֹּא תֹאמַר שֶׁהֵם לְבַדָּם בַּגָּלוּת נִמְצָאִים, אֶלָּא – וְאַף גַּם זֹּאת, עִמָּהֶם נִמְצָאִים. זֶהוּ שֶׁכָּתוּב וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם וְגוֹ'."],[5,"","לְמֶלֶךָ שֶׁהִתְרַגֵּז עַל בְּנוֹ, גָּזַר עָלָיו עֹנֶשׁ לְהִתְרַחֵק מִמֶּנּוּ וְלָלֶכֶת לְאֶרֶץ רְחוֹקָה. שָׁמְעָה הַמַּלְכָּה וְאָמְרָה: הוֹאִיל וּבְנִי הוֹלֵךְ לְאֶרֶץ רְחוֹקָה וּמַשְׁלִיךְ אוֹתוֹ הַמֶּלֶךְ מֵהֵיכָלוֹ, אֲנִי לֹא אֶעֱזֹּב אוֹתוֹ. אוֹ שְׁנֵינוּ כְאֶחָד נָשׁוּב לַהֵיכָל שֶׁל הַמֶּלֶךְ, אוֹ שְׁנֵינוּ כְאֶחָד נֵשֵׁב בְּאֶרֶץ אַחֶרֶת. לְעִתִּים פּוֹקֵד הַמֶּלֶךְ עַל הַמַּלְכָּה, וְלֹא מוֹצְאָהּ, שֶׁהָיְתָה הוֹלֶכֶת עִם בְּנוֹ. אָמַר: הוֹאִיל וְהַמַּלְכָּה שָׁם, שְׁנֵיהֶם יָשׁוּבוּ."],[6,"","וּבִזְמַן שֶׁיִּפְקֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לַמַּלְכָּה, פּוֹקֵד אוֹתָהּ בַּתְּחִלָּה, וּבִגְלָלָהּ פּוֹקֵד אֶת בָּנָיו. זֶהוּ שֶׁכָּתוּב [שמות ו] וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. מִי גוֹרֵם שֶׁאֲנִי שׁוֹמֵעַ צָרָתָם? כִּבְיָכוֹל הַמַּלְכָּה. שֶׁאֲנִי זוֹכֵר אוֹתָהּ. זֶהוּ שֶׁכָּתוּב [שם] וָאֶזְכֹּר אֶת בְּרִיתִי. וְכָתוּב [שם ב] וַיִּזְכֹּר הָאֱלֹהִים אֶת בְּרִיתוֹ. וְכַאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא יַחֲזִיר אֶת יִשְׂרָאֵל מִן הַגָּלוּת, מַה כָּתוּב? [דברים ל] וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְרִחֲמֶךְ. זוֹ הַמַּלְכָּה. וְעוֹד כָּתוּב, [תהלים פה] רָצִיתָ ה' אַרְצֶךְ שַׁבְתָּ שְׁבוּת יַעֲקֹב."],[7,"","אָמַר רַבִּי יְהוּדָה, הַלְה' תִּגְמְלוּ זֹּאת, מִשּׁוּם שֶׁאַתֶּם דּוֹר עִקֵּשׁ וּפְתַלְתֹּל, אַתֶּם הֱיִיתֶם גּוֹרְמִים שֶׁתִּגְלֶה זֹּאת בַּגָּלוּת. הַלְה' תִּגְמְלוּ זֹּאת?! זֶהוּ הַגְּמוּל שֶׁעָשָׂה עִמָּכֶם בְּכָל אוֹתָם מוֹפְתִים שֶׁל מִצְרַיִם, בְּכָל אוֹתָם אוֹתוֹת שֶׁעָשָׂה לָכֶם, הֲזֶהוּ הַגְּמוּל שֶׁאַתֶּם מְשַׁלְּמִים לָזֹּאת הַזּוֹ?! מִי גָרַם לָכֶם זֶה? מִשּׁוּם שֶׁאַתֶּם עַם נָבָל וְלֹא חָכָם, וְלֹא מִסְתַּכְּלִים בְּכָל אוֹתָן טוֹבוֹת שֶׁעָשָׂה לָכֶם עַד עַתָּה."],[8,"","הַלְה' תִּגְמְלוּ זֹּאת – זוֹ הַשְּׁכִינָה. וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים, שֶׁלָּמַדְנוּ, אוֹת הֵ\"א שֶׁל בְּהִבָּרְאָם [בראשית ב] – קְטַנָּה. הֵ\"א שֶׁבְּהַלְה' – גְּדוֹלָה. וַהֲרֵי נִתְבָּאֵר שֶׁלָּמַדְנוּ, אָמַר רַבִּי יְהוּדָה, הֵ\"א שֶׁבְּכָל מָקוֹם – הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִקְרֵאת אֵם. וּשְׁנֵי עוֹלָמוֹת הֵם, שֶׁכָּתוּב [תהלים קו] מִן הָעוֹלָם וְעַד הָעוֹלָם. וַהֲרֵי לָמַדְנוּ בְסוֹד הַפָּסוּק, [במדבר כח] בְּשֶׁמֶן כָּתִית רְבִיעִת הַהִין."]]],[["תַּנְיָא רִבִּי יְהוּדָה אוֹמֵר, בְּכַמָּה אַתְרֵי אִסְתְּכַּלְנָא, דְקוּדְשָׁא בְּרִיךְ הוּא לָא אַעְדֵּי רְחִימוּתָא מִנַּיְיהוּ דְּיִשְׂרָאֵל, דִּבְכָל אֲתָר דְּאִינּוּן הָווֹ, קוּדְשָׁא בְּרִיךְ הוּא בֵּינַיְיהוּ. דִּכְתִּיב, (ויקרא כ״ו:מ״ד) לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלּוֹתָם לְהָפֵר בְּרִיתִי אִתָּם. דַּיְיקָא אִתָּם, בֵּינַיְיהוּ עִמְּהוֹן לָא אַעְדֵּי מִנַּיְיהוּ לְעָלְמִין.","רִבִּי יִצְחָק הֲוָה אָזִיל בְּאָרְחָא, וְפָגַע בֵּיהּ רִבִּי חִיָּיא, אָמַר לֵיהּ חֲמֵינָא (להו) בְּאַנְפָּךְ, דְּהָא בְּמָדוֹרָא דִּשְׁכִינְתָּא מָדוֹרָךְ. מַאי כְּתִיב. (שמות ג׳:ח׳) וָאֵרֵד לְהַצִּילוֹ מִיַּד מִצְרַיִם. וָאֵרֵד, אֵרֵד מִבָּעֵי לֵיהּ. וָאֵרֵד בְּקַדְמִיתָא. אֵימָתַי. כַּד נָחַת יַעֲקֹב לְמִצְרַיִם. וְלָמָּה. לְהַצִּילוֹ מִיַּד מִצְרַיִם. דְּאִלְמָלֵא לָא הֲוָה בֵּינַיְיהוּ, לָא יַכְלִין לְמִסְבַּל גָּלוּתָא. כְּמָה דְאַתְּ אָמֵר (תהילים צ״א:ט״ו) עִמּוֹ אָנֹכִי בְצָרָה אֲחַלְצֵהוּ וַאֲכַבְּדֵהוּ.","אָמַר לֵיהּ, וַדַּאי בְּכָל אֲתָר דְּיִשְׂרָאֵל שַׁרְיָין, קוּדְשָׁא בְּרִיךְ הוּא בֵּינַיְיהוּ. וְכָל אֲתָר דְּחַכִּימֵי דָּרָא אַזְלִין, קוּדְשָׁא בְּרִיךְ הוּא אָזִיל עִמְּהוֹן, דִּכְתִּיב, (שם) כִּי מַלְאָכָיו יְצַוֶּה לָךָ וְגוֹ'. מְנָלָן דִּכְתִּיב, (בראשית ל״ב:ג׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וְגוֹ', וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. הַשְׁתָּא נִשְׁתַּתֵּף כַּחֲדָא, וְנֵיזִיל בְּאָרְחָא, דְּהָא יְדַעְנָא דִּלְאֲתָר חַד אַזְלֵינָן, לְקַבְּלָא אַנְפּוֹי דִּשְׁכִינְתָּא. אָמַר לֵיהּ, וַדַּאי. אָמַר רִבִּי יִצְחָק, תָּנֵינָן, שְׁלוּחֵי מִצְוָה אֵינָן נִיזוֹקִין, לָא בַּהֲלִיכָתָן וְלָא בַּחֲזָרָתָן. וַאֲנָן לְאִתְחֲזָאָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא אַזְלֵינָן, וְלָא דָּחִילְנָא.","עַד דַּהֲווֹ אָזְלֵי, אָמַר רִבִּי חִיָּיא, כְּתִיב (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. הַשָּׁמַיִם, לְאַכְלְלָא קוּדְשָׁא בְּרִיךְ הוּא. וְהָאָרֶץ, לְאַכְלְלָא קוּדְשָׁא בְּרִיךְ הוּא וְכָל מַה דִּלְתַתָּא, אִינּוּן אִקְרוּן תוֹלְדוֹת הַשָּׁמַיִם מִנַיְיהוּ.","אָמַר לֵיהּ אִי הָכִי מַהוּ בְּהִבָּרְאָם, וְאִתְּמַר בְּה' בְּרָאָם. אָמַר לֵיהּ כֹּלָּא חַד מִלָּה, כַּד שָׁמַיִם אִתְחַבָּרוּ, הַאי ה' אַפִּיקַת תּוֹלְדוֹת, וְאִינּוּן אִקְרוּן תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. אָמַר לֵיהּ אִי הָכִי, בְּמַאי אוֹקִימְנָא בְּה' בְּרָאָם, בְּאַבְרָהָם. אָמַר לֵיהּ כֹּלָּא חַד מִלָּה הוּא, בְּאַבְרָהָם, הַיְינוּ הַשָּׁמַיִם, דְּמִתַּמָּן שַׁרְיָין לְאִתְפַּשְׁטָא. בְּה' בְּרָאָם, הַיְינוּ וְהָאָרֶץ, וְכֹלָּא חַד מִלָּה.","אָמַר לֵיהּ, וַדַּאי הָכִי הוּא, וְהָא אוֹלִיפְנָא, דִּכְתִּיב, אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. וְתָנֵינָן, הָעוֹלָם הַזֶּה נִבְרָא בְּה', דִּכְתִּיב בְּהִבָּרְאָם. וְהָעוֹלָם הַבָּא, נִבְרָא בְּי', דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. לְאַכְלְלָא הַשָּׁמַיִם. אֶת הַגָּן, לְאַכְלְלָא אֶת הָאָרֶץ.","וְהָא אוֹקִימְנָא, דִּכְתִּיב, (שיר השירים ד׳:ט״ו) מַעְיַן גַּנִּים, דָּא הִיא הַשָּׁמַיִם, בְּאֵר מַיִם חַיִּים, דִּכְתִּיב, (בראשית כז) וַיִּכְרוּ שָׁם עַבְדֵי יִצְחָק בְּאֵר, דִּכְתִיב (שם) וַיַּעְתֵּק מִשָּׁם וַיַחְפּוֹר בְּאֵר אַחֶרֶת וְגוֹ'. וְנוֹזְלִין מִן לְבָנוֹן, דְּאִינּוּן מִתְעַטְּרִין לְעֵילָּא, וְסַלְּקִין בְּרֵישָׁא דְּמַלְכָּא. דִּכְתִּיב, (תהילים ק״ח:ה׳) כִּי גָּדוֹל מֵעַל שָׁמַיִם חַסְדֶּךָ.","מִן לְבָנוֹן, מִתַּמָּן נָפְקִין לְבִינָה. וְנָגִיד וְאִתְמְשַׁךְ לְכָל זִוְויָין, עַד דְּנַגְדִּין אִינּוּן מַבּוּעִין, וְנַחְתִּין לְאִתְכַּנְּשָׁא לְאֲתָר דְּאִקְרֵי יַמָּא רַבָּא. דִּכְתִּיב, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹ'. וּכְתִיב, (ישעיהו נ״א:א׳) הַבִּיטוּ אֶל צוּר חוּצַּבְתֶּם וְגוֹ'. לְבָתַר כְּתִיב, (שיר השירים ד׳:י״ב) גַּן נָעוּל אֲחוֹתִי כַלָּה וְגוֹ'. וּמִכָּאן, נְפִיקוּ תּוֹלְדוֹת לְכֹלָּא. דִּכְתִּיב, בְּהִבָּרְאָם, בְּה' בְּרָאָם מַמָּשׁ, בְּאַבְרָהָם. אָמַר רִבִּי יִצְחָק, וַאֲפִילּוּ בְּיַעֲקֹב מַמָּשׁ. וְכֹלָּא חַד מִלָּה.","אָמַר רִבִּי יִצְחָק, כַּד אֲנָן יַתְבִין לְקַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, כֹּלָּא אִתְּמַר קַמֵּיהּ בְּאִתְגַּלְיָא, וְלָא אִצְטְרִיכְנָא לְכָל הַאי. אָמַר לֵיהּ, לָאו רִבִּי שִׁמְעוֹן כִּשְׁאַר בְּנֵי נָשָׁא, דְּכֻלְּהוּ קַמֵּיהּ, כִּשְׁאַר נְבִיאֵי לְקַמֵּי מֹשֶׁה. עַד דַּהֲווֹ אָזְלֵי, אָמַר רִבִּי חִיָּיא, כְּתִיב, (ישעיהו מ״ט:ט״ו) הֲתִשְׁכַּח אִשָּׁה עוּלָהּ מֵרַחֵם בֶּן בִּטְנָּה וְגוֹ'. הַאי קְרָא אוֹקְמוּהָ, וְהָכָא מַאי קָא מַיְירֵי. אָמַר רִבִּי יִצְחָק, אִי בְּקִטוּרָא דְּחַבְרַיָּיא, סְמִיכָא לָא אַסְמַכְנָא, אֲנָן מַה נֵימָא.","אָמַר לֵיהּ, דְּהָא קָלָא דִּרְמִיזָא חַד, שְׁמַעְנָא יוֹמָא חַד, כַּד הֲוָה אֲזִילְנָא בְּאָרְחָא, וְלָא יְדַעְנָא מַאן אָמַר, וְלָא יְדַעְנָא מִלָּה. וְתָּא חֲזֵי, ז' יוֹמִין הֲווֹ דַּחֲלִישְׁנָא עַל דָּא, וְלָא טַעִימְנָא מִדִי. וְהַשְׁתָּא אֲזִלְנָא לְגַבֵּיהּ דְּבוּצִינָא קַדִּישָׁא, דְּלֵימָא לִי דִּילְמָא אֵדְכַר. אָמַר לֵיהּ, דִּילְמָא הַהוּא יוֹמָא דְּהֲוָה אָזִיל רִבִּי אֶלְעָזָר לְגַבֵּיהּ דְּחָמוּי, וְהַהוּא יוֹמָא אֲזִילְנָא עִמֵּיהּ, וְהָא אַדְכַּרְנָא מִלָּה.","תָּא חֲזֵי, הָכִי אָמַר רִבִּי אֶלְעָזָר מִשְּׁמֵיהּ דַּאֲבוֹי, אָמְרוּ יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, מִיּוֹמָא דְּנָפִלְנָא בְּגָלוּתָא, קוּדְשָׁא בְּרִיךְ הוּא שָׁבִיק לָן בְּגָלוּתָא, וְאַנְשֵׁי לָן. הֲדָא הוּא דִּכְתִּיב, (ישעיהו מ״ט:י״ד) וַתֹּאמֶר צִיּוֹן עֲזָבַנִי יְיָ' וַיְיָ' שְׁכֵחָנִי. אָמְרָה שְׁכִינְתָּא, הֲתִשְׁכַּח אִשָּׁה עוּלָהּ, וְכִי יִשְׂרָאֵל דְּאִקְרוּן בְּנִין, כְּמָה דְּאַתְּ אָמֵר, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם. מֵרַחֵם בֶּן בִּטְנָהּ, כְּמָה דְאַתְּ אָמֵר, (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. גַּם אֵלֶּה תִשְׁכַּחְנָה, דִּכְתִּיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. וְאָנֹכִי לֹא אֶשְׁכָּחֵךְ, מִכָּאן, דְקוּדְשָׁא בְּרִיךְ הוּא לָא שָׁבִיק לוֹן לְיִשְׂרָאֵל לְעָלְמִין."],[[0,"תניא ר' יהודה וכו':","למדנו רי\"א, בכמה מקומות הסתכלתי, שהקב\"ה לא הסיר אהבתו מישראל. שבכל מקום שהם היו, היה הקב\"ה ביניהם. שכתוב, לא מאסתים ולא געלתים לכלותם להפר בריתי אתם. \u0003אתם\u0004 הוא בדיוק, דהיינו שהקב\"ה הוא ביניהם, עמהם. ולא נסתלק מהם לעולם."],[1,"ר' יצחק הוה וכו':","ר\"י היה הולך בדרך. ופגע בו ר' חייא. א\"ל אני רואה בפניך שבמשכן השכינה משכנך. מה כתוב, וארד להצילו מיד מצרים. כתוב, וארד, ארד היה צריך לומר, הרי ה \u0003ו'\u0004 מיותרת. ומשיב. \u0003וארד\u0004 פירושו, מתחילה. כי ה \u0003ו'\u0004 מהפכת העתיד לעבר. מתי. הוא כשירד יעקב למצרים, ירד עמו הקב\"ה, ולמה ירד כדי \u0003להצילו מיד מצרים\u0004. שאם לא היה ביניהם, לא היו יכלו לסבול הגלות. כש\"א, עמו אנכי בצרה אחלצהו ואכבדהו."],[2,"א\"ל ודאי בכל וכו':","א\"ל, ודאי בכל מקום שישראל שורים, הקב\"ה ביניהם. ובכל מקום שחכמי הדור הולכים, הקב\"ה הולך עמהם. שכתוב, כי מלאכיו יצוה לך וגו'. מאין לנו. שכתוב, ויעקב הלך לדרכו וגו' ויאמר יעקב כאשר ראם מחנה אלקים זה. עתה נתחבר יחד ונלך בדרך שאני יודע שאנו הולכים למקום אחד, לקבל פני השכינה, דהיינו לרשב\"י. א\"ל ודאי הוא כך. א\"ר יצחק למדנו שליחי מצוה אינם נזוקים לא בהליכתם ולא בחזרתם, ואנו הולכים להתראות לפני הקב\"ה, ואין אנו יראים."],[3,"עד דהוו אזלי וכו':","בעוד שהיו הולכים, אמר ר' חייא, כתוב, אלה תולדות השמים והארץ. השמים הוא לכלול את הקב\"ה, דהיינו ז\"א שנקרא שמים. והארץ היא לכלול את הקב\"ה, שהוא המלכות שנקראת ארץ, וכל מה שלמטה מן אצילות דהיינו ג' עולמות בי\"ע, הם נקראים תולדות השמים והארץ שמהם נולדו. דהיינו מז\"א ומלכות."],[4,"א\"ל אי הכי וכו':","א\"ל, אם כן, מהו בהבראם, ולמדנו ב \u0003ה'\u0004 בראם, דהיינו במלכות. ואתה אומר שהם תולדות השמים וארץ דהיינו גם מז\"א. א\"ל, הכל דבר אחד הוא. כי כשהשמים, שהוא ז\"א, נתחברו עם המלכות, אז \u0003ה'\u0004 זו, שהיא המלכות, הוציאה תולדות, ואלו נקראים תולדות השמים והארץ. א\"ל, א\"כ, במה העמדנו ש \u0003בה'בראם\u0004, היינו באברהם, שאותיותיהם שוות. ומה ענין אברהם לכאן. א\"ל, הכל דבר אחד הוא, באברהם, הוא חסד דז\"א שנקרא אברהם, והיינו הוא השמים, שהוא ז\"א. כי משם, מן ספירת החסד, מתחיל ז\"א להתפשט. כלומר שספירה ראשונה של ז\"א הוא חסד, ונמצא שהשם אברהם רומז ג\"כ על ז\"א כמו השם שמים. ומה שאמרו ב \u0003ה'\u0004 בראם, היינו והארץ, שהיא מלכות. ונמצא ששמים וארץ נרמזים באותיות בהבראם. והכל דבר אחד הוא."],[5,"א\"ל ודאי הכי וכו':","א\"ל, ודאי כך הוא, והנה למדתי, שכתוב, אלה תולדות השמים והארץ, ולמדנו עולם הזה נברא ב \u0003ה'\u0004 שהיא המלכות, שכתוב, בהבראם, דהיינו ב \u0003ה'\u0004 בראם. כנ\"ל. ועולם הבא, שהיא בינה נברא ב \u0003י'\u0004 שהיא חכמה. שכתוב \u0003ונהר יוצא מעדן\u0004 להשקות את הגן. שנהר הוא בינה, יוצא מעדן הוא חכמה, להשקות את הגן, היינו ז\"א ואומר, שנהר יוצא מעדן, הוא כולל את השמים, שהוא ז\"א, שנקרא ג\"כ נהר. \u0003את הגן\u0004 כולל ואת הארץ שהיא מלכות. דהיינו שבכלל הפירוש הנ\"ל הוא ג\"כ שז\"א יוצא מחכמה ובינה, שנקראים שניהם עדן, ומשקה את המלכות שה\"ס הגן."],[6,"והא אוקימנא דכתיב וכו':","והרי העמדנו, שכתוב, \u0003מעין גנים\u0004, זה הוא השמים, שהוא ז\"א, הנקרא נהר כנ\"ל. שהוא באר מים חיים. שכתוב, ויכרו שם עבדי יצחק באר. שכתוב, ויעתק משם ויחפור באר אחרת וגו'. \u0003ונוזלים מן לבנון\u0004, דהיינו מן החכמה שנקראת לבנון, שהנוזלים מתעטרים למעלה, בחכמה, ועולים בראש המלך, דהיינו בג\"ר דז\"א, שכתוב, כי גדול מעל השמים חסדך. להיותם נמשכים מן החכמה, שהוא ממעל ז\"א, שנק' שמים."],[7,"מן לבנון מתמן וכו':","ומפרש דבריו. \u0003מן לבנון\u0004, שהוא חכמה, משם יוצאים הנוזלים דהיינו השפע אל הבינה, ונוזל ונמשך לכל הזויות, דהיינו לד' רוחות, חו\"ג תו\"מ דז\"א. עד שאלו המבועים נוזלים ויורדים להתקבץ אל המקום שנקרא ים הגדול, דהיינו המלכות. שכתוב, כל הנחלים הולכים אל הים. שפירושו, שנחלי חו\"ג תו\"מ דז\"א הולכים אל המלכות שנקראת ים. וכתוב, הביטו אל צור חוצבתם וגו' שהוא אברהם, דהיינו חסד דז\"א, ואח\"כ אחר ונוזלים מן לבנון, כתוב גן נעול אחותי כלה וגו'. שהיא המלכות המקבלת הנוזלים מן ז\"א. ומכאן, מן המלכות, יצאו תולדות לכל העולמות. שכתוב בהבראם, ב \u0003ה'\u0004 בראם, שהיא מלכות, והיינו ממש באברהם שהוא חסד דז\"א שה\"ס הנוזלים שנמשכים מחכמה עלאה שנקראת לבנון אל ז\"א, ומז\"א אל המלכות שמהם כל התולדות שבבי\"ע. א\"ר יצחק ואפילו ביעקב ממש. שהוא תפארת דז\"א. כי תפארת כולל בתוכו החסד והגבורה. והכל הוא דבר אחד."],[8,"א\"ר יצחק כד וכו':","אר\"י, כשאנו יושבים לפני ר\"ש נאמר הכל לפניו בגלוי ואין אנו צריכים לכל זה. דהיינו שאינם צריכים שם לכסות הדברים בשמות וכנוים. א\"ל, אין ר\"ש כשאר בני אדם, שכולם לפניו כמו שאר הנביאים כלפי משה. בעוד שהיו הולכים אמר ר' חייא, כתוב, התשכח אשה עולה מרחם בן בטנה וגו'. מקרא זה העמידו. וכאן, בפנימיות, מה פירושו. אמר לו, אם באגודת החברים לא נתמכנו בתמיכה, בביאור המקרא הזה, אנו מה נאמר."],[9,"א\"ל דהא קלא וכו':","א\"ל, הנה שמעתי קול אחד שרמז לי ביאור המקרא, ביום אחד כשהייתי הולך בדרך. ולא ידעתי, מי אמר, ואיני יודע הדבר. ובוא וראה, ז' ימים היו שהייתי חולה על זה, ולא טעמתי משהו. ועתה אני הולך אל המאור הקדוש, שיאמר לי, אולי אזכור. אמר לו ר' יצחק, אולי היה זה באותו יום שהיה הולך ר' אלעזר אל חמיו, ואותו יום הלכתי עמו והנה נזכרתי בדבר."],[10,"ת\"ח הכי אמר וכו':","בוא וראה, כך אמר ר' אלעזר משמו של אביו. אמרו ישראל לפני הקב\"ה, מיום שנפלנו בגלות, הקב\"ה עזב אותנו בגלות, ושכח אותנו. ז\"ש, ותאמר ציון עזבני ה' וה' שכחני. אמרה השכינה, \u0003התשכח אשה עולה\u0004, וכי ישראל הנקראים בנים, כש\"א בנים אתם לה' אלקיכם, וכי אפשר לשכוח אותם. \u0003מרחם בן בטנה\u0004, הוא כש\"א, ואנכי נטעתיך שורק כלה זרע אמת. \u0003גם אל\"ה תשכחנה\u0004, שכתוב, \u0003אלה\u0004 תולדות השמים והארץ. ואנכי לא אשכחך. מכאן שהקב\"ה אינו עוזב את ישראל לעולם."]],[[0,"","לָמַדְנוּ, רַבִּי יְהוּדָה אוֹמֵר, בְּכַמָּה מְקוֹמוֹת הִסְתַּכַּלְתִּי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הֵסִיר אַהֲבָתוֹ מֵהֶם מִיִּשְׂרָאֵל, שֶׁבְּכָל מָקוֹם שֶׁהֵם הָיוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּינֵיהֶם, שֶׁכָּתוּב [ויקרא כו] לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלֹּתָם לְהָפֵר בְּרִיתִי אִתָּם. אִתָּם דַּוְקָא, בֵּינֵיהֶם עִמָּהֶם, לֹא סָר מֵהֶם לְעוֹלָמִים."],[1,"","רַבִּי יִצְחָק הָיָה מְהַלֵּךְ בַּדֶּרֶךְ וּפָגַע בּוֹ רַבִּי חִיָּיא. אָמַר לוֹ, רוֹאֶה אֲנִי [אותם] בְּפָנֶיךְ שֶׁהֲרֵי בַּמָּדוֹר שֶׁל הַשְּׁכִינָה מְקוֹמְךְ. מַהוּ שֶׁכָּתוּב [שמות ג] וָאֵרֵד לְהַצִּילוֹ מִיַּד מִצְרַיִם? וָאֵרֵד?! אֵרֵד הָיָה צָרִיךְ לוֹ! וָאֵרֵד – בָּרִאשׁוֹנָה. מָתַי? כַּאֲשֶׁר יָרַד יַעֲקֹב לְמִצְרַיִם. וְלָמָּה? לְהַצִּילוֹ מִיַּד מִצְרַיִם. שֶׁאִם לֹא הָיָה בֵינֵיהֶם, לֹא יְכוֹלִים לִסְבֹּל הַגָּלוּת, כְּמוֹ שֶׁנֶּאֱמַר [תהלים צא] עִמּוֹ אָנֹכִי בְצָרָה אֲחַלְּצֵהוּ וַאֲכַבְּדֵהוּ."],[2,"","אָמַר לוֹ, וַדַּאי בְּכָל מָקוֹם שֶׁיִּשְׂרָאֵל נִמְצָאִים, הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּינֵיהֶם. וְכָל מָקוֹם שֶׁחַכְמֵי הַדּוֹר הוֹלְכִים, הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ עִמָּהֶם, שֶׁכָּתוּב [שם] כִּי מַלְאָכָיו יְצַוֶּה לָּךְ וְגוֹ'. מִנַּיִן לָנוּ? שֶׁכָּתוּב [בראשית לב] וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וְגוֹ', וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. עַתָּה נִשְׁתַּתֵּף כְּאֶחָד וְנֵלֵךְ בַּדֶּרֶךְ, שֶׁהֲרֵי יָדַעְתִּי שֶׁלְּמָקוֹם אֶחָד אָנוּ הוֹלְכִים, לְקַבֵּל פְּנֵי שְׁכִינָה. אָמַר לוֹ, בְּוַדַּאי. אָמַר רַבִּי יִצְחָק, לָמַדְנוּ, שְׁלוּחֵי מִצְוָה אֵינָן נִזּוֹקִין, לֹא בַהֲלִיכָתָן וְלֹא בַחֲזָרָתָן. וַאֲנַחְנוּ לְהֵרָאוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אָנוּ הוֹלְכִים, וְלֹא יְרֵאִים."],[3,"","עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי חִיָּיא, כָּתוּב [שם ב] אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. הַשָּׁמַיִם – לִכְלֹל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהָאָרֶץ – לִכְלֹל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל מַה שֶּׁלְּמַטָּה, אֵלּוּ נִקְרָאִים תּוֹלְדוֹת הַשָּׁמַיִם, מֵהֶם."],[4,"","אָמַר לוֹ, אִם כֵּן, מַהוּ בְּהִבָּרְאָם, וְנֶאֱמַר בְּה' בְּרָאָם? אָמַר לוֹ, הַכֹּל דָּבָר אֶחָד. כַּאֲשֶׁר הַשָּׁמַיִם הִתְחַבְּרוּ, ה' הַזּוֹ הוֹצִיאָה תוֹלָדוֹת, וְהֵם נִקְרְאוּ תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. אָמַר לוֹ, אִם כֵּן, בַּמֶּה בֵּאַרְנוּ בְּה' בְּרָאָם – בְּאַבְרָהָם? אָמַר לוֹ, הַכֹּל דָּבָר אֶחָד הוּא. בְּאַבְרָהָם – אֵלּוּ הַשָּׁמַיִם, שֶׁמִּשָּׁם מַתְחִילִים לְהִתְפַּשֵּׁט. בְּה' בְּרָאָם, וְזֶהוּ וְהָאָרֶץ, וְהַכֹּל דָּבָר אֶחָד."],[5,"","אָמַר לוֹ, וַדַּאי כָּךְ הוּא, וַהֲרֵי לָמַדְנוּ, שֶׁכָּתוּב אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. וְלָמַדְנוּ, הָעוֹלָם הַזֶּה נִבְרָא בְה', שֶׁכָּתוּב בְּהִבָּרְאָם. וְהָעוֹלָם הַבָּא נִבְרָא בְי', שֶׁכָּתוּב [בראשית ב] וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן – לִכְלֹל הַשָּׁמַיִם. אֶת הַגָּן – לִכְלֹל אֶת הָאָרֶץ."],[6,"","וַהֲרֵי בֵּאַרְנוּ, שֶׁכָּתוּב [שיר השירים ד] מַעְיַן גַּנִּים, זֶהוּ הַשָּׁמַיִם, בְּאֵר מַיִם חַיִּים, שֶׁכָּתוּב [בראשית כו] וַיִּכְרוּ שָׁם עַבְדֵי יִצְחָק בְּאֵר, שֶׁכָּתוּב [שם] וַיַּעְתֵּק מִשָּׁם וַיַּחְפֹּר בְּאֵר אַחֶרֶת וְגוֹ'. וְנֹזְלִים מִן לְבָנוֹן, שֶׁאֵלּוּ מִתְקַשְּׁטִים לְמַעְלָה וְעוֹלִים בְּרֹאשׁוֹ שֶׁל הַמֶּלֶךְ, שֶׁכָּתוּב [תהלים קח] כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךְ."],[7,"","מִן לְבָנוֹן – מִשָּׁם יוֹצְאִים לְבִינָה. וְנִמְשָׁךְ וּמִתְפַּשֵּׁט לְכָל הַקְּצָווֹת, עַד שֶׁנִּמְשָׁכִים אֵלּוּ הַמְּקוֹרוֹת וְיוֹרְדִים לְהִתְכַּנֵּס לְמָקוֹם שֶׁנִּקְרָא הַיָּם הַגָּדוֹל, שֶׁכָּתוּב [קהלת א] כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'. וְכָתוּב [ישעיה נא] הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם וְגוֹ'. וְאַחַר כָּךְ כָּתוּב, [שיר השירים ד] גַּן נָעוּל אֲחֹתִי כַלָּה וְגוֹ'. וּמִכָּאן יָצְאוּ תוֹלָדוֹת לְכֻלָּם, שֶׁכָּתוּב בְּהִבָּרְאָם, בְּה' בְּרָאָם מַמָּשׁ, בְּאַבְרָהָם. אָמַר רַבִּי יִצְחָק, וַאֲפִלּוּ בְּיַעֲקֹב מַמָּשׁ. וְהַכֹּל דָּבָר אֶחָד."],[8,"","אָמַר רַבִּי יִצְחָק, כַּאֲשֶׁר אָנוּ יוֹשְׁבִים לִפְנֵי רַבִּי שִׁמְעוֹן, הַכֹּל נֶאֱמַר לְפָנָיו בְּגִלּוּי וְלֹא הִצְטָרַכְנוּ לְכָל זֶה. אָמַר לוֹ, אֵין רַבִּי שִׁמְעוֹן כִּשְׁאָר בְּנֵי אָדָם, שֶׁכֻּלָּם לְפָנָיו כְּמוֹ שְׁאָר הַנְּבִיאִים כְּלַפֵּי מֹשֶׁה. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי חִיָּיא, כָּתוּב [ישעיה מט] הֲתִשְׁכַּח אִשָּׁה עוּלָהּ מֵרַחֵם בֶּן בִּטְנָהּ וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ, וְכָאן מַה הוּא עוֹסֵק? אָמַר רַבִּי יִצְחָק, אִם בַּקֶּשֶׁר שֶׁל הַחֲבֵרִים, סְמִיכָה לֹא נִסְמַכְתִּי, אָנוּ מַה נֹּאמַר?"],[9,"","אָמַר לוֹ, שֶׁהֲרֵי קוֹל שֶׁל רֶמֶז אֶחָד שָׁמַעְתִּי יוֹם אֶחָד כַּאֲשֶׁר הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ, וְלֹא יָדַעְתִּי מִי אָמַר, וְלֹא יָדַעְתִּי דָבָר. וּבֹא רְאֵה, שִׁבְעָה יָמִים הָיוּ שֶׁנֶּחֱלַשְׁתִּי עַל זֶה וְלֹא טָעַמְתִּי דָבָר, וְעַתָּה הוֹלֵךְ אֲנִי אֵצֶל הַמְּנוֹרָה הַקְּדוֹשָׁה שֶׁיֹּאמַר לִי, שֶׁמָּא אֶזְכֹּר. אָמַר לוֹ, שֶׁמָּא אוֹתוֹ הַיּוֹם שֶׁהָיָה הוֹלֵךְ רַבִּי אֶלְעָזָר אֵצֶל חָמִיו, וְאוֹתוֹ הַיּוֹם הָלַכְתִּי עִמּוֹ, וְהִנֵּה נִזְכַּרְתִּי בַדָּבָר."],[10,"","בֹּא רְאֵה, כָּךְ אָמַר רַבִּי אֶלְעָזָר מִשְּׁמוֹ שֶׁל אָבִיו, אָמְרוּ יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: מִיּוֹם שֶׁנָּפַלְנוּ בַגָּלוּת, הַקָּדוֹשׁ בָּרוּךְ הוּא עָזַב אוֹתָנוּ בַגָּלוּת וְשָׁכַח אוֹתָנוּ. זֶהוּ שֶׁכָּתוּב [ישעיה מט] וַתֹּאמֶר צִיּוֹן עֲזָבַנִי ה' וַה' שְׁכֵחָנִי. אָמְרָה הַשְּׁכִינָה: הֲתִשְׁכַּח אִשָּׁה עוּלָהּ?! וְכִי יִשְׂרָאֵל שֶׁנִּקְרָאִים בָּנִים, כְּמוֹ שֶׁנֶּאֱמַר [דברים יד] בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם, מֵרַחֵם בֶּן בִּטְנָהּ, כְּמוֹ שֶׁנֶּאֱמַר [ירמיה ב] וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת, גַּם אֵלֶּה תִּשְׁכַּחְנָה, שֶׁכָּתוּב [בראשית ב] אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ?! וְאָנֹכִי לֹא אֶשְׁכָּחֵךְ. מִכָּאן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹזֵב אוֹתָם אֶת יִשְׂרָאֵל לְעוֹלָמִים."]]],[["תּוּ אָמַר, הֲתִשְׁכַּח אִשָּׁה עוּלָהּ מֵרַחֵם בֶּן בִּטְנָהּ. דָּא הוּא רָזָא עִלָּאָה, דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא, הָא מִלִּין אִלֵּין בִּשְׁמֵיהּ אֲחִידָן, כְּמָה דְקוּדְשָׁא בְּרִיךְ הוּא לָא אַנְשֵׁי שְׁמֵיהּ, דְּהָא הוּא כֹּלָּא. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא לָא אַנְשֵׁי לוֹן לְיִשְׂרָאֵל דְּאִינּוּן אֲחִידָן בִּשְׁמֵיהּ מַמָּשׁ. אִתְרְגִּישׁ רִבִּי חִיָּיא, אָמַר וַדַּאי דָּא הִיא מִלָּה. בְּרִיךְ יְהֵא קוּדְשָׁא בְּרִיךְ הוּא דְּאַעְרַעְנָא לָךְ, וְיָדַעְנָא מִלָּה. וְיָדַעְנָא מַאן הַהוּא דְּשָׁמַעְנָא מִנֵּיהּ.","וְתָּא חֲזֵי, דְּהַהוּא יוֹמָא דְּרָהִיטְנָא ד' מִילֵּי, וְלָא אַשְׁכַּחְנָא מַאן הֲוָה. אָמַר לֵיהּ, בְּגִין דְּעָאלְנָא בְּחַד מְעַרְתָּא דְּרִבִּי אֶלְעָזָר נָּפִישׁ שַׁעֲתָא חֲדָא. קָרֵי עָלֵיהּ רִבִּי חִיָּיא הָנֵי קְרָאֵי, (ישעיהו נ״ח:ח׳) אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךָ וְגוֹ'. אָז תִּקְרָא וַיְיָ' יַעֲנֶה וְגוֹ' אָז תִּתְעַנָּג עַל יְיָ' וְגוֹ'.","(דברים ל״ב:ז׳) זְכוֹר יְמוֹת עוֹלָם בִּינוּ שְׁנוֹת דּוֹר וָדוֹר וְגוֹ'. זְכוֹר יְמוֹת עוֹלָם, רִבִּי אַבָּא אָמַר, מַאן יְמוֹת עוֹלָם. אִינּוּן שִׁיתָּא יוֹמִין, דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא בְּהוּ. דִּכְתִּיב, (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ' וְגוֹ'. שֵׁשֶׁת יָמִים, וְלָא בְּשֵׁשֶׁת יָמִים, וְהָא אוֹקִימְנָא. בִּינוּ שְׁנוֹת דּוֹר וָדוֹר. כְּלוֹמַר, אִינּוּן יְמוֹת עוֹלָם, יָדְעוּ וְיִשְׁתְּמוֹדְעוּ כָּל אִינּוּן שְׁנִין וְיוֹמִין, וְכָל דָּרָא וְדָרָא, עַד דָּרָא דָּא דְּאַתּוּן קַיְימִין.","שְׁאַל אָבִיךָ וְיַגֵּדְךָ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, הֲלֹא הוּא אָבִיךָ קָּנֶךָ. וְיַגֵּדְךָ, וְהוּא יְגַלֶּה עוּמְקָא דְּחָכְמְתָא. וּמַאי הִיא. אֶלָּא כַּד אִינּוּן שִׁיתָּא יוֹמִין שַׁכְלִילוּ עָלְמָא, לָא שַׁכְלִילוּ לֵיהּ, אֶלָּא בְּגִינָךְ, דְּתֵיתֵי אַנְתְּ וּתְקַיֵּים אוֹרַיְיתָא. דְּתָנֵינָן, כָּל מַה דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא, עַל תְּנַאי עֲבַד, דְּכַד יֵיתוּן יִשְׂרָאֵל, אִי יְקַבְּלוּן אוֹרַיְיתָא יָאוּת, וְאִי לָא דְּיְהָדַר לֵיהּ לְתֹהוּ וָבֹהוּ. וּבְגִין כָּךְ, אִינּוּן יְמוֹת עוֹלָם יָדְעוּ וְאִשְׁתְּמוֹדְעָן כֹּלָּא.","וְהָא תָּנֵינָן, הַנְהוּ עַנְפֵּי דְּאִילָנָא, הֵיךְ מִתְאַחֲדָן בְּגוֹ אִילָנָא, וְהָא אוֹקִימְנָא, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא בִּרֵר לוֹן, לִמְמָנָן תְּרִיסִין, עַל שְׁאַר עַמִּין, וְאַתּוּן מַה כְּתִיב. כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, דְּלָא יָהַב לְהוּ לְרַבְרְבָא, וְלָא לְמַלְאָכָא, וְלָא לִמְמָנָא אַחֲרָא, וְהַאי עַמָּא דְקוּדְשָׁא בְּרִיךְ הוּא נָסַב לְחוּלָקֵיהּ.","בְּאָן אֲתָר אַשְׁכַּח לֵיהּ. יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵיל יְשִׁימוֹן וְגוֹ'. דִּכְתִּיב, (יהושע כ״ד:ג׳) תֶּרַח אֲבִי אַבְרָהָם וְגוֹ'. וָאֶקַּח אֶת אֲבִיכֶם אֶת אַבְרָהָם וְגוֹ'. וּמֵהָכָא דָּבַּר לְהוּ לְיִשְׂרָאֵל בְּכָל דָּרָא וְדָרָא, וְלָא אִתְפְּרַשׁ מִנַּיְיהוּ, וְדָבַּר לְהוּ בְּרַחֲמֵי, הֲדָא הוּא דִכְתִיב כְּנֶשֶׁר יָעִיר קִנּוֹ וְגוֹ'.","(דברים ל״ב:י״א) כְּנֶשֶׁר יָעִיר קִנּוֹ. אָמַר רִבִּי יוֹסֵי, לָא אַשְׁכַּחְנָא מַאן דְּחָיִיס עַל בְּנוֹי, כְּהַאי נִשְׁרָא. וְעַל דָּא תָּנֵינָן, כְּתִיב, (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָּמִין וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. נֶשֶׁר בְּאָן דּוּכְתֵּיהּ. בַּאֲתָר דְּיַעֲקֹב קָאִים. הֲדָא הוּא דִכְתִיב, (משלי ל׳:י״ט) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. בְּהַהוּא אֲתָר מַמָּשׁ. מַאי טַעְמָא. בְּגִין דְּאִיהוּ רַחֲמֵי עַל בְּנוֹי, וְדִינָא לְגַבֵּי אַחֲרָנִין. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא, דָּבַּר לִבְנוֹי כְּנֶשֶׁר דָּא.","מַה כְּתִיב יְיָ' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר. הוּא בִּלְחוֹדוֹי, דִּכְתִּיב, (שמות י״ג:כ״א) וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם וְגוֹ'. וְאֵין עִמּוֹ אֵל נֵכָר, דְּלָא דָּבַּר לְהוּ לְיִשְׂרָאֵל לָא מַלְאָכָא, וְלָא מְמָנָא אַחֲרָא, דְּאִינּוּן אִקְרוּן אֵל נֵכָר. וְדָא הוּא דְּאָמַר מֹשֶׁה, (שמות ל״ג:ט״ו) אִם אֵין פָּנֶיךָ הוֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה. הֲדָא הוּא דִּכְתִּיב, יְיָ' בָּדָד יַנְחֶנּוּ. הוּא בִּלְחוֹדוֹי, וְאֵין עִמּוֹ אֵל נֵכָר.","זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא דָּבַּר עִמְּהוֹן, (בישראל) הָכִי עָלַיְיהוּ כְּתִיב, (תהילים קל״ה:ד׳-ה׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגוּלָתוֹ, וּכְתִיב, (שמואל א י״ב:כ״ב) כִּי לֹא יִטּוֹשׁ יְיָ' אֶת עַמּוֹ וְגוֹ'. מַאי טַעְמָא לֹא יִטּוֹשׁ ה' אֶת עַמּוֹ. בַּעֲבוּר שְׁמוֹ הַגָּדוֹל, בְּגִין דְּהַאי בְּהַאי אִתְדְּבַק. וְעַל דָּא לָא יִשְׁבּוֹק לוֹן קוּדְשָׁא בְּרִיךְ הוּא, דִּבְכָל אֲתָר דְּאִינּוּן שַׁרְיָין, קוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן כְּמָה דְּאוֹקִימְנָא.","(דברים ל״ב:כ״ט) לוּ חָכְמוּ יַשְׂכִּילוּ זֹאת. אָמַר רִבִּי יוֹסֵי, כָּל הָנֵי קְרָאֵי דְּהָכָא, אוֹכָחֵי אִינּוּן, דְּאוֹכַח לְהוּ מֹשֶׁה לְיִשְׂרָאֵל, בַּר הַהוּא שְׁמָא קַדִּישָׁא, דְּגַלֵּי בְּשֵׁירוּתָא דְּמִלוֹי. אָמַר רִבִּי אַבָּא, וַאֲפִילּוּ מַה דְּאוֹכַח לְיִשְׂרָאֵל, בִּכְלָלָא דִּשְׁמָא קַדִּישָׁא הוּא, דְּלֵית מִלָּה בְּאוֹרַיְיתָא דְּנָפִיק מִכְּלָלָא דִּשְׁמָא קַדִּישָׁא. דְּאוֹרַיְיתָא כֹּלָּא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִינּוּן."],[[0,"תו אמר התשכח וכו':","עוד אמר התשכח אשה עולה מרחם בן בטנה. זה הוא סוד עליון, שאמר הקב\"ה, הנה דברים אלו אחוזים בשמי, כמו שהקב\"ה אינו שוכח שמו, כי הוא הכל, כך הקב\"ה אינו שוכח את ישראל, כי הם אחוזים בשמו ממש. נתרגש ר' חייא, אמר, ודאי זה הוא הדבר ששמעתי ושכחתי. ברוך יהיה הקב\"ה שפגשתי אותך וידעתי הדבר, גם ידעתי מי הוא ששמעתי ממנו."],[1,"ות\"ח דההוא יומא וכו':","ובוא וראה, באותו יום ששמעתי הקול שרמז לי הביאור הזה, רצתי ארבעה מילין ולא מצאתי, מי הוא שאמר זה. א\"ל ר' יצחק, שהוא משום שנכנסנו במערה אחת, ור' אלעזר נח שם שעה אחת. קרא עליו ר' חייא אלו המקראות דהיינו על הזמן שזכה להיות עם ר\"א במערה, אז יבקע כשחר אורך וגו'. אז תקרא וה' יענה וגו'. אז תתענג על ה' וגו'."],[2,"זכור ימות עולם בינו וגו':","זכור ימות עולם, ר' אבא אמר מי הם ימות עולם. הם ששת הימים שעשה הקב\"ה בהם את העולם. שכתוב כי ששת ימים עשה ה' וגו'. כתוב, ששת ימים ולא בששת ימים, משום שהם שש ספירות חג\"ת נה\"י דז\"א שהן עשו את העולם, וכבר העמדנו. בינו \u0003שנות דור ודור\u0004 כלומר, אלו ימות עולם, חג\"ת נה\"י, ידעו ויכירו כל אלו השנים והימים, וכל דור ודור, עד דור הזה שאתם נמצאים בו."],[3,"שאל אביך ויגדך:","זהו הקב\"ה. ז\"ש, הלא הוא אביך קנך. \u0003ויגדך\u0004, היינו שהוא יגלה לך עומק החכמה. ומה היא. אלא כשאלו ששת ימים, חג\"ת נה\"י, שכללו העולם לא שכללו אותו, אלא בשבילך, שאתה תבא ותעסוק בתורה. שלמדנו כל מה שעשה הקב\"ה עשה על תנאי, כשיבואו ישראל, אם יקבלו את התורה, טוב. ואם לא, יחזור העולם לתהו ובהו. ומשום זה אלו ימות עולם ידעו ויכירו הכל."],[4,"והא תנינן הנהו וכו':","והרי למדנו, אלו ענפי האילן, דהיינו ע' שרים של האומות, איך הם מתאחזים בתוך האילן, שהוא ז\"א. והנה העמדנו, שאז הקב\"ה פזר אותם את ע' השרים לממונים ומגינים על שאר האומות, ואתם, ישראל, מה כתוב \u0003כי חלק ה' עמו יעקב חבל נחלתו\u0004, שלא נתן אותם לשר, ולא למלאך, ולא לממונה אחר, כי עם הזה של הקב\"ה, לקח לחלקו."],[5,"באן אתר אשכח וכו':","באיזה מקום מצא אותם. כתוב, ימצאהו בארץ מדבר ובתהו יליל ישימון וגו'. שכתוב, תרח אבי אברהם וגו'. ואקח את אביכם את אברהם וגו'. ומכאן הנהיג את ישראל בכל דור ודור, ולא נפרד מהם. והנהיגם ברחמים. ז\"ש כנשר יעיר קנו וגו'."],[6,"כנשר יעיר קנו:","א\"ר יוסי, לא מצאנו מי שירחם על בניו כנשר הזה. וע\"כ למדנו, כתוב, ופני אריה אל הימין ופני שור מהשמאל. נשר איפה הוא מקומו. היינו במקום שיעקב עומד. דהיינו בקו האמצעי הכולל ימין ושמאל. ז\"ש, דרך הנשר בשמים. במקום ההוא ממש, דהיינו בז\"א הנקרא שמים, שהוא קו האמצעי. מהו הטעם. הוא משום שהוא רחמן על בניו, ודין כלפי אחרים, כך הקב\"ה, הכולל ימין ושמאל, שהוא חסד ודין, מנהיג את בניו, כנשר הזה."],[7,"מה כתיב ה' וגו':","מה כתוב, ה' בדד ינחנו ואין עמו אל נכר, הוא בלבדו, שכתוב וה' הולך לפניהם וגו'. ואין עמו אל נכר דהיינו שאין מנהיג את ישראל, לא מלאך ולא ממונה אחר, שהם נקראים אל נכר. וזהו שאמר משה, אם אין פניך הולכים אל תעלנו מזה. ז\"ש, ה' בדד ינחנו. הוא בלבדו, ואין עמו אל נכר."],[8,"זכאה חולקהון דישראל וכו':","אשרי חלקם של ישראל, שהקב\"ה מנהיג אותם, שכך כתוב עליהם כי יעקב בחר לו יה ישראל לסגולתו, וכתוב, כי לא יטוש ה' את עמו וגו'. מהו הטעם, לא יטוש ה' את עמו, היינו בעבור שמו הגדול, משום שזה בזה נתדבקו כי ישראל נתדבקו בשמו הגדול, וע\"כ לא יעזוב אותם הקב\"ה, שבכל מקום שהם שורים נמצא הקב\"ה עמהם. כמו שהעמדנו."],[9,"לו חכמו ישכילו זאת:","א\"ר יוסי כל אלו המקראות שבכאן הם תוכחות שהוכיח משה את ישראל, חוץ משם הקדוש ההוא שגילה בתחלת דבריו, דהיינו, כי שם ה' אקרא וגו' שה\"ס חג\"ת נהי\"מ (כנ\"ל אות ר\"ו) א\"ר אבא, ואפילו המקראות שהוכיח בהם את ישראל הם בכלל השם הקדוש כי אין דבר בתורה שיוצא מכלל השם הקדוש. כי התורה כולה שמו של הקב\"ה הם."]],[[0,"","עוֹד אָמַר, הֲתִשְׁכַּח אִשָּׁה עוּלָהּ מֵרַחֵם בֶּן בִּטְנָהּ. זֶהוּ סוֹד עֶלְיוֹן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא. הִנֵּה דְבָרִים אֵלּוּ בִשְׁמוֹ אֲחוּזִים. כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שׁוֹכֵחַ שְׁמוֹ שֶׁהֲרֵי הוּא הַכֹּל – כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שׁוֹכֵחַ אוֹתָם אֶת יִשְׂרָאֵל, שֶׁהֵם אֲחוּזִים בִּשְׁמוֹ מַמָּשׁ. הִתְרַגֵּשׁ רַבִּי חִיָּיא, אָמַר, וַדַּאי זֶהוּ דְּבַר חִדּוּשׁ. בָּרוּךְ יִהְיֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּפְגַּשְׁתִּי בְךְ וְיָדַעְתִּי דָבָר, וְיָדַעְתִּי מִי אוֹתוֹ שֶׁשָּׁמַעְתִּי מִמֶּנּוּ."],[1,"","וּבֹא רְאֵה, שֶׁאוֹתוֹ יוֹם שֶׁרַצְתִּי אַרְבָּעָה מִילִין, וְלֹא מָצָאתִי מִי הָיָה. אָמַר לוֹ, מִשּׁוּם שֶׁנִּכְנַסְתִּי בִמְעָרָה אַחַת שֶׁרַבִּי אֶלְעָזָר נָח שָׁעָה אַחַת. קָרָא עָלָיו רַבִּי חִיָּיא אֵלּוּ הַפְּסוּקִים, [ישעיה נח] אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וְגוֹ'. אָז תִּקְרָא וַה' יַעֲנֶה וְגוֹ', אָז תִּתְעַנַּג עַל ה' וְגוֹ'."],[2,"","[דברים לג] זְכֹר יְמוֹת עוֹלָם בִּינוּ שְׁנוֹת דֹּר וָדוֹר וְגוֹ'. זְכֹר יְמוֹת עוֹלָם. רַבִּי אַבָּא אָמַר, מִי אֵלּוּ יְמוֹת עוֹלָם? אֵלּוּ שִׁשָּׁה יָמִים שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם בָּהֶם, שֶׁכָּתוּב [שמות לא] כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' וְגוֹ'. שֵׁשֶׁת יָמִים, וְלֹא בְשֵׁשֶׁת יָמִים, וַהֲרֵי בֵּאַרְנוּ. בִּינוּ שְׁנוֹת דֹּר וָדר. כְּלוֹמַר, אֵלּוּ יְמוֹת עוֹלָם, יֵדְעוּ וְיִתְוַדְּעוּ כָּל אֵלּוּ הַשָּׁנִים וְהַיָּמִים וְכָל דּוֹר וָדוֹר, עַד דּוֹר זֶה שֶׁאַתֶּם עוֹמְדִים בּוֹ."],[3,"","שְׁאַל אָבִיךְ וְיַגֵּדְךְ – זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב הֲלֹא הוּא אָבִיךְ קָּנֶךְ. וְיַגֵּדְךְ, וְהוּא יְגַלֶּה עֹמֶק הַחָכְמָה. וּמַה הִיא? אֶלָּא כַּאֲשֶׁר שִׁשָּׁה יָמִים אֵלּוּ בָּנוּ אֶת הָעוֹלָם, לֹא בָנוּ אוֹתוֹ אֶלָּא בִּגְלָלְךְ, שֶׁתָּבא אַתָּה וּתְקַיֵּם אֶת הַתּוֹרָה. שֶׁלָּמַדְנוּ, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא – עַל תְּנַאי עָשָׂה, שֶׁכַּאֲשֶׁר יָבאוּ יִשְׂרָאֵל, אִם יְקַבְּלוּ אֶת הַתּוֹרָה – מוּטָב, וְאִם לֹא – שֶׁיַּחֲזִירֵהוּ לְתֹהוּ וָבהוּ. וּמִשּׁוּם זֶה, אֵלּוּ יְמוֹת עוֹלָם יוֹדְעִים וּמְבִינִים הַכֹּל."],[4,"","וַהֲרֵי לָמַדְנוּ, אֵלּוּ עַנְפֵי הָאִילָן אֵיךְ נֶאֱחָזִים בְּתוֹךְ הָאִילָן? וַהֲרֵי בֵּאַרְנוּ, שֶׁכַּאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַר לָהֶם לִמְמֻנֵּי הַמָּגִנִּים עַל שְׁאָר הָאֻמּוֹת, וְאַתֶּם מַה כָּתוּב? כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. שֶׁלֹּא נָתַן אוֹתָם לְשַׂר, וְלֹא לְמַלְאָךְ, וְלֹא לִמְמֻנֶּה אַחֵר, וְזֶה הָעָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל לְחֶלְקוֹ."],[5,"","בְּאֵיזְהִ מָקוֹם מָצָא אוֹתוֹ? יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁמֹן וְגוֹ'. שֶׁכָּתוּב [יהושע כד] תֶּרַח אֲבִי אַבְרָהָם וְגוֹ', וָאֶקַּח אֶת אֲבִיכֶם אֶת אַבְרָהָם וְגוֹ'. וּמִכָּאן מַנְהִיג אוֹתָם אֶת יִשְׂרָאֵל בְּכָל דּוֹר וָדוֹר וְלֹא נִפְרָד מֵהֶם וּמַנְהִיג אוֹתָם בְּרַחֲמִים. זֶהוּ שֶׁכָּתוּב [דברים לב] כְּנֶשֶׁר יָעִיר קִנּוֹ וְגוֹ'."],[6,"","כְּנֶשֶׁר יָעִיר קִנּוֹ. אָמַר רַבִּי יוֹסֵי, לֹא מָצָאנוּ מִי שֶׁמְּרַחֵם עַל בָּנָיו כַּנֶּשֶׁר הַזֶּה. וְעַל זֶה לָמַדְנוּ, כָּתוּב [יחזקאל א] וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. הַנֶּשֶׁר, הֵיכָן מְקוֹמוֹ? בְּמָקוֹם שֶׁיַּעֲקֹב עוֹמֵד. זֶהוּ שֶׁכָּתוּב [משלי ל] דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. בְּאוֹתוֹ מָקוֹם מַמָּשׁ. מַה טַּעֲמוֹ? מִשּׁוּם שֶׁהוּא מְרַחֵם עַל בָּנָיו, וּבְדִין עִם אֲחֵרִים. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג אֶת בָּנָיו כְּנֶשֶׁר זֶה."],[7,"","מַה כָּתוּב? ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר. הוּא בִּלְבַדּוֹ, שֶׁכָּתוּב [שמות יג] וַה' הֹלֵךְ לִפְנֵיהֶם וְגוֹ'. וְאֵין עִמּוֹ אֵל נֵכָר, שֶׁלֹּא הִנְהִיג לָהֶם לְיִשְׂרָאֵל לֹא מַלְאָךְ, וְלֹא מְמֻנֶּה אַחֵר, שֶׁהֵם נִקְרָאִים אֵל נֵכָר. וְזֶהוּ שֶׁאָמַר מֹשֶׁה, [שמות לג] אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה. זֶהוּ שֶׁכָּתוּב ה' בָּדָד יַנְחֶנּוּ. הוּא בִּלְבַדּוֹ, וְאֵין עִמּוֹ אֵל נֵכָר."],[8,"","אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְנַהֵג אִתָּם [בישראל] כָּךְ, עֲלֵיהֶם כָּתוּב [תהלים קלה] כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ, וְכָתוּב [שמואל א יב] כִּי לֹא יִטֹּשׁ ה' עַמּוֹ וְגוֹ'. מָה הַטַּעַם לֹא יִטֹּשׁ ה' אֶת עַמּוֹ? בַּעֲבוּר שְׁמוֹ הַגָּדוֹל, מִשּׁוּם שֶׁזֶּה בָּזֶה נִדְבָּק. וְעַל זֶה לֹא יַעֲזֹּב אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁבְּכָל מָקוֹם שֶׁהֵם נִמְצָאִים, הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהֶם, כְּמוֹ שֶׁבֵּאַרְנוּ."],[9,"","לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת [דברים לב]. אָמַר רַבִּי יוֹסֵי, כָּל אֵלּוּ הַפְּסוּקִים שֶׁכָּאן תּוֹכָחוֹת הֵם שֶׁהוֹכִיחַ אוֹתָם מֹשֶׁה לְיִשְׂרָאֵל, חוּץ מֵאוֹתוֹ שֵׁם קָדוֹשׁ שֶׁגִּלָּה בִתְחִלַּת דְּבָרָיו. אָמַר רַבִּי אַבָּא, וַאֲפִלּוּ מַה שֶּׁהוֹכִיחַ לְיִשְׂרָאֵל הוּא בִּכְלַל הַשֵּׁם הַקָּדוֹשׁ, שֶׁאֵין דָּבָר בַּתּוֹרָה שֶׁיּוֹצֵא מִכְּלַל הַשֵּׁם הַקָּדוֹשׁ, שֶׁהַתּוֹרָה כֻּלָּהּ שְׁמוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם."]]],[["וְהָנֵי קְרָאֵי יְדִיעָאן אִינּוּן. אֲבָל בְּגִין דִּשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא רָשִׁים בְּהַאי פַּרְשְׁתָּא, אִצְטְרִיכְנָא עַד הַשְׁתָּא. וְהָכָא הָא כְּתִיב, לוּ חָכְמוּ יַשְׂכִּילוּ זֹאת, זֹאת וַדַּאי, וְהָא בְּכַמָּה אֲתָר אוֹקִימְנָא הַאי, דְּאִי יִשְׂרָאֵל יִנְדְּעוּן הַאי, אֵיךְ זֹאת אֲחִידָא בְּדִינוֹי לְאִתְפָּרְעָא מִן חַיָּיבַיָּא, יָבִינוּ לְאַחֲרִיתָם, וְיִסְתָּמָרוּ לְמֶהֱוֵי בָּהּ. כְּמָה דִּכְתִּיב, (איוב כ׳:כ״ז) וְאֶרֶץ מִתְקוֹמָמָה לוֹ.","דָּבָר אַחֵר לוּ חָכְמוּ יַשְׂכִּילוּ זֹאת. דְּאִיהִי מִתְקַשְּׁרָא בְּהוּ בְּיִשְׂרָאֵל, כַּד נַטְרִין פִּקּוּדֵי אוֹרַיְיתָא, וְיַתְבִין עִמָּהּ בִּשְׁלָם, יִנְדְּעוּן דִּסְיַּיעְתָּא דְּהַאי זֹאת עִמְּהוֹן, לְאִתְפָּרְעָא מִשַּׂנְאֵיהוֹן. וְיִשְׂרָאֵל דְּאִינּוּן זְעִירִין בֵּינֵי עַמְמַיָא, יִנְדְּעוּן, אֵיכָה יִרְדּוֹף אֶחָד אֶלֶף וּשְׁנַיִם יָנִיסוּ רְבָבָה. וּמַאן גָּרִים לְהוּ. הַאי זֹאת, דְּהֲוָה בְּהוּ בִּשְׁלָם, כַּד עַבְדִּין פִּקּוּדֵי אוֹרַיְיתָא. וּלְעָלְמִין לָא אִתְעָדֵי מִנַּיְיהוּ, לְמֶעְבַּד לְהוּ נוּקְמִין.","(דברים ל״ב:ל׳) אִם לֹא כִּי צוּרָם מְכָרָם וַיְיָ' הִסְגִּירָם. מַאי טַעְמָא כִּי צוּרָם מְכָרָם. בְּגִין צוּר יְלָדְךָ תֶּשִׁי, דְּתִקּוּנִין לָא שָׁרָאן כַּדְּקָא יָאוּת בְּאַתְרַיְיהוּ. אִם לָא כִּי צוּרָם מְכָרָם. אָמַר רִבִּי יְהוּדָה דָּא אַבְרָהָם, כְּמָה דְּאוֹקִימְנָא, דְּאָמַר אַבְרָהָם יִתְחַיְּיבוּן יִשְׂרָאֵל בְּגָלוּתָא, וְלָא יֵיעֲלוּן בַּגֵיהִנָּם דִּתְרֵין אִלֵּין גָּלוּתָא וְגֵיהִנָּם, לָא יִסְבְּלוּן יִשְׂרָאֵל. וְקוּדְשָׁא בְּרִיךְ הוּא אִסְתְּכַם עַל יְדוֹי, דְּכָל זִמְנָא דִּי יְחוּבוּן יִשְׂרָאֵל, יִפְּלוּן בְּגָלוּתָא, וְיִשְׁתַּעְבְּדוּן בְּהוּ שַׂנְאֵיהוֹן. וּבְגִין כָּךְ, צוּרָם מְכָרָם וַדַּאי, וַיְיָ' הִסְגִּירָם, וְאִסְתְּכַם עַל יְדוֹי.","תַּנְיָא, אָמַר רִבִּי יְהוּדָה, מַאי טַעְמָא אוֹכַח לְהוּ מֹשֶׁה בְּהַאי שִׁירָה הָכִי, בְּגִין דְּאִינְהוּ זְמִינִין לְמֵיעַל לְאַרְעָא, וּלְאַשָׁרֵי בֵּינַיְיהוּ שְׁכִינְתָּא, וּבְגִין כָּךְ אוֹכַח לְהוּ עַל הַאי.","רִבִּי יִצְחָק אָמַר, בִּתְרֵי אַתְרֵי קוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְאוֹכָחָא לְהוּ לְיִשְׂרָאֵל, וְחָדָאן אוּמוֹת הָעוֹלָם. חַד דִּכְתִּיב, (הושע י״ב:ג׳) וְרִיב לַיְיָ' עִם יְהוּדָה וְלִפְקוֹד עַל יַעֲקֹב כִּדְרָכָיו וְגוֹ'. שַׁמְעִין אוּמוֹת הָעוֹלָם חָדָאן, אַמְרֵי, הַשְׁתָּא יִשְׁתֵּצוּן מֵעָלְמָא, כַּד חָמֵי קוּדְשָׁא בְּרִיךְ הוּא דְּאִינּוּן חַדָאן, מַה כְּתִיב בַּתְרֵיהּ. בַּבֶּטֶן עָקַב אֶת אָחִיו וְגוֹ'. כַּד שַׁמְעִין, אַמְרִין, דָּא הוּא תְּשׁוּבָה.","לְאִתְּתָא דְּהֲוָה לָהּ קְטָטָה בִּבְרָהּ, אַזְלַת לְמַקְבִּיל עָלֵיהּ דִּינָא, חָמָאת לְדַיָּינָא דָּאִין נַפְשִׁין. מִנַּיְיהוּ לְאַלְקָאָה, לְצַלְבָא, לְאוֹקְדָא, אָמְרָה וַיי מַה אַעְבִיד מִן בְּרָא. כַּד סִיֵּים דִּינָא, אָמַר לְהַהִיא אִינְתּוּ, אִימָּא, מַה אַעֲבִיד לָךְ בְּרִיךְ, אָמְרָה קוֹבְלַנִי, עכ\"מ.","(דברים ל״ב:י׳) יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ, וַדַּאי לְבָתַר עָבֵד לְכָל אִינּוּן קְלִיפִין, דִּיהוֹן כֻּלְּהוּ מִשְׁתַּעְבְּדִין לֵיהּ. עַד הָכָא הֲוָה כְּתִיב בְּהַהוּא סִפְרָא, דְּקָרְטָנָא אַסְיָא לְבָתַר הֲוָה רָשִׁים בְּהַאי קְרָא, כָּל נְטוּרָא דְּאִצְטְרִיךְ אַסְיָא חַכִּים לְמֶעְבַּד לִמְרַע דְּשָׁכִיב בְּבֵי מַרְעֵיהּ, בֵּי אֲסִירֵי דְּמַלְכָּא, לְמִפְלַח לְמָארֵי עָלְמָא.","דְּכַד אָזִיל אַסְיָא חַכִּים לְגַבֵּיהּ, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵיל יְשִׁימוֹן, מַרְעִין דְּשַׁרְיָין עָלֵיהּ, אַשְׁכַּח לֵיהּ בַּאֲסִירוּ דְּמַלְכָּא. אִי תֵּימָא הוֹאִיל וְקוּדְשָׁא בְּרִיךְ הוּא (ס\"א פקיד) יִפְקוֹד לְתַפְשָׂא לֵיהּ, דְּלָא יִשְׁתְּדַל בַּר נָשׁ אֲבַּתְרֵיהּ. לָאו הָכִי, דְּהָא דָּוִד אָמַר, (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל וְגוֹ', דָּל הַהוּא דְּשָׁכִיב בְּבֵי מַרְעֵיהּ. וְאִי אַסְיָא חַכִּים הוּא, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֵיהּ בִּרְכָאן, לְהַהוּא דְּיִשְׁתְּדַּל בֵּיהּ.","וְהַהוּא אַסְיָא, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר, בְּבֵי מַרְעֵיהּ שְׁכִיב. וּבְתֹהוּ יְלֵיל יְשִׁימוֹן, דְּאִינּוּן מַרְעִין דַּחֲקִין לֵיהּ. מַאי אִצְטְרִיךְ לֵיהּ לְמֶעְבַּד. יְסוֹבְבֶנְהוּ יְסוֹבֵב סִבּוֹת, וְיֵיתֵי עִלּוֹת, בְּגִין דְּיִמְנַע מִנֵּיהּ אִינּוּן מִלִּין דְּנַזְקִין לֵיהּ. יַקִּיז לֵיהּ, וְיַפִּיק מִנֵּיהּ דָּמָא בִּישָׁא. יְבוֹנֵנֶהוּ יִסְתְּכַּל וְיָבִין הַהוּא מַרְעָא מִמָּה הֲוֵי, וְיִסְתְּכַּל בְּגִין דְּלָא יִתְרַבֵּי עֲלוֹי, וְיַמְאִךְ לֵיהּ. לְבָתַר יִצְּרֶנְהוּ כְּאִישׁוֹן עֵינוֹ, בְּגִין דִּיְהֵא נָטִיר כַּדְּקָא יָאוּת, בְּאִינּוּן מַשְׁקֵי, בְּאִינּוּן אַסְוָותָא דְּאִצְטְרִיכוּ לֵיהּ, וְלָא יִטְעֵי (ס\"א מינייהו) בֵּינַיְיהוּ. דְּאִלְמָלֵי יִטְעֵי, אֲפִילּוּ בְּמִלָּה חַד, קוּדְשָׁא בְּרִיךְ הוּא חָשִׁיב עַל הַהוּא אַסְיָא, כְּאִלּוּ שָׁפִיךְ דָּמָא וְקַטְלֵיהּ.","בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי, דְּאַף עַל גַּב דְּהַהוּא בַּר נַשׁ אִיהוּ בְּבֵי אֲסִירֵי דְּמַלְכָּא, וְאִיהוּ אָסִיר בְּבֵי אֲסִירֵי, דְּיִשְׁתְּדַּל בַּר נַשׁ עָלֵיהּ, וִיסַיֵּיעַ לֵיהּ לְאַפָּקָא לֵיהּ מִבֵּי אֲסִירֵי. וַהֲוָה אָמַר הָכִי. קוּדְשָׁא בְּרִיךְ הוּא דָּן דִּינִין דִּבְנֵי עָלְמָא לְעֵילָּא, הֵן לַמָּוֶת הֵן לְשָׁרוּשֵׁי, הֵן לַעֲקוֹר, הֵן לַעֲנוֹשׁ נְכָסִין, וּלְאָסוּרִין. מַאן דְּאִתְחֲזֵי לַעֲנוֹשׁ נְכָסִין, נָפַל בְּבֵי מַרְעֵיהּ, וְלָא יִתְסֵּי, עַד דְּיִתֵּן כָּל מַה דְּאִתְגְּזַר עָלֵיהּ. כֵּיוָן דְּאִתְעֲנָשׁ בְּמָמוֹנֵיהּ, וְיָהִיב כָּל מַה דְּאִתְגְּזַר עָלֵיהּ, אִתְּסֵי, וְנָפַק מִבֵּי אֲסִירֵי. וְעַל דָּא אִצְטְרִיךְ לְאִשְׁתַּדְּלָא עָלֵיהּ דְּיִתֵּן עוֹנְשֵׁיהּ וְיִפּוּק."],[[0,"והני קראי ידיעאן וכו':","ואלו המקראות שביארנו עד הנה, המה ידועים לכל, אבל משום ששמו של הקב\"ה רשום בפרשה זו, נצרכנו לבארם עד עתה. וכאן, הרי כתוב, \u0003לו חכמו ישכילו זאת. זאת\u0004 ודאי, שהיא המלכות. והנה בכמה מקומות העמדנו זה, שאם ישראל ידעו את זה, איך, \u0003זאת\u0004, נאחזת בדיניה, להפרע מן הרשעים, \u0003יבינו לאחריתם\u0004, וישמרו עצמם להיות בה, דהיינו לקיים מצותיה. כמו שכתוב, וארץ, שהיא המלכות, מתקוממה לו."],[1,"ד\"א לו חכמו וגו':","פירוש אחר. לו חכמו ישכילו זאת. כש \u0003זאת\u0004, מתקשרת בישראל דהיינו בעת ששומרים מצות התורה, ויושבים עמה בשלמות, ידעו שעזרת \u0003זאת\u0004 הזו עמהם להפרע משונאיהם. וישראל שהם המעט בין העמים, ידעו, איכה ירדוף אחד אלף ושנים יניסו רבבה. ומי גרם להם. היינו זאת זו שהיתה בהם בשלמות בעת שעשו מצות התורה, ולעולם לא תסור מהם, מלעשות להם נקמות בשונאיהם."],[2,"אם לא כי וכו':","אם לא כי צורם מכרם וה' הסגירם. מהו הטעם כי צורם מכרם, משום, צור ילדך תשי, שהתקונים אינם שורים כראוי במקומם. אם לא כי צורם מכרם. א\"ר יהודה זהו אברהם, כמו שהעמדנו, שאמר אברהם יתחייבו ישראל בגלות ואל יכנסו בגיהנם, כי שנים אלו גלות וגיהנם לא יוכלו ישראל לסבול (כנ\"ל יתרו אות שנ\"ב) והקב\"ה הסכים על ידו, שכל זמן שיחטאו ישראל יפלו בגלות, ויעבדו בהם שונאיהם. ומשום זה, \u0003כי צורם מכרם\u0004, ודאי, דהיינו אברהם, שמסר אותם לגלות, \u0003וה' הסגירם\u0004. שהסכים עמו."],[3,"תניא א\"ר יהודה וכו'",": למדנו, אר\"י, מהו הטעם שכך הוכיח אותם משה בשירה זו. הוא משום שהיו עתידים ליכנס לארץ ושישרה ביניהם השכינה, ומשום זה הוכיח להם על זה."],[4,"ר' יצחק אמר וכו':","רי\"א, בב' מקומות עתיד הקב\"ה להוכיח את ישראל, ואומות העולם שמחים. אחד, שכתוב, וריב לה' עם יהודה ולפקוד על יעקב כדרכיו וגו'. שומעים אומות העולם ושמחים, אומרים עתה יכלו מן העולם. כשראה הקב\"ה שהם שמחים, מה כתוב אחריו, בבטן עקב את אחיו וגו'. כאשר שמעו זה, אומרים זה הוא תשובה, על עונות ישראל. פירוש. שתמהו כי תחילה אמר, שבא לפקוד על יעקב כדרכיו, והיה צריך להשיב על זה את העונות הרבים שעשו ישראל ולבסוף הזכיר, רק מה שיעקב חטא בהיותו בבטן. שאין עונשים על חטא כזה כלל."],[5,"לאתתא דהוה לה וכו':","שזה דומה, לאשה שהיה לה ריב עם בנה. הלכה לצעוק ולתבוע עליו דין. ראתה את הדיין שדן דיני נפשות, מהם להלקות, מהם לתליה, לשריפה, אמרה, אוי מה אעשה עם בני. כלומר, שנפל עליה פחד, פן ידון גם את בנה באחד מעונשים האלו. כשהדיין גמר את הדין, אמר לאותו אשה אמרי מה עשה לך בנך. אמרה אני קובלת עליו (חסר הסיום) ולפי הענין נראה, שאמרה שהיא קובלת עליו, על שהצר אותה בבטנה, בעת שעיברה אותו. וכמובן, שהדיין לא עשה לו כלום בעד זה."],[6,"ימצאהו בארץ מדבר ובתהו:","ודאי שאח\"כ עשה לכל אלו הקליפות, שבמדבר ושבישימון, שיהיו כולם משועבדים לישראל המקראות שעד כאן היו כתובים באותו ספר של הרופא, הנקרא קרטנא. ולאח\"כ היה רושם במקרא הזה כל השמירה, שרופא חכם צריך לעשות לחולה בבית משכבו. כלומר שמדרך הרופא לרשום לפניו תחילה את המצב, שמצא בו את החולה ואח\"כ רושם הרפואות. וכן היו מסודרים כאן באותו ספר, אלו המקראות, שמתחילה הזכיר הספר את המקראות, ימצאהו בארץ מדבר וגו', דהיינו המצב שבו נמצא החולה, ולאחר כך, היה רושם במקרא הזה שלאח\"כ, שכתוב בו, כל השמירה שרופא חכם צריך לעשות לחולה השוכב בבית חוליו, בבית אסירי המלך, דהיינו שהם חולים מבחינת מה שאינם יכולים לעבוד את אדון העולם. \u0003קרטנא\u0004 מפרש הזהר (דפוס ישן) להלן בהשמטות דף ש\"ה: ששמו היה יודאן דקסרי. וקראו את שמו אסיא קרטינאה. משום שהיה גדול על כל הרופאים ויקר בחכמה. כי קרטינאה בלשון פרסי, פירושו יקר. עכ\"ל."],[7,"דכד אזיל אסיא:","וכך היה כתוב שם בספר. כשהולך רופא חכם אל חולה, ימצאהו בארץ מדבר ובתהו יליל ישימון היינו, כי המחלות השורים עליו, מושיבים אותו בבית האסורים של המלך, במדבר בישימון, ואם תאמר, כיון שהקב\"ה צוה לתפשו בבית האסורים, לא ישתדל אדם אחריו להחזירו בתשובה. אינו כן, שהרי דוד אמר אשרי משכיל אל דל וגו'. אותו חולה השוכב בבית חוליו הוא דל. ואם חבירו רופא חכם הוא, הקב\"ה נותן ברכות לכל מי שישתדל בו."],[8,"וההוא אסיא ימצאהו וגו':","ומפרש דבריו. ורופא ההוא, \u0003ימצאהו בארץ מדבר\u0004, דהיינו ששוכב בבית חליו. \u0003ובתהו יליל ישימון\u0004, שהמחלות מצירים אותו. מה הוא צריך לעשות. היינו, \u0003יסובבנהו\u0004, יסובב סבות ויביא עלות וסבות, כדי שימנע ממנו אלו הדברים שמזיקים אותו, ויקיז ליה דם, ויוציא ממנו הדם הרע. \u0003יבוננהו\u0004, יסתכל ויבין המחלה ממה היתה, ויסתכל שלא תתרבה המחלה, וימעט אותה. ואחר כך \u0003יצרנהו כאישון עינו\u0004, כדי שיהיה נשמר כראוי באלו המשקים, ובאלו הרפואות הצריכות לו, שלא יטעה בהן. שאם יטעה אפילו בדבר אחד, וימות, הקב\"ה חושב לאותו הרופא, כאלו שפך דם והרגו."],[9,"בגין דקב\"ה בעי וכו':","משום שהקב\"ה רוצה, שאע\"פ שאותו האדם הוא בבית האסורים של המלך, והוא אסור בבית האסורים, שאינו יכול להתיר את עצמו, ישתדל עליו אדם, ויעזור לו לצאת מבית האסורים. והוי אומר כך. הקב\"ה דן דינים של בני העולם למעלה הן למות, הן לעקור אותו מן השורש, אותו ואת בניו, הן לעקור אותו שלא יהיה לו בנים, הן להענישו ברכושו, ולתת אותו בבית האסורים. מי שנגזר עליו לעונש רכוש, נופל בבית חוליו, ואינו נרפא, עד שיתן כל מה שנגזר עליו. אחר שנענש בכספו, ונתן כל מה שנגזר עליו אז הוא נרפא ויוצא מבית האסורים. וע\"כ צריכים להשתדל עליו שיתן עונשו ויצא מבית האסורים. \u0003לשרושי\u0004 פירושו לעקור אותו מן השורש אותו ואת בניו (עזרא ז)."]],[[0,"","וְאֵלּוּ הַפְּסוּקִים יְדוּעִים הֵם. אֲבָל מִשּׁוּם שֶׁשְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא רָשׁוּם בְּפָרָשָׁה זוֹ, הָיִיתִי צָרִיךְ עַד עַתָּה. וְכָאן הֲרֵי כָּתוּב, לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת, זֹּאת וַדַּאי. וַהֲרֵי בְּכַמָּה מְקוֹמוֹת בֵּאַרְנוּ זֹּאת, שֶׁאִם יִשְׂרָאֵל יֵדְעוּ אֶת זֶה אֵיךְ זֹּאת אֲחוּזָה בְדִינֶיהָ לְהִפָּרַע מִן הָרְשָׁעִים – יָבִינוּ לְאַחֲרִיתָם, וְיִשְׁתַּמְּרוּ לִהְיוֹת בָּהּ, כְּמוֹ שֶׁכָּתוּב [איוב כ] וְאֶרֶץ מִתְקוֹמָמָה לוֹ."],[1,"","דָּבָר אַחֵר לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת – שֶׁהִיא קְשׁוּרָה בָהֶם בְּיִשְׂרָאֵל. כַּאֲשֶׁר שׁוֹמְרִים מִצְווֹת הַתּוֹרָה וְיוֹשְׁבִים עִמָּהּ בְּשָׁלוֹם, יֵדְעוּ שֶׁעֶזְרָה שֶׁל זֹּאת הַזּוֹ עִמָּהֶם, לְהִפָּרַע מִשּׂוֹנְאֵיהֶם. וְיִשְׂרָאֵל, שֶׁהֵם מְעַטִּים בֵּין הָאֻמּוֹת, יֵדְעוּ אֵיכָה יִרְדֹּף אֶחָד אֶלֶף וּשְׁנַיִם יָנִיסוּ רְבָבָה. וּמִי גָרַם לָהֶם? הַזֹּאת הַזּוֹ שֶׁהָיְתָה בֵינֵיהֶם בְּשָׁלוֹם כַּאֲשֶׁר עוֹשִׂים מִצְווֹת הַתּוֹרָה, וּלְעוֹלָמִים לֹא זָזָה מֵהֶם לַעֲשׂוֹת לָהֶם נְקָמוֹת."],[2,"","אִם לֹא כִּי צוּרָם מְכָרָם וַה' הִסְגִּירָם [דברים לב]. מָה הַטַּעַם כִּי צוּרָם מְכָרָם? מִשּׁוּם שֶׁצּוּר יְלָדְךְ תֶּשִׁי, שֶׁהַתִּקּוּנִים לֹא נִמְצָאִים כְּמוֹ שֶׁצָּרִיךְ בִּמְקוֹמָם. אִם לֹא כִּי צוּרָם מְכָרָם. אָמַר רַבִּי יְהוּדָה, זֶה אַבְרָהָם, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁאָמַר אַבְרָהָם, יִתְחַיְּבוּ יִשְׂרָאֵל בְּגָלוּת וְלֹא יִכָּנְסוּ בְגֵיהִנָּם, שֶׁשְּׁנֵי אֵלּוּ – גָּלוּת וְגֵיהִנָּם – לֹא יִסְבְּלוּ יִשְׂרָאֵל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ, שֶׁכָּל זְמַן שֶׁיִּתְחַיְּבוּ יִשְׂרָאֵל, יִפְּלוּ לְגָלוּת וְיִשְׁתַּעְבְּדוּ בָהֶם שׂוֹנְאֵיהֶם. וּמִשּׁוּם זֶה צוּרָם מְכָרָם, וַדַּאי, וַה' הִסְגִּירָם, וְהִסְכִּים עַל יָדָיו."],[3,"","לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, מָה הַטַּעַם שֶׁהוֹכִיחַ לָהֶם מֹשֶׁה בַּשִּׁירָה הַזּוֹ כָּךְ? מִשּׁוּם שֶׁהֵם מְזֻמָּנִים לְהִכָּנֵס לָאָרֶץ וּלְהַשְׁרוֹת עֲלֵיהֶם שְׁכִינָה, וּמִשּׁוּם זֶה הוֹכִיחַ אוֹתָם עַל כָּךְ."],[4,"","רַבִּי יִצְחָק אָמַר, בִּשְׁנֵי מְקוֹמוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מְזֻמָּן לְהוֹכִיחַ אֶת יִשְׂרָאֵל, וְשָׂמְחוּ אֻמּוֹת הָעוֹלָם. אֶחָד – שֶׁכָּתוּב [הושע יב] וְרִיב לַה' עִם יְהוּדָה וְלִפְקֹד עַל יַעֲקֹב כִּדְרָכָיו וְגוֹ'. שָׁמְעוּ אֻמּוֹת הָעוֹלָם, שָׂמְחוּ. אָמְרוּ, עַתָּה יִכָּרְתוּ מֵהָעוֹלָם. כַּאֲשֶׁר רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֵם שְׂמֵחִים, מַה כָּתוּב אַחֲרָיו? בַּבֶּטֶן עָקַב אֶת אָחִיו וְגוֹ'. כַּאֲשֶׁר שׁוֹמְעִים, אוֹמְרִים, זוֹ הִיא תְשׁוּבָה."],[5,"","מָשָׁל לְאִשָּׁה שֶׁהָיְתָה לָהּ קְטָטָה בִּבְנָהּ, הָלְכָה לִתְבֹּעַ עָלָיו דִּין. רָאֲתָה לַדַּיָּן שֶׁדָּן דִּינֵי נְפָשׁוֹת – חֶלְקָם לְמַלְקוֹת, לִתְלִיָּה, לִשְׂרֵפָה. אָמְרָה: אוֹי, מָה אֶעֱשֶׂה מִן הַבֵּן? כַּאֲשֶׁר סִיֵּם הַדִּין, אָמַר לְאוֹתָהּ אִשָּׁה: אִמָּא, מֶה עָשָׂה לָךְ בְּנֵךְ? אָמְרָה, מִתְלוֹנֶנֶת, עכ\"מ."],[6,"","יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ. וַדַּאי לְבַסּוֹף עָשָׂה לְכָל אוֹתָן קְלִפּוֹת שֶׁיִּהְיוּ כֻלָּן מִשְׁתַּעְבְּדוֹת לוֹ. עַד כָּאן הָיָה כָתוּב בְּאוֹתוֹ סֵפֶר שֶׁל קַרְטָנָא הָרוֹפֵא. לְבַסּוֹף הָיָה רָשׁוּם בְּזֶה הַפָּסוּק, כָּל שְׁמִירָה שֶׁנִּצְרָךְ רוֹפֵא חָכָם לַעֲשׂוֹת לְחוֹלֶה שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ, בֵּית אֲסִירֵי הַמֶּלֶךְ – לַעֲבֹד לַאֲדוֹן הָעוֹלָם!"],[7,"","שֶׁכַּאֲשֶׁר הוֹלֵךְ רוֹפֵא חָכָם אֶצְלוֹ, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁמֹן, מַחֲלוֹת הַשּׁוֹרוֹת עָלָיו. מוֹצֵא אוֹתוֹ בְּמַאֲסַר הַמֶּלֶךְ. אִם תֹּאמַר, הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא [פוקד] יִפְקֹד לִתְפֹּס אוֹתוֹ, שֶׁלֹּא יִשְׁתַּדֵּל אָדָם אַחֲרָיו – לֹא כָּךְ, שֶׁהֲרֵי אָמַר דָּוִד, [תהלים מא] אַשְׁרֵי מַשְׂכִּיל אֶל דָּל וְגוֹ'. דַּל הוּא אוֹתוֹ שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ. וְאִם רוֹפֵא חָכָם הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ בְּרָכוֹת לְאוֹתוֹ שֶׁיִּשְׁתַּדֵּל בּוֹ."],[8,"","וְאוֹתוֹ רוֹפֵא, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר, בְּבֵית חָלְיוֹ שׁוֹכֵב. וּבְתֹהוּ יְלֵל יְשִׁמֹן, שֶׁאוֹתָן מַחֲלוֹת מְצֵרוֹת לוֹ. מַה צָּרִיךְ לוֹ לַעֲשׂוֹת? יְסוֹבְבֶנְהוּ – יְסוֹבֵב סִבּוֹת וְיָבִיא עִלּוֹת כְּדֵי שֶׁיִּמְנַע מִמֶּנּוּ אוֹתָם דְּבָרִים שֶׁמַּזִּיקִים לוֹ. יַקִּיז לוֹ, וְיוֹצִיא מִמֶּנּוּ דָם רַע. יְבוֹנְנֵהוּ – יִסְתַּכֵּל וְיָבִין אוֹתוֹ חוֹלֶה מִמַּה הָיָה, וְיִסְתַּכֵּל כְּדֵי שֶׁלֹּא יִכְבַּד עָלָיו וִימַעֵט אוֹתוֹ. לְבַסּוֹף – יִצְּרֶנְהוּ כְּאִישׁוֹן עֵינוֹ, כְּדֵי שֶׁיִּהְיֶה שָׁמוּר כְּמוֹ שֶׁצָּרִיךְ בְּאוֹתָם מַשְׁקִים, בְּאוֹתָן רְפוּאוֹת שֶׁצְּרִיכוֹת לוֹ, וְלֹא יִטְעֶה [מהם] בֵּינֵיהֶן. שֶׁאִם יִטְעֶה אֲפִלּוּ בְדָבָר אֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא חוֹשֵׁב עַל אוֹתוֹ רוֹפֵא כְּאִלּוּ שָׁפַךְ דָּמִים וַהֲרָגוֹ."],[9,"","מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה, שֶׁאַף עַל גַּב שֶׁאוֹתוֹ אָדָם הוּא בְּבֵית אֲסִירֵי הַמֶּלֶךְ וְהוּא אָסוּר בְּבֵית הָאֲסוּרִים, שֶׁיִּשְׁתַּדֵּל אָדָם עָלָיו וְיַעֲזֹּר לוֹ לְהוֹצִיאוֹ מִבֵּית הָאֲסוּרִים. וְהָיָה אוֹמֵר כָּךְ: הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן דִּינִים שֶׁל בְּנֵי הָעוֹלָם לְמַעְלָה, הֵן לְמָוֶת, הֵן לְשָׁרְשׁוֹ, הֵן לַעֲקֹר, הֵן לַעֲנֹשׁ בִּנְכָסָיו, וְלֶאֱסֹר אוֹתוֹ. מִי שֶׁנִּרְאֶה לַעֲנֹשׁ נְכָסִים, נוֹפֵל בְּבֵית חָלְיוֹ, וְלֹא יִתְרַפֵּא עַד שֶׁיִּתֵּן כָּל מַה שֶּׁנִּגְזַר עָלָיו. כֵּיוָן שֶׁנֶּעֱנָשׁ בְּמָמוֹנוֹ וְנוֹתֵן כָּל מַה שֶּׁנִּגְזַר עָלָיו, יִתְרַפֵּא, וְיוֹצֵא מִבֵּית הָאֲסוּרִים. וְעַל זֶה צָרִיךְ לְהִתְעַסֵּק עִמּוֹ שֶׁיִּתֵּן עָנְשׁוֹ וְיֵצֵא."]]],[["מַאן דְּיִתְחֲזֵי לְשָׁרוּשֵׁי, יִתְפְסוּן לֵיהּ, וְיָהֲבֵי לֵיהּ בְּבֵי אֲסִירֵי, עַד דְּיִשְׁתְּרַשׁ מִכֹּלָּא. וּלְזִמְנִין דְּיִשְׁתְּרַשׁ מִשַּׁיְיפֵי, אוֹ מֵחַד מִנַּיְיהוּ, וּלְבָתַר יַפְּקוּן לֵיהּ מִבֵּי אֲסִירֵי. מַאן דְּיִתְחֲזֵי לַמָוֶת, הָכִי הוּא, דְּאִילּוּ יִתֵּן כָּל כּוּפְרָא, וְכָל מָמוֹנָא דְּעָלְמָא לָא יִשְׁתְּזִיב.","וְעַל דָּא אִצְטְרִיךְ לְאַסְיָא חַכִּים, לְאִשְׁתַּדְּלָא עָלֵיהּ, אִי יָכִיל לְמֵיהַב לֵיהּ אַסְוָותָא מִן גּוּפָא, יָאוּת. וְאִי לָאו, יִתֵּן לֵיהּ אַסְוָותָא לְנִשְׁמָתֵיהּ, וְיִשְׁתְּדַל עַל אַסְוָותָא דְּנִשְׁמְתָא. וְדָא הוּא אַסְיָא דְקוּדְשָׁא בְּרִיךְ הוּא יִשְׁתְּדַל עָלֵיהּ בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי.","אָמַר רִבִּי אֶלְעָזָר, עַד הַשְׁתָּא לָא שְׁמַעְנָא מֵאַסְיָא דָּא, וּמִסִּפְרָא דָּא. בַּר מִזִּמְנָא חֲדָא, דְּאָמַר לִי טַיְּיעָא חֲדָא, דְּשָׁמַע לַאֲבוֹי, דְּאַסְיָא חַד הֲוָה בְּיוֹמוֹי, דְּכַד הֲוָה מִסְתְּכַּל בְּבַּר נָשׁ, כַּד אִיהוּ בְּבֵי מַרְעֵיהּ, הֲוָה אָמַר, דָּא חַי וְדָא מֵת. וַהֲווּ אַמְרִין עָלֵיהּ דְּהוּא זַכָּאָה קְשׁוֹט, דְּחִיל חַטָּאָה. וְכָל מַה דְּלָא יָכִיל (אצ\"ל למזבן) לְמִדְבַּק מַה דְּאִצְטְרִיךְ, אִיהוּ הֲוָה קָנֵי, וְיָהִיב מִדִּילֵיהּ. הֲוָה אַמְרִין, דְּלֵית חַכִּים בְּעָלְמָא כְּגִינֵיהּ. וּבִצְלוֹתֵיהּ הֲוָה עָבִיד יַתִּיר, מִמָּה דְּהֲוָה עָבִיד בִּידוֹי. וּכְדְדָמֵי לָן, דָּא הֲוָה הַהוּא אַסְיָא.","אָמַר הַהוּא טַיְּיעָא, וַדַּאי סִפְרָא דִּילֵיהּ בִּידִי אִיהוּ, דְּקָא יָרִיתְנָא מֵאָבִי אַבָּא, וְכָל מִלּוֹי דְּהַהוּא סִפְרָא, כֻּלְּהוּ אִתְיַיסְּדוּן עַל רָזִין דְּאוֹרַיְיתָא, וְרָזִין סְתִימִין אַשְׁכַּחְנָא בֵּיהּ, וּמִלִּין דְּאַסְוָּותָא סַגִּיאִין, דְּאִיהוּ אָמַר דְּלָא יָאוּת לְמִפְעַל לוֹן, בַּר (אי) אִיהוּ דְּחִיל חַטָּאָה.","וְאִינּוּן מִמַּה דְּהֲוָה עָבִיד בִּלְעָם, דְּהֲוָה לָחִישׁ לְחִישִׁין עַל מְרָע, וַהֲוָה אָמַר בְּפוּמוֹי וְאִתְסֵּי מִיַּד. וְכֻלְּהוּ בָּרִיר לוֹן בְּהַהוּא סִפְרָא. וְאָמַר, דָּא אָסוּר, וְדָא מוּתָּר לְמַאן דִּדְחִיל חַטָּאָה. בְּגִין דְּמַרְעִין סַגִּיאִין אָמַר, דְּתַלְיָיא אַסְוָותָא דִּלְהוֹן, בִּלְחִישׁוּ דְּפוּמָא. וְאִינּוּן מִסִּטְרָא דְּנָחָשׁ, וּמִנְּהוֹן מִסִּטְרָא דְּקֶסֶם. וְכָל אִינּוּן דְּאָסוּר לוֹמַר בְּפוּמָא, וְאָסוּר לְמֶעְבַּד בְּעוֹבָדָא, הֲוָה אָמַר. עַד דְּאַשְׁכַּחְנָא עַל מַרְעִין יְדִיעָאן דְּאִצְטְרִיךְ לוֹמַר כַּךְ. וּלְנַדּוּיֵי בְּנִדּוּי וּבְשַׁמָתָא, עַל הַהוּא מְרָע. וְאִיהוּ תַּוָּוהָא סַגִּי לְגַבָּן.","חַדֵי רִבִּי אֶלְעָזָר, וְחַדוּ חַבְרַיָּיא. אָמַר רִבִּי אֶלְעָזָר, אִי הַהוּא סִפְרָא הֲוָה לְגַבָּן נֶחְמֵי מַה אִיהוּ אָמַר. אֲנָא אִמְסַר בִּמְסִירָה, עַל מְנַת לְאַחְזָאָה לְבוּצִינָא קַדִישָׁא. וְתָנֵינָן, אָמַר רִבִּי אֶלְעָזָר, הַהוּא סִפְרָא הֲוָה בִּידִי תְּרֵיסָר יַרְחֵי, וְאַשְׁכַּחְנָא בֵּיהּ נְהוֹרִין עִלָּאִין וְיַקִירִין. כַּד מָטֵינָא לְאִינּוּן רָזִין דְּהֲוָה מִבִּלְעָם תַּוַּוהְנָא.","יוֹמָא חַד לָחִישְׁנָא בַּאֲתָר חַד, וַהֲווּ אַתְוָון סַלְקָן וְנַחְתָּן. עַד דַּחֲמֵינָא בְּחֶלְמָא, וְאָמַר לִּי, מַה לָךְ לְמֵיעַל בִּתְחוּמָא דְּלָא דִּילָךְ, וְלָא אִצְטְרִיךְ לָךְ. אִתְּעַרְנָא, וְאַבְאִישׁ קַמָּאי, עַל רָזִין סְתִימִין דַּהֲווֹ תַּמָּן. שָׁדַרְנָא לְהַהוּא יוּדָאִי, וְרִבִּי יוֹסֵי בַּרִבִּי יְהוּדָה שְׁמֵיהּ, וְיָהִיבְנָא לֵיהּ סִפְרָא.","וּבְרָזִין דְּבִלְעָם אַשְׁכַּחְנָא, מֵאִינּוּן שְׁמָהָן דְּמַלְאָכִין דְּשָׁדַר לֵיהּ בָּלָק, וְלָא הֲווֹ מִסְתַּדְּרָן עַל תִּקּוּנַיְיהוּ כַּדְּקָא יָאוּת. אֲבָל כַּמָה זִינֵי אַסְוָותָא אַשְׁכַּחְנָא בֵּיהּ, דְּקָא מִתְתַּקְּנֵי עַל תִּקּוּנֵי אוֹרַיְיתָא, וְרָזִין סְתִימִין דִּילָהּ. וַחֲמֵינָא דְּאִינּוּן בַּחֲסִידוּתָא. וּצְלוֹתִין וּבָעוּתִין לְּקוּדְשָׁא בְּרִיךְ הוּא. וְאִי תֵּימָא, דְּהֲוָה עָבִיד אַסְוָותָא בִּפְסוּקֵי אוֹרַיְיתָא, אוֹ בְּרָזִין דְּאוֹרַיְיתָא. חַס וְשָׁלוֹם. אֶלָּא הֲוָה אָמַר רָזִין דְּאוֹרַיְיתָא, וְעַל הַהוּא רָזָא אַפִּיק רָזִין דְּאַסְוָּותָא, דְּלָא חֲמֵינָא כְּהַהוּא גַּוְונָא לְעָלְמִין. אֲמֵינָא בְּרִיךְ רַחֲמָנָא, דְּאַחְכִּים לִבְנֵי נָשָׁא מֵחָכְמָתָא דִּלְעֵילָּא.","וּמֵאִינּוּן מִלִּין דְּבִלְעָם נָסִיבְנָא, וַחֲמֵינָא בְּהוּ דְּלָא הֲוָה בְּעָלְמָא חַכִּים בַּחֲרָשִׁין כְּגִינֵיהּ. אֲמֵינָא, בְּרִיךְ רַחֲמָנָא דְּבִטֵּל מֵעָלְמָא חַרְשִׁין, דְּלָא יִטְעוּן בְּנֵי נָשָׁא מִבָּתַר דַּחַלְתָּא דְקוּדְשָׁא בְּרִיךְ הוּא יִתְבָּרַךְ וְיִתְעַלֶּה שְׁמוֹ אָמֵן. (ע\"כ). (מכאן חזור לפרשת בלק, אמר רבי אלעזר, בלעם חייבא, מאן קטיל ליה וכו', דף קצ\"ג ע\"ב) בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן."],[[0,"מאן דיתחזי לשרושי כו':","מי שנגזר עליו לעקרו מן השורש. תופסים אותו ונותנים אותו בבית האסורים עד שנעקר מכל. דהיינו עד שימות הוא ובניו. ולפעמים נעקר מאבריו או מאחד מהם, ובזה מתכפר לו, וא\"כ מוציאים אותו מבית האסורים. מי שנגזר עליו למות. כך הוא. שמת. ואלו יתן כל כפר וכל כסף שבעולם, אינו ניצול."],[1,"ועל דא אצטריך וכו':","וע\"כ צריך לרופא חכם, שישתדל עליו, אם יכול לתת לו רפואת הגוף, טוב. ואם לא, יתן לו רפואה לנשמתו, וישתדל על רפואת הנשמה. וזה הוא הרופא, שהקב\"ה ישתדל עליו לברכו בעולם הזה ובעולם הבא. (ע\"כ היה כתוב בספרו של הרופא קרטנא הנ\"ל)."],[2,"א\"ר אלעזר עד וכו':","אר\"א, עד עתה לא שמעתי מרופא הזה, קרטנא, ומספר הזה. חוץ מפעם אחת, שאמר לי סוחר אחד, ששמע מאביו, שרופא אחד היה בימיו, שבשעה שהיה מסתכל באדם כשהוא בבית חוליו, היה אומר, זה חי וזה מת. והיו אומרים עליו שהוא צדיק אמת ירא חטא. וכל מה שהחולה לא היה יכול להשיג מה שצריך, היה הוא קונה ונותן משלו. והיו אומרים שאין חכם בעולם כמוהו. ובתפלתו היה עושה יותר, ממה שהיה עושה בידיו. וכנראה לנו, שזה היה אותו הרופא, קרטנא."],[3,"אמר ההוא טייעא וכו':","אמר אותו סוחר, ודאי שהספר שלו, של אותו הרופא, הוא בידי, שירשתי אותו מאבי אבא, וכל דבריו של אותו ספר, כולם נתיסדו על סודות התורה, וסודות סתומים מצאתי בו. ודברי רפואה הרבה, שהוא אמר עליהם שאינו ראוי לפעול עמהם חוץ אם הוא ירא חטא."],[4,"ואינון ממה דהוה וכו':","והם, הרפואות הכתובים שם, הם ממה שהיה עושה בלעם, שהיה לוחש לחשים על המחלה, והיה אומר בפיו, ומיד נתרפא. וכולם מבוררים באותו ספר, ואומר זה אסור להשתמש בו, וזה מותר להשתמש בו למי שהוא ירא חטא. כי מחלות הרבה, אמר, שהרפואה שלהן תלויה בלחש הפה. והן מצד \u0003נחש\u0004 (הנון והח' פתוחות) ומהן מצד \u0003קסם\u0004 וכל אלו שאסור לומר בפה, ואסור לעשות מעשה, היה אומר שם. עד שמצאתי על מחלות ידועות שצריך לומר כך, ולנדות בנדוי וחרם, על אותה מחלה. והוא פליאה גדולה לנו."],[5,"חדי ר' אלעזר וכו':","שמח ר' אלעזר ושמחו החברים. א\"ר אלעזר, אם יהיה אצלנו אותו ספר נראה מה הוא אומר. ואני אמסור במסירה, כלומר שימסור לו הבטחה, על מנת להראות למאור הקדוש. לאביו רשב\"י. ולמדנו, א\"ר אלעזר, אותו ספר היה בידי י\"ב חודש, ומצאתי בו אורות עליונים ויקרים, כשהגעתי לאלו הסודות שהיו מבלעם נפלאתי."],[6,"יומא חד לחישנא וכו':","יום אחד לחשתי במקום אחד, והיו האותיות עולות ויורדות. עד שראיתי בחלום, ואמר לי, מה לך להכנס בגבול שאינו שלך. ואינו צריך לך. והקיצותי. והיה רע לפני, להפרד מן הספר, משום סודות הסתומים שהיו בו. שלחתי אל אותו יהודי, ור' יוסי בר' יהודה שמו, ונתתי לו את הספר."],[7,"וברזין דבלעם אשכחנא וכו':","ובסודות של בלעם מצאתי מאלו שמות המלאכים, ששלח אליו בלק, ולא היו מסודרים על תקונם כראוי. אבל כמה מיני רפואה מצאתי בו, בספר הנ\"ל, שהם מתוקנים על תקוני התורה, ועל הסודות הסתומים שבה וראיתי שהם בחסידות, ותפלות ובקשות להקב\"ה. \u0003ואם תאמר שהיה עושה רפואה בדברי תורה, או בסודות התורה, חס ושלום, כי אסור לעשות כן,\u0004 אלא היה אומר סודות התורה, ועל פי סוד ההוא היה ממציא סודות של רפואה כאלו, שמעולם לא ראיתי כמוהם. אמרתי ברוך הרחמן, שהחכים את בני אדם, מן החכמה שלמעלה."],[8,"ומאינון מלין דבלעם וכו':","ומאלו הדברים של בלעם לקחתי, וראיתי בהם, שלא היה בעולם חכם בכשפים כמוהו. אמרתי, ברוך הרחמן שביטל הכשפים מן העולם, שלא יטעו ויסירו בני אדם מאחר יראתו של הקב\"ה, יתעלה ויתברך שמו, אמן. ברוך ה' לעולם אמן ואמן. ימלוך ה' לעולם אמן ואמן."]],[[0,"","מִי שֶׁרָאוּי לְשָׁרְשׁוֹ, יִתְפְּסוּ אוֹתוֹ, וְיִתְּנוּ אוֹתוֹ בְּבֵית הָאֲסוּרִים עַד שֶׁיִּשְׁתָּרֵשׁ מֵהַכֹּל. וְלִפְעָמִים מִשְׁתָּרֵשׁ בְּאֵיבָרָיו אוֹ מֵאֶחָד מֵהֶם, וּלְבַסּוֹף יוֹצִיאוּ אוֹתוֹ מִבֵּית הָאֲסוּרִים. מִי שֶׁרָאוּי לְמָוֶת – כָּךְ הוּא, שֶׁאִלּוּ יִתֵּן כָּל הַכֹּפֶר וְכָל מָמוֹן שֶׁבָּעוֹלָם, לֹא יִנָּצֵל."],[1,"","וְעַל זֶה צָרִיךְ לְרוֹפֵא חָכָם שֶׁיַּעֲסֹק בִּרְפוּאָתוֹ. אִם יָכוֹל לָתֵת לוֹ רְפוּאָה מִן הַגּוּף – מוּטָב, וְאִם לֹא – יִתֵּן לוֹ רְפוּאָה לְנִשְׁמָתוֹ, וְיִשְׁתַּדֵּל בִּרְפוּאַת נִשְׁמָתוֹ. וְזֶהוּ רוֹפֵא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁתַּדֵּל עָלָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[2,"","אָמַר רַבִּי אֶלְעָזָר, עַד עַתָּה לֹא שָׁמַעְתִּי מֵרוֹפֵא זֶה וּמִסֵּפֶר זֶה, חוּץ מִפַּעַם אַחַת שֶׁאָמַר לִי סוֹחֵר אֶחָד, שֶׁשָּׁמַע לְאָבִיו שֶׁרוֹפֵא אֶחָד הָיָה בְיָמָיו, שֶׁכַּאֲשֶׁר הָיָה מִסְתַּכֵּל בְּבֶן אָדָם כַּאֲשֶׁר הוּא בְּבֵית חָלְיוֹ, הָיָה אוֹמֵר, זֶה חַי וְזֶה מֵת. וְהָיוּ אוֹמְרִים עָלָיו שֶׁהוּא צַדִּיק אֲמִתִּי, יְרֵא חֵטְא, וְכָל מַה שֶּׁלֹּא יָכֹל לְהַשִּׂיג מַה שֶּׁנִּצְרָךְ, הוּא הָיָה קוֹנֶה וְנוֹתֵן מִשֶּׁלּוֹ. וְהָיוּ אוֹמְרִים שֶׁאֵין חָכָם בָּעוֹלָם כָּמוֹהוּ, וּבִתְפִלָּתוֹ הָיָה עוֹשֶׂה יוֹתֵר מִמַּה שֶּׁהָיָה עוֹשֶׂה בְיָדָיו. וְכִמְדֻמֶּה לָנוּ, זֶה הָיָה אוֹתוֹ רוֹפֵא."],[3,"","אָמַר אוֹתוֹ סוֹחֵר, וַדַּאי סִפְרוֹ בְיָדִי הוּא, שֶׁיָּרַשְׁתִּי אוֹתוֹ מֵאֲבִי אַבָּא, וְכָל דְּבָרָיו שֶׁל אוֹתוֹ סֵפֶר, כֻּלָּם מְיֻסָּדִים עַל סוֹדוֹת הַתּוֹרָה, וְסוֹדוֹת נֶעְלָמִים מָצָאתִי בוֹ וּדְבָרִים שֶׁל רְפוּאָה רַבִּים, שֶׁהוּא אָמַר שֶׁלֹּא רָאוּי לַעֲשׂוֹת אוֹתָם חוּץ [אם] הוּא יְרֵא חֵטְא."],[4,"","וְהֵם מִמַּה שֶּׁהָיָה עוֹשֶׂה בִּלְעָם, שֶׁהָיָה לוֹחֵשׁ לְחָשִׁים עַל חוֹלֶה, וְהָיָה אוֹמֵר בְּפִיו וּמִתְרַפֵּא מִיָּד. וְכֻלָּם מְבָרֵר אוֹתָם בְּאוֹתוֹ סֵפֶר. וְאָמַר, זֶה אָסוּר, וְזֶה מֻתָּר לְמִי שֶׁיְּרֵא חֵטְא. מִשּׁוּם שֶׁחֳלָאִים רַבִּים אָמַר שֶׁתְּלוּיָה רְפוּאָתָם בִּלְחִישַׁת הַפֶּה. וְאֵלּוּ מִצַּד הַנָּחָשׁ, וּמֵהֶם מִצַּד שֶׁל קֶסֶם. וְכָל אוֹתָם שֶׁאָסוּר לוֹמַר בַּפֶּה וְאָסוּר לַעֲשׂוֹת בְּמַעֲשֶׂה הָיָה אוֹמֵר. עַד שֶׁמָּצָאתִי עַל חֳלָאִים יְדוּעִים שֶׁצָּרִיךְ לוֹמַר כָּךְ, וּלְנַדּוֹת בְּנִדּוּי וּבְשַׁמְתָּא עַל אוֹתוֹ חֹלִי, וְהוּא תְמִיהָה גְדוֹלָה אֶצְלִי."],[5,"","שָׂמַח רַבִּי אֶלְעָזָר, וְשָׂמְחוּ הַחֲבֵרִים. אָמַר רַבִּי אֶלְעָזָר, אִם אוֹתוֹ סֵפֶר הָיָה אֶצְלֵנוּ, הָיִינוּ רוֹאִים מַה הוּא אוֹמֵר. אֲנִי אֶמְסֹר בִּמְסִירָה עַל מְנָת לְהַרְאוֹת לַמְּנוֹרָה הַקְּדוֹשָׁה. וְלָמַדְנוּ, אָמַר רַבִּי אֶלְעָזָר, אוֹתוֹ הַסֵּפֶר הָיָה בְיָדִי שְׁנֵים עָשָׂר חֹדֶשׁ, וּמָצָאתִי בוֹ אוֹרוֹת עֶלְיוֹנוֹת וַחֲשׁוּבִים. כַּאֲשֶׁר הִגַּעְתִּי לְאוֹתָם סוֹדוֹת שֶׁהָיוּ מִבִּלְעָם, תָּמַהְתִּי."],[6,"","יוֹם אֶחָד לָחַשְׁתִּי בְּמָקוֹם אֶחָד, וְהָיוּ הָאוֹתִיּוֹת עוֹלוֹת וְיוֹרְדוֹת. עַד שֶׁרָאִיתִי בַחֲלוֹם וְאָמַר לִי, מַה לְּךְ לְהִכָּנֵס בִּתְחוּם שֶׁאֵינוֹ שֶׁלְּךְ וְשֶׁאֵינוֹ נִצְרָךְ לְךְ? הִתְעוֹרַרְתִּי. וְרַע בְּעֵינַי עַל סוֹדוֹת הַסְּתוּמִים שֶׁהָיוּ שָׁם. שָׁלַחְתִּי לְאוֹתוֹ יְהוּדִי, וְרַבִּי יוֹסֵי בְּרַבִּי יְהוּדָה שְׁמוֹ, וְנָתַתִּי לוֹ אֶת הַסֵּפֶר."],[7,"","וּבַסּוֹדוֹת שֶׁל בִּלְעָם מָצָאתִי מֵאוֹתָם שֵׁמוֹת שֶׁל מַלְאָכִים שֶׁשָּׁלַח לוֹ בָּלָק, וְלֹא הָיוּ מִסְתַּדְּרִים עַל תִּקּוּנָם כְּמוֹ שֶׁצָּרִיךְ. אֲבָל כַּמָּה מִינֵי רְפוּאָה מָצָאתִי בוֹ שֶׁהֵם מְתֻקָּנִים עַל תִּקּוּנִי הַתּוֹרָה וְסוֹדוֹת סְתוּמִים שֶׁלָּהּ. וְרָאִיתִי שֶׁהֵם בַּחֲסִידוּת, וּתְפִלּוֹת וּבַקָּשׁוֹת לְהַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִם תֹּאמַר שֶׁהָיָה עוֹשֶׂה רְפוּאָה בִּפְסוּקֵי הַתּוֹרָה אוֹ בְסוֹדוֹת הַתּוֹרָה – חַס וְשָׁלוֹם. אֶלָּא הָיָה אוֹמֵר סוֹדוֹת הַתּוֹרָה, וְעַל אוֹתוֹ סוֹד הוֹצִיא סוֹדוֹת שֶׁל רְפוּאָה שֶׁלֹּא רָאִיתִי בְּאֹפֶן זֶה לְעוֹלָם. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁהֶחְכִּים לִבְנֵי אָדָם מֵחָכְמָה שֶׁל מַעְלָה."],[8,"","וּמֵאֵלּוּ הַדְּבָרִים שֶׁל בִּלְעָם לָקַחְתִּי, וְרָאִיתִי בָהֶם שֶׁלֹּא הָיָה בָעוֹלָם חָכָם בְּכִשּׁוּפִים כְּדֻגְמָתוֹ. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁבִּטֵּל מֵהָעוֹלָם הַכִּשּׁוּפִים, שֶׁלֹּא יִטְעוּ בְּנֵי אָדָם מֵאַחַר יִרְאָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יִתְבָּרַךְ וְיִתְעַלֶּה שְׁמוֹ אָמֵן."]]]]};
